def t(cle, **kw):
    """Texte dans la langue courante (retombe sur le français si la clé manque)."""
    s = TEXTES.get(LANGUE, TEXTES["fr"]).get(cle)
    if s is None:
        s = TEXTES["fr"].get(cle, cle)
    return s.format(**kw) if kw else s


class TexteCle(str):
    """Texte déjà traduit, qui garde sa clé (l'historique le retraduit si on change de langue)."""
    cle = None
    params = None


def tk_(cle, **kw):
    r = TexteCle(t(cle, **kw))
    r.cle, r.params = cle, {k: v for k, v in kw.items() if isinstance(v, (str, int, float))}
    return r


def fixer_langue(code):
    global LANGUE
    LANGUE = code if code in TEXTES else "fr"


def detecter_langue():
    """Langue du Mac : français si le réglage système commence par « fr », anglais sinon."""
    try:
        r = subprocess.run(["defaults", "read", "-g", "AppleLanguages"], capture_output=True,
                           text=True, timeout=3)
        m = re.search(r'"?([A-Za-z]{2,3})(?:[-_][A-Za-z0-9]+)?"?\s*[,)]?', r.stdout.split("\n", 1)[-1])
        if r.returncode == 0 and m:
            return "fr" if m.group(1).lower() == "fr" else "en"
    except (OSError, subprocess.SubprocessError):
        pass
    return "fr"

