# ----------------------------------------------------------------------
# Journal d'erreurs : ippilot.log (dans le dossier de données). Remplace les « except: pass » muets.
# Un même endroit du code n'est noté qu'une fois par minute (pour ne pas inonder le fichier en pleine animation).
# ----------------------------------------------------------------------
_LOG = logging.getLogger("ippilot")
_LOG_PRET = [False]
_LOG_VUS = {}


def _log_init():
    if _LOG_PRET[0]:
        return
    _LOG_PRET[0] = True
    try:
        os.makedirs(DOSSIER, exist_ok=True)
        h = logging.handlers.RotatingFileHandler(os.path.join(DOSSIER, "ippilot.log"), maxBytes=256 * 1024,
                                                 backupCount=2, encoding="utf-8")
        h.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s"))
        _LOG.addHandler(h)
        _LOG.setLevel(logging.INFO)
        _LOG.propagate = False
    except Exception:  # noqa: BLE001  (le journal ne doit jamais faire planter l'application)
        pass


def journal(message, *args):
    """Note un message dans ippilot.log (silencieux en cas de problème)."""
    try:
        _log_init()
        _LOG.info(message, *args)
    except Exception:  # noqa: BLE001
        pass


def journal_exc():
    """À appeler dans un bloc « except » : note l'erreur en cours (avec sa ligne), au plus une fois par minute et par endroit."""
    try:
        _type, exc, tb = sys.exc_info()
        if tb is None:
            return
        while tb.tb_next:
            tb = tb.tb_next
        cle = (tb.tb_frame.f_code.co_name, tb.tb_lineno, _type.__name__)
        maintenant = time.time()
        if maintenant - _LOG_VUS.get(cle, 0) < 60:
            return
        _LOG_VUS[cle] = maintenant
        _log_init()
        _LOG.error("%s dans %s (ligne %s) : %s", _type.__name__, cle[0], cle[1], exc, exc_info=True)
    except Exception:  # noqa: BLE001
        pass


def lien_don():
    """Lien de don (PayPal) lu dans lien_don.txt (une ligne commençant par https://) ; '' s'il n'y en a pas."""
    chemin = os.path.join(RESSOURCES, "lien_don.txt")
    try:
        with open(chemin, encoding="utf-8") as f:
            for ligne in f:
                ligne = ligne.strip()
                if ligne.startswith("https://"):
                    return ligne
    except OSError:
        pass
    return ""


def ouvrir_lien(url):
    try:
        subprocess.Popen(["open", url])
    except OSError:
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception:
            journal_exc()


def url_maj():
    """Adresse du fichier de version du site, lue dans lien_maj.txt (une ligne en https://) ; '' = vérification désactivée."""
    try:
        with open(os.path.join(RESSOURCES, "lien_maj.txt"), encoding="utf-8") as f:
            for ligne in f:
                ligne = ligne.strip()
                if ligne.startswith("https://"):
                    return ligne
    except OSError:
        pass
    return ""


def _num_version(v):
    try:
        return tuple(int(x) for x in str(v).strip().lstrip("vV").split("."))
    except ValueError:
        return ()


def _lire_adresse_maj(adresse):
    """Télécharge le petit fichier de version. Essaie d'abord Python ; si la vérification du certificat échoue (fréquent avec
    le Python de macOS tant que « Install Certificates » n'a pas été lancé), retombe sur « curl », fourni avec le Mac et qui
    utilise les certificats du système. Renvoie (texte, raison_de_l_echec)."""
    raison = ""
    try:
        import urllib.request
        req = urllib.request.Request(adresse, headers={"User-Agent": "IP-Pilot/" + VERSION})
        with urllib.request.urlopen(req, timeout=5) as r:
            return r.read(20000).decode("utf-8"), ""
    except Exception as e:  # noqa: BLE001
        raison = f"python : {type(e).__name__} {e}"[:200]
    try:
        r = subprocess.run(["/usr/bin/curl", "-fsSL", "--max-time", "6", "-A", "IP-Pilot/" + VERSION, adresse],
                           capture_output=True, timeout=10)
        if r.returncode == 0 and r.stdout:
            return r.stdout[:20000].decode("utf-8"), ""
        raison += f" | curl : code {r.returncode} {r.stderr.decode('utf-8', 'replace').strip()[:120]}"
    except Exception as e:  # noqa: BLE001
        raison += f" | curl : {type(e).__name__} {e}"[:150]
    return "", raison


def chercher_maj():
    """Interroge le site (6 s au plus). Renvoie {version, url, notes} si une version plus récente existe, sinon None.
    Silencieux pour l'utilisateur en cas de problème (pas de réseau, site absent, fichier illisible), mais la raison est
    notée dans latence.txt pour qu'on puisse comprendre pourquoi la fenêtre ne s'affiche pas."""
    adresse = url_maj()
    if not adresse:
        return None
    try:
        texte, raison = _lire_adresse_maj(adresse)
        if not texte:
            sonde_ecrire("MAJ   impossible de lire " + adresse + " (" + raison + ")")
            return None
        d = json.loads(texte)
        nouv = str(d.get("version", ""))
        if not _num_version(nouv) or _num_version(nouv) <= _num_version(VERSION):
            sonde_ecrire(f"MAJ   version du site {nouv or '?'} : pas plus récente que {VERSION}")
            return None
        lien = str(d.get("url", ""))
        if not lien.startswith("https://"):
            sonde_ecrire("MAJ   le champ « url » du fichier de version est absent ou ne commence pas par https://")
            return None
        notes = d.get("notes_" + LANGUE) or d.get("notes_fr") or d.get("notes") or ""
        sonde_ecrire(f"MAJ   nouvelle version {nouv} trouvée (vous avez {VERSION})")
        return {"version": nouv, "url": lien, "notes": str(notes)}
    except Exception as e:  # noqa: BLE001
        try:
            sonde_ecrire(f"MAJ   erreur de lecture : {type(e).__name__} {e}"[:220])
        except Exception:  # noqa: BLE001
            pass
        return None


def fenetre_maj(app, info):
    fen, corps = _fenetre_base(app, t("maj_titre"), 520, 420 if info["notes"] else 280)
    EtiquetteSerree(corps, text=t("maj_dispo", v=info["version"]), bg=CREME, fg=ENCRE, font=(F_TITRE, 20),
             wraplength=460, justify="center").pack(pady=(6, 2))
    tk.Label(corps, text=t("maj_actuelle", v=VERSION), bg=CREME, fg=GRIS_TEXTE, font=(F_TEXTE, 14)).pack()
    if info["notes"]:
        EtiquetteSerree(corps, text=info["notes"], bg=CREME, fg=ENCRE, font=(F_TEXTE, 14), wraplength=460,
                 justify="left", anchor="w").pack(fill="x", pady=(12, 0))

    def fermer(ignorer=False):
        if ignorer:
            sauver_reglage(maj_ignoree=info["version"])
        try:
            fen.destroy()
        except Exception:
            journal_exc()

    def telecharger():
        ouvrir_lien(info["url"])
        fermer()

    def bt(texte, cmd, fond, fg, **kw):
        # le bord noir est un cadre noir autour du bouton (sur Mac, le liseré d'un Label n'est pas toujours dessiné)
        cadre = tk.Frame(corps, bg=NOIR, padx=4, pady=4, cursor="pointinghand")
        b = tk.Label(cadre, text=texte, bg=fond, fg=fg, font=(F_TEXTE, 16), padx=20, pady=5, width=13,   # même largeur pour les deux
                     cursor="pointinghand")
        b.pack()
        for w_ in (b, cadre):
            w_.bind("<ButtonRelease-1>", lambda e: cmd())
        cadre.pack(**kw)
    ig = tk.Label(corps, text=t("maj_ignorer"), bg=CREME, fg=GRIS_TEXTE, font=(F_TEXTE, 12, "underline"),
                  cursor="pointinghand")
    ig.bind("<ButtonRelease-1>", lambda e: fermer(True))
    ig.pack(side="bottom", pady=(8, 0))
    bt(t("maj_plus_tard"), fermer, CREME, ENCRE, side="bottom", pady=(8, 0))
    bt(t("maj_dl"), telecharger, ROUGE, CLAIR, side="bottom", pady=(6, 0))
    fen.bind("<Escape>", lambda e: fermer())


