def charger_mesure(app):
    """Outil de développement : si IPPILOT_MESURE=1 et si ippilot_mesure.py est dans le dossier de données d'IP Pilot,
    il est chargé (mesure du retard des clics). Sans cette variable, RIEN n'est chargé : l'application n'exécute plus
    jamais un fichier trouvé au hasard dans Téléchargements, Bureau, Documents, etc."""
    if os.environ.get("IPPILOT_MESURE") != "1":
        return
    chemin = os.path.join(DOSSIER, "ippilot_mesure.py")
    if not os.path.isfile(chemin) or os.path.islink(chemin):
        journal("mesure : %s introuvable (ou lien symbolique), rien n'est chargé", chemin)
        return
    try:
        import importlib.util
        spec = importlib.util.spec_from_file_location("ippilot_mesure", chemin)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        mod.installer(app, tk, DOSSIER)
        journal("mesure : module chargé depuis %s", chemin)
    except Exception:  # noqa: BLE001
        journal_exc()


CLES_IFACE = ("interface", "mode", "ip", "masque", "routeur", "dns")


# ----------------------------------------------------------------------
# Partie « système » : parler à macOS
# ----------------------------------------------------------------------
def lancer(args, delai=None):
    """Lance une commande et renvoie (succès, texte). Sans délai précisé : 60 s au plus (une commande qui se fige ne bloque plus)."""
    if delai is None:
        delai = 60
    try:
        r = subprocess.run(args, capture_output=True, text=True, timeout=delai)
    except subprocess.TimeoutExpired:
        return False, "délai dépassé"
    except OSError as e:
        return False, str(e)
    return r.returncode == 0, (r.stdout + r.stderr).strip()


def lister_services():
    ok, out = lancer(["networksetup", "-listallnetworkservices"])
    lignes = out.splitlines()[1:]  # la 1re ligne est un message d'information
    return [l.lstrip("*").strip() for l in lignes if l.strip()]


def lire_config(service):
    return lancer(["networksetup", "-getinfo", service])[1]


def etat_compact(texte, nom):
    """Résumé court de `networksetup -getinfo` : tient dans le journal sans avoir à le faire défiler.
    Renvoie (mode, « IP … · masque …\nrouteur … »), ou None si on ne comprend pas la sortie."""
    def val(cle):
        m = re.search(r"^%s:\s*(\S+)" % cle, texte, re.M)
        return m.group(1) if m else ""
    ip, masque, routeur = val("IP address"), val("Subnet mask"), val("Router")
    if not ip:
        return None
    mode = t("etat_dhcp") if re.search(r"^(DHCP|BOOTP) Configuration", texte, re.M) else t("etat_manuel")
    lignes = [f"{t('etat_ip')} {ip}  ·  {t('etat_masque')} {masque or '—'}"]
    if routeur:
        lignes.append(f"{t('etat_routeur')} {routeur}")
    return mode, "\n".join(lignes)


def appliquer_admin(commandes):
    """Lance plusieurs commandes avec une seule demande de mot de passe."""
    shell = " && ".join(" ".join(shlex.quote(a) for a in c) for c in commandes)
    pour_applescript = shell.replace("\\", "\\\\").replace('"', '\\"')
    script = f'do shell script "{pour_applescript}" with administrator privileges'
    return lancer(["osascript", "-e", script])


# ----------------------------------------------------------------------
# Petit assistant « sans mot de passe » pour le Radar (installé une seule fois)
# ----------------------------------------------------------------------
HELPER = "/usr/local/libexec/ip_pilot_helper"
HELPER_SUDOERS = "/etc/sudoers.d/ip_pilot"
HELPER_VERSION = "3"
HELPER_SH = r"""#!/bin/sh
# IP Pilot : assistant du Radar (écoute / sondage). Ne fait que ça, sur des fichiers temporaires d'IP Pilot.
PATH=/usr/bin:/bin:/usr/sbin:/sbin
[ "$1" = version ] && { echo 3; exit 0; }
mode="$1"; dev="$2"; f="$3"; a="$4"
[ $# -ge 4 ] || exit 2
shift 4
printf '%s' "$dev" | grep -Eq '^[a-z]+[0-9]+$' || exit 2
# Un chemin n'est accepté que si son DOSSIER (une fois les liens symboliques résolus) est un dossier ippilot_* de /tmp ou
# /var/folders, appartenant à l'utilisateur qui a lancé sudo, et fermé aux autres (drwx------). Le fichier lui-même ne doit
# pas être un lien. On travaille ensuite sur le chemin résolu, jamais sur celui qu'on a reçu.
chemin_canon() {
  case "$1" in
    *..*|*[!A-Za-z0-9_./-]*) return 1;;
  esac
  d="${1%/*}"; b="${1##*/}"
  [ -n "$d" ] && [ -n "$b" ] && [ "$d" != "$1" ] || return 1
  r="$(cd "$d" 2>/dev/null && pwd -P)" || return 1
  case "$r" in
    /private/var/folders/*/ippilot_*|/var/folders/*/ippilot_*|/private/tmp/ippilot_*|/tmp/ippilot_*) ;;
    *) return 1;;
  esac
  [ -n "$SUDO_UID" ] || return 1
  info="$(ls -ldn "$r")" || return 1
  set -- $info
  case "$1" in drwx------*) ;; *) return 1;; esac
  [ "$3" = "$SUDO_UID" ] || return 1
  [ ! -L "$r/$b" ] || return 1
  printf '%s' "$r/$b"
}
f="$(chemin_canon "$f")" || exit 2
a="$(chemin_canon "$a")" || exit 2
case "$mode" in
ecouter)
  printf '%s' "$1" | grep -Eq '^[0-9]{1,3}$' || exit 2
  duree="$1"
  rm -f "$a"
  tcpdump -n -e -l -i "$dev" 'arp or (ip and (ether broadcast or ether multicast))' > "$f" 2>/dev/null &
  P=$!; i=0
  while [ $i -lt "$duree" ] && [ ! -f "$a" ]; do sleep 1; i=$((i+1)); done
  kill $P 2>/dev/null; wait $P 2>/dev/null
  chmod 644 "$f" 2>/dev/null
  exit 0;;
lldp)
  printf '%s' "$1" | grep -Eq '^[0-9]{1,3}$' || exit 2
  duree="$1"
  rm -f "$a"
  tcpdump -n -e -l -v -s 0 -c 1 -i "$dev" 'ether proto 0x88cc or ether dst 01:00:0c:cc:cc:cc' > "$f" 2>/dev/null &
  P=$!; i=0
  while [ $i -lt "$duree" ] && [ ! -f "$a" ] && kill -0 $P 2>/dev/null; do sleep 1; i=$((i+1)); done
  kill $P 2>/dev/null; wait $P 2>/dev/null
  chmod 644 "$f" 2>/dev/null
  exit 0;;
sonder)
  PL="$*"
  rm -f "$a"; : > "$f"
  cleanup() { for n in $PL; do ifconfig "$dev" -alias "$n.250" 2>/dev/null; done; }
  trap cleanup EXIT
  for n in $PL; do
    printf '%s' "$n" | grep -Eq '^[0-9]{1,3}(\.[0-9]{1,3}){2}$' || continue
    [ -f "$a" ] && break
    ifconfig "$dev" alias "$n.250" 255.255.255.0 2>/dev/null || continue
    echo "PLAGE $n" >> "$f"
    seq 1 254 | xargs -P 120 -I{} ping -c 1 -t 1 -q "$n.{}" >/dev/null 2>&1
    arp -an -i "$dev" | grep -v incomplete >> "$f"
    ifconfig "$dev" -alias "$n.250" 2>/dev/null
  done
  chmod 644 "$f" 2>/dev/null
  exit 0;;
esac
exit 2
"""


def helper_pret():
    ok, out = lancer(["sudo", "-n", HELPER, "version"], delai=10)
    return ok and out.strip() == HELPER_VERSION


def helper_installer():
    """Une seule demande de mot de passe : installe l'assistant et l'autorisation qui va avec."""
    import getpass
    import tempfile
    user = getpass.getuser()
    if not re.fullmatch(r"[A-Za-z0-9._-]+", user):
        return False, "nom d'utilisateur inattendu"
    dossier = tempfile.mkdtemp(prefix="ippilot_inst_")
    src = os.path.join(dossier, "helper")
    sud = os.path.join(dossier, "sudoers")
    with open(src, "w", encoding="utf-8") as fh:
        fh.write(HELPER_SH)
    with open(sud, "w", encoding="utf-8") as fh:
        fh.write(f"{user} ALL=(root) NOPASSWD: {HELPER}\n")
    return appliquer_admin([
        ["/bin/mkdir", "-p", "/usr/local/libexec"],
        ["/bin/cp", src, HELPER], ["/usr/sbin/chown", "root:wheel", HELPER], ["/bin/chmod", "755", HELPER],
        ["/usr/sbin/visudo", "-cf", sud],
        ["/bin/cp", sud, HELPER_SUDOERS], ["/usr/sbin/chown", "root:wheel", HELPER_SUDOERS],
        ["/bin/chmod", "440", HELPER_SUDOERS]])


def lancer_avec_helper(args, secours):
    """Lance l'assistant sans mot de passe (installé au premier usage). `secours` : commande de repli (ancienne méthode)."""
    if not helper_pret():
        ok, msg = helper_installer()
        if not ok:
            if "User canceled" in msg or "(-128)" in msg:
                return False, msg
            return appliquer_admin(secours)
    ok, msg = lancer(["sudo", "-n", HELPER] + [str(a) for a in args], delai=1200)
    if ok:
        return True, ""
    return appliquer_admin(secours)


_METHODE = None   # méthode qui a marché la dernière fois : "direct", "sudo" ou "admin"


def _sequence(commandes, prefixe=()):
    for c in commandes:
        ok, out = lancer(list(prefixe) + c, delai=30)
        if not ok:
            return False, out
    return True, ""


def executer_commandes(commandes):
    """Applique les commandes réseau en essayant d'abord SANS mot de passe :
    1) directement, 2) avec « sudo -n » (si l'autorisation a été installée), 3) avec la fenêtre de mot de passe macOS."""
    global _METHODE
    ordre = ["direct", "sudo", "admin"]
    if _METHODE in ordre:
        ordre.remove(_METHODE)
        ordre.insert(0, _METHODE)
    for methode in ordre:
        if methode == "direct":
            ok, msg = _sequence(commandes)
        elif methode == "sudo":
            ok, msg = _sequence(commandes, ("sudo", "-n"))
        else:
            ok, msg = appliquer_admin(commandes)
        if ok:
            _METHODE = methode
            return True, ""
        if methode == "admin":
            return False, msg
    return False, ""


def notifier(titre, texte):
    """Petite notification macOS (utile depuis la barre de menu)."""
    ligne = texte.splitlines()[0] if texte else ""
    script = (f"display notification {json.dumps(ligne, ensure_ascii=False)} "
              f"with title {json.dumps(titre, ensure_ascii=False)}")
    lancer(["osascript", "-e", script], delai=5)


# ----------------------------------------------------------------------
# Profils : format, validation, sauvegarde
# ----------------------------------------------------------------------
def interface_vide(service=""):
    return {"interface": service, "mode": "manuel", "ip": "",
            "masque": "255.255.255.0", "routeur": "", "dns": ""}



def normaliser(p):
    """Accepte l'ancien format (une seule interface par profil) et le convertit."""
    if "interfaces" not in p:
        p = {"nom": p.get("nom", ""), "test": "", "interfaces": [p]}
    interfaces = []
    for c in p["interfaces"]:
        if isinstance(c, dict):
            propre = {k: str(v) for k, v in c.items() if k in CLES_IFACE}
            interfaces.append({**interface_vide(), **propre})
    return {"nom": str(p.get("nom", "")), "test": str(p.get("test", "")),
            "interfaces": interfaces or [interface_vide()]}


def ip_valide(texte):
    try:
        ipaddress.IPv4Address(texte)
        return True
    except ValueError:
        return False


def normaliser_masque(texte):
    """Renvoie le masque sous la forme 255.255.255.0 (accepte aussi /24 ou 24). '' si invalide."""
    t = texte.strip().lstrip("/")
    try:
        if t.isdigit():
            return str(ipaddress.IPv4Network(f"0.0.0.0/{int(t)}").netmask) if 1 <= int(t) <= 32 else ""
        masque = ipaddress.IPv4Address(t)
        bits = format(int(masque), "032b")
        # un vrai masque = des 1 puis des 0 (255.255.255.0) ; on refuse « 0.0.0.255 » (masque inversé) et « 0.0.0.0 »
        if "01" in bits or bits.startswith("0"):
            return ""
        return str(masque)
    except ValueError:
        return ""


def valider_profil(p, autres_noms=()):
    """Renvoie un message d'erreur, ou None si tout va bien."""
    if not p["nom"]:
        return t("v_nom")
    if p["nom"] in autres_noms:
        return t("v_double")
    if not p["interfaces"]:
        return t("v_aucune")
    vues = set()
    for c in p["interfaces"]:
        nom = c["interface"]
        if not nom:
            return t("v_choisir")
        if nom in vues:
            return t("v_deux_fois", n=nom)
        vues.add(nom)
        if c["mode"] == "manuel":
            if not ip_valide(c["ip"]):
                return t("v_ip", n=nom)
            if not normaliser_masque(c["masque"]):
                return t("v_masque", n=nom)
            if c["routeur"] and not ip_valide(c["routeur"]):
                return t("v_passerelle", n=nom)
        for d in c["dns"].replace(",", " ").split():
            if not ip_valide(d):
                return t("v_dns", n=nom, d=d)
    if p["test"] and not ip_valide(p["test"]):
        return t("v_test")
    return None


def resume_profil(p):
    morceaux = []
    for c in p["interfaces"]:
        valeur = "DHCP" if c["mode"] == "dhcp" else (c["ip"] or "…")
        morceaux.append(f"{c['interface'] or '?'} · {valeur}")
    return "   ".join(morceaux)


def charger_profils():
    for chemin in (FICHIER, ANCIEN_FICHIER, ANCIEN_FICHIER2):
        try:
            with open(chemin, encoding="utf-8") as f:
                brut = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(brut, list):
            continue
        profils = [normaliser(p) for p in brut if isinstance(p, dict)]
        if chemin != FICHIER and profils:
            sauver_profils(profils)  # on garde les profils de l'ancienne version
        return profils
    return []


def ecrire_json_sur(chemin, donnees, **options):
    """Écrit dans un fichier temporaire puis le substitue : une coupure ou un arrêt en pleine écriture ne laisse jamais
    un fichier tronqué (les profils, réglages et historique sont ainsi à l'abri)."""
    os.makedirs(os.path.dirname(chemin) or ".", exist_ok=True)
    tmp = f"{chemin}.{os.getpid()}.{threading.get_ident()}.tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(donnees, f, **options)
        os.replace(tmp, chemin)
    finally:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass


def sauver_profils(profils):
    ecrire_json_sur(FICHIER, profils, indent=2, ensure_ascii=False)


def lire_reglages():
    """Petit fichier etat.json : dernier profil, langue, sons, mode nuit."""
    try:
        with open(FICHIER_ETAT, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def sauver_reglage(**valeurs):
    if "perf_niveau" in valeurs:
        _PERF_CACHE[0] = valeurs["perf_niveau"] if valeurs["perf_niveau"] in PERF_NIVEAUX else None
    d = lire_reglages()
    d.update(valeurs)
    try:
        ecrire_json_sur(FICHIER_ETAT, d, ensure_ascii=False)
    except OSError:
        pass


def lire_dernier():
    return str(lire_reglages().get("dernier", ""))


def ecrire_dernier(nom):
    sauver_reglage(dernier=nom)


def date_fichier(chemin):
    try:
        return os.path.getmtime(chemin)
    except OSError:
        return 0.0


# ----------------------------------------------------------------------
# Application d'un profil + test de connexion
# ----------------------------------------------------------------------
def dns_a_changer(svc, voulus):
    """False si les DNS demandés sont déjà ceux du Mac (on évite alors une commande lente)."""
    ok, out = lancer(["networksetup", "-getdnsservers", svc], delai=5)
    if not ok:
        return True
    actuels = [] if "aren't any" in out else out.split()
    return actuels != list(voulus)


def commandes_interface(c):
    svc = c["interface"]
    if c["mode"] == "dhcp":
        cmds = [["networksetup", "-setdhcp", svc]]
    else:
        cmd = ["networksetup", "-setmanual", svc, c["ip"],
               normaliser_masque(c["masque"]) or c["masque"]]
        if c["routeur"]:
            cmd.append(c["routeur"])
        cmds = [cmd]
    dns = c["dns"].replace(",", " ").split()
    if dns_a_changer(svc, dns):
        cmds.append(["networksetup", "-setdnsservers", svc] + (dns if dns else ["Empty"]))
    return cmds


def construire_commandes(p):
    commandes = []
    for c in p["interfaces"]:
        commandes += commandes_interface(c)
    return commandes



def resoudre_cible(p):
    """Choisit l'adresse à pinger : adresse de test indiquée, sinon passerelle indiquée. Sinon : pas de test."""
    if p["test"]:
        return p["test"], t("qui_test")
    for c in p["interfaces"]:
        if c["mode"] == "manuel" and c["routeur"]:
            return c["routeur"], t("qui_passerelle")
    return "", ""


def tester_connexion(cible, essais):
    """Ping jusqu'à `essais` fois (rapides : 0,6 s max chacun). Renvoie (joignable, millisecondes ou None)."""
    for _ in range(essais):
        ok, out = lancer(["ping", "-c", "1", "-W", "600", cible], delai=4)
        if ok:
            m = re.search(r"time[=<]([\d.]+)", out)
            return True, (float(m.group(1)) if m else None)
        time.sleep(0.3)
    return False, None


def appliquer_profil(p, progres=None):
    """Applique le profil puis teste la connexion (seulement si une passerelle ou une adresse de test est indiquée).
    Renvoie (réussi, message, ton, ms, cible) : `ms` = latence du ping (ou None), `cible` = adresse testée.
    `progres(secondes, a_un_test)` est appelée dès que le profil est appliqué (avant le test de connexion)."""
    debut = time.time()
    ok, msg = executer_commandes(construire_commandes(p))
    if not ok:
        if "User canceled" in msg or "(-128)" in msg:
            msg = t("annule")
        return False, tk_("echec", m=msg), "err", None, ""

    cible, qui = resoudre_cible(p)
    if progres:
        progres(time.time() - debut, bool(cible))
    if not cible:
        return True, tk_("sans_test", nom=p["nom"]), "ok", None, ""

    dhcp = any(c["mode"] == "dhcp" for c in p["interfaces"])
    fin = time.time() + (15 if dhcp else 8)
    joignable, ms = tester_connexion(cible, max(3, int((fin - time.time()) / 0.8)))
    if joignable:
        detail = f" ({ms:.0f} ms)" if ms is not None else ""
        return True, tk_("repond", nom=p["nom"], qui=qui, cible=cible, detail=detail), "ok", ms, cible
    return True, tk_("ne_repond_pas", nom=p["nom"], cible=cible), "warn", None, cible


def etat_interfaces(p):
    blocs = []
    for c in p["interfaces"]:
        blocs.append(f"● {c['interface']}\n{lire_config(c['interface'])}")
    return "\n\n".join(blocs)



# ----------------------------------------------------------------------
# Scanner le réseau : quels appareils répondent sur la carte choisie ?
# ----------------------------------------------------------------------
# Liste volontairement courte : seulement des préfixes d'adresse MAC dont on est sûr.
FABRICANTS = {
    "00:15:55": "CODA Audio", "00:1d:c1": "Audinate (Dante)", "00:0e:dd": "Shure", "00:1b:66": "Sennheiser",
    "00:a0:de": "Yamaha", "00:1b:92": "L-Acoustics", "08:fa:e0": "Fohhn", "00:15:64": "Behringer",
    "00:60:71": "Midas", "10:c7:3f": "Midas / Klark Teknik", "b8:27:eb": "Raspberry Pi", "dc:a6:32": "Raspberry Pi", "e4:5f:01": "Raspberry Pi",
}
MAX_HOTES = 1022          # au-delà (réseau plus grand qu'un /22), on ne scanne que le /24 de la carte
_PING_AVEC_B = [True]     # « ping -b carte » (macOS) ; on s'en passe si la commande ne le connaît pas


def mac_propre(texte):
    """0:1d:c1:a:b:c  ->  00:1d:c1:0a:0b:0c  (macOS écrit les MAC sans zéros devant)."""
    morceaux = texte.strip().lower().split(":")
    if len(morceaux) != 6:
        return ""
    try:
        return ":".join(f"{int(x, 16):02x}" for x in morceaux)
    except ValueError:
        return ""


_OUI = {}


def _charger_oui():
    """Base des fabricants (IEEE, ~35 000 préfixes) : assets/oui.csv.gz, chargée une seule fois."""
    if _OUI:
        return _OUI
    import gzip
    for dossier in (os.path.join(RESSOURCES, "assets"), RESSOURCES):
        chemin = os.path.join(dossier, "oui.csv.gz")
        if os.path.exists(chemin):
            try:
                with gzip.open(chemin, "rt", encoding="utf-8") as f:
                    for ligne in f:
                        cle, _, nom = ligne.rstrip("\n").partition(";")
                        _OUI[cle] = nom
            except (OSError, EOFError):
                pass
            break
    if not _OUI:                                # fichier absent de l'application installée : copie intégrée au programme
        try:
            import base64
            import io
            with gzip.open(io.BytesIO(base64.b64decode(_OUI_INTEGRE)), "rt", encoding="utf-8") as f:
                for ligne in f:
                    cle, _, nom = ligne.rstrip("\n").partition(";")
                    _OUI[cle] = nom
        except Exception:
            journal_exc()
    _OUI.setdefault("_charge", "")
    return _OUI


def fabricant(mac):
    """Fabricant d'après les 3 premiers octets de l'adresse MAC (le modèle précis, lui, n'y est pas)."""
    if not mac:
        return ""
    if mac[:8] in FABRICANTS:
        return FABRICANTS[mac[:8]]
    try:
        if int(mac[1], 16) & 2:                 # adresse « privée » (téléphone, ordinateur qui masque sa MAC)
            return t("mac_privee")
    except ValueError:
        return ""
    return _charger_oui().get(mac[:8].replace(":", ""), "")


def lier_pave(widget, defiler):
    """Défilement à deux doigts du pavé tactile pour une fenêtre annexe (Tk 9 n'envoie plus <MouseWheel> pour le pavé) :
    `defiler(n)` reçoit un nombre de lignes, positif vers le bas."""
    def pave(event):
        try:
            dx, dy = (float(v) for v in widget.tk.call("tk::PreciseScrollDeltas", event.delta))
        except Exception:  # noqa: BLE001
            return
        acc = getattr(widget, "_pave_acc", 0.0) + dy
        n = int(acc / 14.0)
        widget._pave_acc = acc - n * 14.0
        if n:
            defiler(-n)
    try:
        widget.bind("<TouchpadScroll>", pave, add="+")
    except tk.TclError:
        pass


def fab_aff(f):
    """Le fabricant « adresse privée » est mémorisé dans la langue du moment : on le retraduit à l'affichage."""
    return t("mac_privee") if f in ("adresse privée", "private address") else f


def hote_de(ip):
    """Nom que l'appareil annonce lui-même (DNS inverse / Bonjour), s'il y en a un : souvent le modèle."""
    import socket
    try:
        nom = socket.gethostbyaddr(ip)[0]
    except (OSError, UnicodeError):
        return ""
    nom = re.sub(r"\.(local|lan|home|localdomain|fritz\.box)$", "", nom, flags=re.I)
    if not nom or nom == ip or nom.replace("-", ".") == ip or re.fullmatch(r"(ip-)?\d+[-.]\d+[-.]\d+[-.]\d+", nom):
        return ""
    return nom[:40]


def periphérique_de(service):
    """Nom technique (en7…) de la carte dont le service réseau s'appelle `service`."""
    ok, out = lancer(["networksetup", "-listallhardwareports"], delai=8)
    port = None
    for ligne in out.splitlines():
        if ligne.startswith("Hardware Port:"):
            port = ligne.split(":", 1)[1].strip()
        elif ligne.startswith("Device:") and port == service:
            return ligne.split(":", 1)[1].strip()
    return ""


def adresse_de_carte(device):
    """(ip, masque) de la carte `device` d'après ifconfig, ou ('', '')."""
    ok, out = lancer(["ifconfig", device], delai=5)
    for ligne in out.splitlines():
        mots = ligne.split()
        if len(mots) >= 4 and mots[0] == "inet" and "netmask" in mots:
            ip = mots[1]
            brut = mots[mots.index("netmask") + 1]
            try:
                masque = str(ipaddress.IPv4Address(int(brut, 16))) if brut.startswith("0x") else brut
            except ValueError:
                continue
            return ip, masque
    return "", ""


def liste_hotes(ip, masque):
    """Les adresses à tester sur le réseau de `ip`/`masque` (sans la nôtre). Renvoie (liste, réseau, réduit)."""
    reduit = False
    reseau = ipaddress.IPv4Network(f"{ip}/{masque}", strict=False)
    if reseau.num_addresses - 2 > MAX_HOTES or (lire_reglages().get("etendue") == "bloc" and reseau.prefixlen < 24):
        reseau = ipaddress.IPv4Network(f"{ip}/24", strict=False)
        reduit = True
    return [str(h) for h in reseau.hosts() if str(h) != ip], reseau, reduit



# Niveaux de performance : (secondes entre deux scans complets, secondes entre deux « ping » rapides, ping en parallèle)
PERF_NIVEAUX = {"eco": (60, 10, 6), "normal": (30, 5, 12), "haut": (15, 2, 32)}
_PAUSE_PING = [0.0]               # les ping de fond attendent la fin de cet instant (après un clic ou un redessin)


_PERF_CACHE = [None]
CADENCE_LANGUE = {"eco": 2, "normal": 1, "haut": 1}     # l'ondulation de la langue : une image sur N (1 = 30 images/s)


def perf_niveau():
    if _PERF_CACHE[0] is None:
        n = lire_reglages().get("perf_niveau", "normal")
        _PERF_CACHE[0] = n if n in PERF_NIVEAUX else "normal"
    return _PERF_CACHE[0]


def perf():
    return PERF_NIVEAUX[perf_niveau()]


def _ping_un(ip, device, attente=700):
    """Un ping rapide ; renvoie le temps en ms si l'appareil répond, sinon None."""
    t0 = time.time()
    while attente >= 700 and _PAUSE_PING[0] > time.time() and time.time() - t0 < 1.5:   # on laisse l'interface respirer après un clic (sauf scan rapide demandé)
        time.sleep(0.04)
    cmd = ["ping", "-c", "1", "-W", str(attente)]
    if device and _PING_AVEC_B[0]:
        cmd += ["-b", device]
    ok, out = lancer(cmd + [ip], delai=3)
    if not ok and device and _PING_AVEC_B[0] and ("usage" in out.lower() or "illegal" in out.lower()
                                                   or "invalid" in out.lower() or "unknown option" in out.lower()):
        _PING_AVEC_B[0] = False
        return _ping_un(ip, device, attente)
    if not ok:
        return None
    m = re.search(r"time[=<]([\d.]+)", out)
    return float(m.group(1)) if m else 0.0


def table_arp(device):
    """{ip: mac} des appareils vus sur la carte (réponse ARP : marche même si l'appareil ignore le ping)."""
    ok, out = lancer(["arp", "-an"], delai=8)
    res = {}
    for ligne in out.splitlines():
        m = re.search(r"\((\d+\.\d+\.\d+\.\d+)\) at ([0-9a-fA-F:]+) on (\S+)", ligne)
        if not m or "incomplete" in ligne:
            continue
        ip, mac, dev = m.group(1), mac_propre(m.group(2)), m.group(3)
        if device and dev != device:
            continue
        if not mac or mac == "ff:ff:ff:ff:ff:ff" or ip.startswith(("224.", "239.", "255.")):
            continue
        res[ip] = mac
    return res


class EcouteAnnonces:
    """Écoute, sans rien envoyer, ce que les appareils annoncent quand ils se branchent (Bonjour/Dante, SSDP, Art-Net).
    Si une adresse inconnue du réseau scanné se manifeste, on demande tout de suite un scan (au plus un toutes les 3 s)."""
    GROUPES = (("224.0.0.251", 5353), ("239.255.255.250", 1900), ("", 6454))

    def __init__(self, reveil, connus):
        self.reveil, self.connus = reveil, connus          # connus() -> ensemble des adresses déjà vues
        self.stop = threading.Event()
        self.ip, self.reseau, self.dernier = "", None, 0.0
        self.signale = {}
        self.thread = None
        self._ip_ouverte = None

    def regler(self, ip, reseau_txt):
        try:
            self.reseau = ipaddress.IPv4Network(reseau_txt, strict=False)
        except ValueError:
            return
        self.ip = ip
        if self.thread is None and not self.stop.is_set():
            self.thread = threading.Thread(target=self._boucle, daemon=True)
            self.thread.start()

    def arreter(self):
        self.stop.set()

    def _ouvrir(self):
        import socket
        import struct
        socks = []
        for groupe, port in self.GROUPES:
            try:
                sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                sk.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                if hasattr(socket, "SO_REUSEPORT"):
                    sk.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
                sk.bind(("", port))
                if groupe:
                    sk.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP,
                                  struct.pack("4s4s", socket.inet_aton(groupe), socket.inet_aton(self.ip)))
                sk.setblocking(False)
                socks.append(sk)
            except OSError:
                try:
                    sk.close()
                except (OSError, UnboundLocalError):
                    pass
        return socks

    def _vu(self, src):
        if src == self.ip or self.reseau is None:
            return
        try:
            if ipaddress.IPv4Address(src) not in self.reseau:
                return
        except ValueError:
            return
        if src in self.connus():
            return
        maintenant = time.time()
        if maintenant - self.signale.get(src, 0) < 60:
            return
        if len(self.signale) > 500:
            self.signale.clear()
        self.signale[src] = maintenant
        if maintenant - self.dernier >= 3.0:
            self.dernier = maintenant
            try:
                self.reveil()
            except Exception:  # noqa: BLE001
                journal_exc()

    def _boucle(self):
        import select
        socks = []
        try:
            while not self.stop.is_set():
                if self._ip_ouverte != self.ip:                  # la carte a changé d'adresse : on rouvre les écoutes
                    for sk in socks:
                        try:
                            sk.close()
                        except OSError:
                            pass
                    socks = self._ouvrir() if self.ip else []
                    self._ip_ouverte = self.ip
                if not socks:
                    self.stop.wait(5.0)
                    continue
                try:
                    pret, _, _ = select.select(socks, [], [], 1.0)
                except (OSError, ValueError):
                    self._ip_ouverte = None
                    continue
                for sk in pret:
                    for _ in range(40):                           # on vide un peu à la fois : jamais de longue pause
                        try:
                            _, adr = sk.recvfrom(2048)
                        except OSError:
                            break
                        self._vu(adr[0])
        finally:
            for sk in socks:
                try:
                    sk.close()
                except OSError:
                    pass


def ping_groupe(device, reseau):
    """Grand réseau (plus de 1 022 adresses) : au lieu de tout tester, on lance un ping « à tout le monde »
    (groupe 224.0.0.1 + adresse de diffusion du réseau) et on note qui répond. Renvoie la liste des adresses vues."""
    cibles = ["224.0.0.1"]
    try:
        cibles.append(str(reseau.broadcast_address))
    except Exception:  # noqa: BLE001
        journal_exc()
    vues = set()
    verrou = threading.Lock()

    def un(cible):
        base = ["ping", "-c", "2", "-t", "3"]
        essais = ([base + ["-b", device, cible]] if device and _PING_AVEC_B[0] else []) + [base + [cible]]
        for cmd in essais:
            ok, out = lancer(cmd, delai=8)
            adresses = re.findall(r"from (\d+\.\d+\.\d+\.\d+)", out)
            if adresses or ok:
                with verrou:
                    vues.update(adresses)
                return
    fils = [threading.Thread(target=un, args=(c,), daemon=True) for c in cibles]
    for f in fils:
        f.start()
    for f in fils:
        f.join(10)
    return sorted(vues)


# avancement du balayage en cours (lu par la jauge de l'onglet Appareils)
_PROG_SCAN = {"actif": False, "n": 0, "total": 0, "t0": 0.0, "dernier": None, "manuel": False}
_SCAN_MANUEL = [False]          # mis à True par « actualiser » : le prochain balayage affichera la jauge


_DERNIER_BALAYAGE_PING = [0.0]       # dernière fois qu'on a testé toutes les adresses une par une (méthode lente de secours)


def sonde_udp(device, ip, cibles, annuler=None):
    """Envoie un tout petit paquet UDP à chaque adresse de `cibles` : le Mac demande alors en ARP « qui a cette adresse ? »
    et les appareils présents répondent. Rien ne s'affiche chez eux (port 9, « discard »). Renvoie False si impossible."""
    import socket
    try:
        sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    except OSError:
        return False
    try:
        sk.setblocking(False)
        lie = False
        if device and sys.platform == "darwin":
            try:
                sk.setsockopt(socket.IPPROTO_IP, 25, socket.if_nametoindex(device))      # IP_BOUND_IF : sortir par cette carte
                lie = True
            except (OSError, ValueError):
                pass
        if not lie:
            try:
                sk.bind((ip, 0))
            except OSError:
                pass
        for i, c in enumerate(cibles):
            if annuler and annuler():
                break
            try:
                sk.sendto(b"\x00", (c, 9))
            except OSError:
                pass                              # (« hôte injoignable » : normal pour une adresse vide)
            if i % 48 == 47:
                time.sleep(0.004)                 # on laisse respirer la carte réseau
        return True
    except OSError:
        return False
    finally:
        try:
            sk.close()
        except OSError:
            pass


def trouver_par_arp(device, ip, hotes, annuler=None):
    """Méthode rapide (environ 1 s) : sonde UDP de toutes les adresses, puis lecture de la table ARP du Mac.
    Marche aussi pour les appareils qui ne répondent pas au ping. Renvoie ({ip: mac}, méthode_ok)."""
    if not sonde_udp(device, ip, hotes, annuler):
        return {}, False
    time.sleep(0.5)
    arp = table_arp(device)
    restants = [h for h in hotes if h not in arp]
    if restants and not (annuler and annuler()):
        sonde_udp(device, ip, restants, annuler)          # une seconde chance pour ceux qui n'ont pas répondu du premier coup
        time.sleep(0.4)
        arp = table_arp(device)
    return arp, True


def verifier_absents(absents, device, ip_locale, annuler=None, paralleles=8):
    """Contre-vérification immédiate d'appareils qui viennent de manquer à l'appel (au lieu d'attendre le scan suivant).
    `absents` : liste de (clé, appareil, répondait_au_ping). Deux pings ; pour un appareil qui n'a jamais répondu au ping,
    en plus une sonde ARP fraîche. Renvoie {clé: ms | "arp" | None} ; None = bien absent."""
    from concurrent.futures import ThreadPoolExecutor

    def un(item):
        k, d, pinguable = item
        for essai in range(2):
            ms = _ping_un(d["ip"], device)
            if ms is not None:
                return k, ms
            if annuler and annuler():
                return k, "arp"                  # on arrête : dans le doute, on ne déclare rien
            if essai == 0:
                time.sleep(0.3)
        if not pinguable and sonde_udp(device, ip_locale, [d["ip"]], annuler):
            time.sleep(0.4)
            if d["ip"] in table_arp(device):
                return k, "arp"
        return k, None

    if not absents:
        return {}
    with ThreadPoolExecutor(max_workers=max(1, min(paralleles, len(absents)))) as pool:
        return dict(pool.map(un, absents))


_LAC_NOMS = {}                  # (ip, mac) -> (nom lu sur l'ampli, instant de la dernière tentative)


def _lac_nom_connu(ip, mac):
    return (_LAC_NOMS.get((ip, mac)) or ("", 0))[0]


def _lac_chercher_noms(vus, attente=2.0):
    """Amplis L-Acoustics vus sur le réseau : on lit leur nom en L-COM, en parallèle (un seul essai par IP+MAC, retenté après 60 s)."""
    from concurrent.futures import ThreadPoolExecutor, wait as attendre
    a_faire = []
    for a, d in vus.items():
        if d.get("fabricant") != "L-Acoustics":
            continue
        cle = (a, d.get("mac", ""))
        vieux = _LAC_NOMS.get(cle)
        if vieux is None or (not vieux[0] and time.time() - vieux[1] > 60):
            a_faire.append((a, cle))
    if not a_faire:
        return

    def lire(a, cle):
        r = lac_devinfo(a, delai=1.0)
        _LAC_NOMS[cle] = ((r or {}).get("nom", ""), time.time())
    pool = ThreadPoolExecutor(max_workers=8)
    futs = [pool.submit(lire, a, cle) for a, cle in a_faire]
    attendre(futs, timeout=attente)
    pool.shutdown(wait=False, cancel_futures=True)


def scanner_reseau(service, attendus=(), progres=None, ip=None, masque=None, device=None, annuler=None,
                   cache_hotes=None, rapide=False, partiel=None):
    """Cherche les appareils qui répondent sur la carte `service`.

    Renvoie un dict : ok, erreur, ip, reseau, reduit, trouves (liste triée de dicts ip/mac/ms/nom/fabricant/attendu),
    manquants (liste de (ip, nom) attendus mais absents)."""
    from concurrent.futures import ThreadPoolExecutor
    device = device if device is not None else periphérique_de(service)
    if ip is None:
        ip, masque = adresse_de_carte(device) if device else ("", "")
    if not ip or not masque:
        return {"ok": False, "erreur": "pas_d_ip", "ip": "", "reseau": "", "reduit": False,
                "trouves": [], "manquants": []}
    hotes, reseau, reduit = liste_hotes(ip, masque)
    attendus = list(attendus)
    # un appareil attendu hors du réseau de la carte est quand même testé
    en_plus = [a for a, _ in attendus if a not in hotes and a != ip]
    if reduit and not (annuler and annuler()):
        # réseau trop grand pour tout tester : on trouve les appareils par un ping de groupe + la table ARP
        try:
            vrai = ipaddress.IPv4Network(f"{ip}/{masque}", strict=False)
            vues = set(ping_groupe(device, vrai)) | set(table_arp(device))
            for a in sorted(vues, key=lambda x: tuple(int(p) for p in x.split("."))):
                if (a != ip and a not in hotes and a not in en_plus and not a.startswith(("224.", "239.", "255."))
                        and ipaddress.IPv4Address(a) in vrai):
                    en_plus.append(a)
        except Exception:  # noqa: BLE001
            journal_exc()
    cibles = hotes + en_plus
    ms = {}
    fait = [0]
    verrou = threading.Lock()
    manuel = _SCAN_MANUEL[0]                       # la jauge ne s'affiche que pour un balayage demandé par « actualiser »
    _SCAN_MANUEL[0] = False
    total = len(cibles)
    _PROG_SCAN.update(actif=True, n=0, total=total, t0=time.time(), manuel=manuel)
    hotes_ens = set(hotes)

    def un(cible):
        if annuler and annuler():
            return
        r = _ping_un(cible, device, 400 if rapide else 700)
        with verrou:
            fait[0] += 1
            if r is not None:
                ms[cible] = r
            n = fait[0]
        if progres:
            progres(n, len(cibles))

    def pinger(liste, maxi):
        if not liste:
            return
        with ThreadPoolExecutor(max_workers=max(1, min(maxi, len(liste)))) as pool:
            list(pool.map(un, liste))

    try:
        # 1) méthode rapide : sonde ARP de tout le réseau (environ 1 s)
        arp0, ok_arp = trouver_par_arp(device, ip, hotes, annuler)
        _PROG_SCAN["n"] = int(total * 0.6)
        trouves_arp = [a for a in arp0 if a in hotes_ens and a != ip]
        if partiel and trouves_arp:
            # premier affichage tout de suite : les appareils vus par ARP, avant les pings et les noms
            cache0 = cache_hotes if cache_hotes is not None else {}
            partiel({"ok": True, "partiel": True, "erreur": "", "ip": ip, "reseau": str(reseau), "reduit": reduit,
                     "device": device, "service": service, "manquants": [],
                     "trouves": [{"ip": a, "mac": arp0[a], "ms": None, "fabricant": fabricant(arp0[a]),
                                  "nom": dict(attendus).get(a, "") or _lac_nom_connu(a, arp0[a]), "hote": cache0.get(a, ""), "attendu": a in dict(attendus)}
                                 for a in sorted(trouves_arp, key=lambda x: tuple(int(p) for p in x.split(".")))]})
        # 2) un ping seulement pour ceux qu'on a trouvés (et pour les adresses attendues hors réseau)
        a_pinger = sorted(set(trouves_arp) | set(en_plus))
        fait[0] = len(cibles) - len(a_pinger)
        pinger(a_pinger, max(perf()[2], 64) if rapide else max(perf()[2], 24))
        # 3) filet de sécurité : si la méthode rapide n'a rien donné, on teste les adresses une par une (au plus toutes les 10 min)
        if (not ok_arp or not trouves_arp) and not (annuler and annuler()) and time.time() - _DERNIER_BALAYAGE_PING[0] > 600:
            _DERNIER_BALAYAGE_PING[0] = time.time()
            fait[0] = 0
            pinger([h for h in cibles if h not in a_pinger], max(perf()[2], 64) if rapide else perf()[2])
    finally:
        _PROG_SCAN.update(actif=False, n=total, dernier=(total, time.time() - _PROG_SCAN["t0"]))
    arp = table_arp(device)
    vus = {}
    for a in set(ms) | set(arp):
        if a == ip or (a not in hotes and a not in en_plus):
            continue
        mac = arp.get(a, "")
        vus[a] = {"ip": a, "mac": mac, "ms": ms.get(a), "fabricant": fabricant(mac) if mac else ""}
    noms = dict(attendus)
    # noms annoncés par les appareils eux-mêmes (en parallèle, 2 secondes au plus au total)
    from concurrent.futures import wait as attendre
    hotes_trouves = cache_hotes if cache_hotes is not None else {}
    a_chercher = [a for a in vus if a not in hotes_trouves]       # (déjà connus = pas de nouvelle recherche)
    if a_chercher:
        pool2 = ThreadPoolExecutor(max_workers=16)
        futs = {pool2.submit(hote_de, a): a for a in a_chercher}
        faits, _ = attendre(futs, timeout=2.0)
        for f in faits:
            try:
                hotes_trouves[futs[f]] = f.result()
            except Exception:  # noqa: BLE001
                journal_exc()
        pool2.shutdown(wait=False, cancel_futures=True)
    _lac_chercher_noms(vus)
    for a, d in vus.items():
        d["nom"] = noms.get(a, "") or _lac_nom_connu(a, d.get("mac", ""))
        d["hote"] = hotes_trouves.get(a, "")
        d["attendu"] = a in noms
    trouves = sorted(vus.values(), key=lambda d: tuple(int(x) for x in d["ip"].split(".")))
    manquants = [(a, n) for a, n in attendus if a not in vus]
    return {"ok": True, "erreur": "", "ip": ip, "reseau": str(reseau), "reduit": reduit, "device": device,
            "service": service, "manuel": manuel,
            "trouves": trouves, "manquants": manquants}


# ----------------------------------------------------------------------
# Surveillance, historique des événements, noms par adresse MAC, export, conflits d'IP
# ----------------------------------------------------------------------
FICHIER_EVT = os.path.join(DOSSIER, "evenements.json")
MAX_EVT = 1000
_verrou_evt = threading.Lock()
GENRES_EVT = ("connexion", "deconnexion", "erreur", "conflit", "avert", "info")


_evt_etat = {"dernier": 0.0, "timer": None}


def _ecrire_evenements():
    """Écrit l'historique sur disque (à appeler avec _verrou_evt pris). Avant : une réécriture complète à CHAQUE événement."""
    _evt_etat["dernier"] = time.time()
    _evt_etat["timer"] = None
    if _CACHE_EVT[0] is None:
        return
    try:
        ecrire_json_sur(FICHIER_EVT, _CACHE_EVT[0], ensure_ascii=False)
    except OSError:
        pass


def vider_evenements_en_attente():
    with _verrou_evt:
        _ecrire_evenements()


atexit.register(vider_evenements_en_attente)


def noter_evenement(genre, texte):
    """Ajoute une ligne à l'historique (connexions, déconnexions, erreurs…). Jamais les messages « rigolos » de la mascotte."""
    with _verrou_evt:
        if _CACHE_EVT[0] is None:                      # le fichier n'est relu qu'une fois, ensuite tout est en mémoire
            _CACHE_EVT[0] = _lire_evenements_fichier()
        liste = _CACHE_EVT[0]
        ev = {"t": time.time(), "g": genre, "m": str(texte)}
        if getattr(texte, "cle", None):
            ev["k"], ev["p"] = texte.cle, texte.params
        liste.append(ev)
        del liste[:-MAX_EVT]
        if time.time() - _evt_etat["dernier"] >= 1.0:
            _ecrire_evenements()
        elif _evt_etat["timer"] is None:               # trop tôt : on regroupe, l'écriture aura lieu dans 1 s
            _evt_etat["timer"] = threading.Timer(1.0, vider_evenements_en_attente)
            _evt_etat["timer"].daemon = True
            _evt_etat["timer"].start()


_MODELES = {}


def _modeles():
    if not _MODELES:
        for lang, tab in TEXTES.items():
            for cle, val in tab.items():
                if len(re.sub(r"\{[a-z_]+\}", "", val).strip()) < 8:
                    continue
                morceaux = re.split(r"\{([a-z_]+)\}", " ".join(val.split()))
                rx = "".join(re.escape(m_) if i % 2 == 0 else f"(?P<{m_}>.+?)" for i, m_ in enumerate(morceaux))
                try:
                    _MODELES.setdefault(cle, []).append(re.compile(rx + "$"))
                except re.error:
                    pass
    return _MODELES


_CACHE_CLE = {}


def retrouver_cle(texte):
    """Retrouve (clé, paramètres) d'un ancien message enregistré sans clé (dans n'importe quelle langue).
    Le résultat est gardé en mémoire : la recherche (des centaines d'expressions) coûtait des centaines de
    millisecondes à chaque redessin de l'historique."""
    norm = " ".join(str(texte).split())
    if norm in _CACHE_CLE:
        r_ = _CACHE_CLE[norm]
        return (r_[0], dict(r_[1])) if r_ else None
    trouve = None
    for cle, liste in _modeles().items():
        for rx in liste:
            m_ = rx.match(norm)
            if m_:
                trouve = (cle, m_.groupdict())
                break
        if trouve:
            break
    if len(_CACHE_CLE) > 3000:
        _CACHE_CLE.clear()
    _CACHE_CLE[norm] = trouve
    return (trouve[0], dict(trouve[1])) if trouve else None


def texte_evenement(e):
    """Texte d'un événement dans la langue courante (les anciens, sans clé, restent tels quels)."""
    k = e.get("k")
    if k:
        try:
            return t(k, **(e.get("p") or {}))
        except (KeyError, IndexError, ValueError):
            pass
    r_ = retrouver_cle(e["m"])
    if r_:
        try:
            return t(r_[0], **r_[1])
        except (KeyError, IndexError, ValueError):
            pass
    return e["m"]


_CACHE_EVT = [None]


def lire_evenements():
    if _CACHE_EVT[0] is not None:
        return list(_CACHE_EVT[0])
    return _lire_evenements_fichier()


def _lire_evenements_fichier():
    try:
        with open(FICHIER_EVT, encoding="utf-8") as f:
            d = json.load(f)
        return [e for e in d if isinstance(e, dict) and "m" in e] if isinstance(d, list) else []
    except (OSError, json.JSONDecodeError):
        return []


def vider_evenements():
    with _verrou_evt:
        _CACHE_EVT[0] = []
        try:
            if os.path.exists(FICHIER_EVT):
                os.remove(FICHIER_EVT)
        except OSError:
            pass


def cle_appareil(d):
    """Un appareil se reconnaît à son adresse MAC (l'IP peut changer) ; sans MAC, à son IP."""
    return d.get("mac") or d["ip"]


def noms_memorises():
    n = lire_reglages().get("noms_mac", {})
    return n if isinstance(n, dict) else {}


def nom_appareil(d, noms=None):
    """Nom choisi par l'utilisateur (mémorisé par MAC), sinon nom de la liste attendue, sinon nom annoncé par l'appareil."""
    noms = noms_memorises() if noms is None else noms
    return noms.get(cle_appareil(d), "") or d.get("nom", "") or d.get("hote", "")


def memoriser_nom(cle, nom):
    noms = dict(noms_memorises())
    nom = nom.strip()
    if nom:
        noms[cle] = nom
    else:
        noms.pop(cle, None)
    sauver_reglage(noms_mac=noms)


def conflits_ou_mac_change(evts):
    return any(g == "conflit" for g, _ in evts)


def suivre_changements(etat, trouves, seuil=2, confirmes=()):
    """Compare deux scans. `etat` (dict, modifié sur place) garde la mémoire d'un scan à l'autre.
    Renvoie une liste d'événements (genre, dict) : connexion / deconnexion / conflit.
    Un appareil n'est déclaré perdu qu'après `seuil` scans de suite sans réponse (un ping perdu n'est pas une panne),
    sauf si `confirmes` le dit absent : la surveillance l'a déjà re-sondé aussitôt et il n'a pas répondu."""
    evts = []
    appareils = etat.setdefault("appareils", {})
    ip_mac = etat.setdefault("ip_mac", {})
    premier = not etat.get("init")
    etat["init"] = True
    presents = set()
    for d in trouves:
        k = cle_appareil(d)
        ancien = appareils.get(k)
        if ancien is not None and ancien["perdu"] and ancien.get("repond") and d.get("ms") is None:
            continue         # il répondait au ping et ne répond plus : sa ligne ARP, restée dans la table, ne le ramène pas
        presents.add(k)
        if ancien is None:
            appareils[k] = {"ip": d["ip"], "mac": d.get("mac", ""), "manque": 0, "perdu": False}
            if not premier:
                evts.append(("connexion", {"cle": k, "ip": d["ip"], "mac": d.get("mac", ""), "nouveau": True}))
        else:
            if ancien["perdu"]:
                evts.append(("connexion", {"cle": k, "ip": d["ip"], "mac": d.get("mac", ""), "nouveau": False}))
            ancien.update(ip=d["ip"], manque=0, perdu=False)
        if d.get("ms") is not None:
            appareils[k]["repond"] = True
        if d.get("mac"):
            vieux = ip_mac.get(d["ip"])
            if vieux and vieux != d["mac"]:
                evts.append(("conflit", {"ip": d["ip"], "ancien": vieux, "nouveau": d["mac"]}))
            ip_mac[d["ip"]] = d["mac"]
    for k, a in appareils.items():
        if k in presents:
            continue
        a["manque"] = max(a["manque"] + 1, seuil) if k in confirmes else a["manque"] + 1
        if a["manque"] >= seuil and not a["perdu"]:
            a["perdu"] = True
            evts.append(("deconnexion", {"cle": k, "ip": a["ip"], "mac": a["mac"]}))
    return evts


def adresses_deja_prises(p):
    """Avant d'appliquer une IP fixe : cette adresse répond-elle déjà sur le réseau ? (autre appareil qui l'utilise).
    On ignore les adresses qui sont déjà celles de ce Mac."""
    ok, out = lancer(["ifconfig"], delai=5)
    miennes = set(re.findall(r"inet (\d+\.\d+\.\d+\.\d+) ", out)) if ok else set()
    prises = []
    for c in p["interfaces"]:
        if c.get("mode") == "manuel" and ip_valide(c.get("ip", "")) and c["ip"] not in miennes:
            if _ping_un(c["ip"], None) is not None:
                prises.append(c["ip"])
    return prises


FICHIER_INV = os.path.join(DOSSIER, "appareils.json")


def lire_inventaire():
    """Inventaire du matériel déjà vu : {clé (MAC ou IP): {ip, mac, fab, vu, note}}."""
    try:
        with open(FICHIER_INV, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def sauver_inventaire(inv):
    try:
        ecrire_json_sur(FICHIER_INV, inv, ensure_ascii=False)
    except OSError:
        pass


def purger_inventaire(inv, avant, noms=None, epingles=()):
    """L'inventaire ne garde que l'important : un appareil absent depuis `avant` (début de cette session) est oublié,
    sauf si l'utilisateur l'a nommé, annoté ou épinglé. Renvoie les clés supprimées."""
    noms = noms_memorises() if noms is None else noms
    morts = [k for k, a in inv.items()
             if a.get("vu", 0) < avant and not (a.get("note") or "").strip() and not noms.get(k)
             and not noms.get(a.get("ip", "")) and k not in epingles and a.get("ip", "") not in epingles]
    for k in morts:
        inv.pop(k, None)
    return morts


def noter_vu(inv, d, maintenant, reseau="", carte=""):
    """Met l'inventaire à jour avec un appareil vu dans un scan. Renvoie True si c'est un appareil nouveau."""
    k = cle_appareil(d)
    if d.get("mac") and d["ip"] != k and d["ip"] in inv and not inv[d["ip"]].get("mac"):
        # même adresse IP, vu d'abord sans MAC puis avec : c'est le même appareil, on fusionne
        vieux = inv.pop(d["ip"])
        if k not in inv:
            inv[k] = vieux
        elif vieux.get("note") and not inv[k].get("note"):
            inv[k]["note"] = vieux["note"]
        try:
            noms = noms_memorises()
            if noms.get(d["ip"]) and not noms.get(k):
                memoriser_nom(k, noms[d["ip"]])
        except Exception:  # noqa: BLE001
            journal_exc()
    nouveau = k not in inv
    a = inv.setdefault(k, {"note": ""})
    a.update(ip=d["ip"], mac=d.get("mac", ""), fab=d.get("fabricant", ""), vu=maintenant)
    if reseau:
        a["reseau"] = reseau
    if carte:
        a["carte"] = carte
    return nouveau


def exporter_inventaire_csv(chemin, inv, noms=None):
    import csv
    noms = noms_memorises() if noms is None else noms
    with open(chemin, "w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow([t("csv_nom"), "IP", "MAC", t("csv_fabricant"), t("csv_vu"), t("csv_note")])
        for k, a in sorted(inv.items(), key=lambda kv: tuple(int(x) for x in kv[1].get("ip", "0.0.0.0").split("."))):
            w.writerow([noms.get(k, ""), a.get("ip", ""), a.get("mac", ""), a.get("fab", ""),
                        time.strftime("%Y-%m-%d %H:%M", time.localtime(a.get("vu", 0))) if a.get("vu") else "",
                        a.get("note", "")])
    return len(inv)


def duree_courte(sec):
    sec = max(0, int(sec))
    if sec >= 3600:
        return f"{sec // 3600} h {sec % 3600 // 60:02d}"
    return f"{sec // 60:02d}:{sec % 60:02d}"


def duree_precise(sec):
    """1,8 s / 12 s / 02:30 (la virgule en français)."""
    if sec < 10:
        return f"{sec:.1f}".replace(".", ",") + " s" if LANGUE == "fr" else f"{sec:.1f} s"
    if sec < 60:
        return f"{int(round(sec))} s"
    return duree_courte(sec)


def analyser_media(texte):
    """Vitesse de la liaison en Mb/s d'après la sortie de « ifconfig » : 1000, 100, 10, 2500, 10000…
    0 = pas de câble, None = on ne sait pas (Wi-Fi, carte virtuelle)."""
    if re.search(r"status:\s*inactive", texte):
        return 0
    m = re.search(r"media:.*?\((\d+)(G?)base", texte, flags=re.I)
    if not m:
        return None
    v = int(m.group(1))
    return v * 1000 if m.group(2) else v


def texte_vitesse(mbs):
    if mbs is None:
        return ""
    if mbs == 0:
        return t("vit_aucun")
    if mbs >= 1000:
        g = mbs / 1000
        v = (f"{g:g}".replace(".", ",") if LANGUE == "fr" else f"{g:g}") + " Gb/s"
    else:
        v = f"{mbs} Mb/s"
    return t("vit_texte", v=v)


def vitesse_liaison(device):
    if not device:
        return None
    ok, out = lancer(["ifconfig", device], delai=4)
    return analyser_media(out) if ok else None


def tester_port(ip, port, delai=2.0):
    """'ouvert', 'ferme' (l'appareil répond mais refuse) ou 'muet' (aucune réponse)."""
    import socket
    try:
        with socket.create_connection((ip, port), timeout=delai):
            return "ouvert"
    except ConnectionRefusedError:
        return "ferme"
    except OSError:
        return "muet"


def lire_octets(texte):
    """{périphérique: (octets reçus, octets envoyés)} d'après « netstat -ib » (une ligne <Link#> par carte).
    Les colonnes sont lues depuis la droite d'après l'en-tête : ça marche avec ou sans adresse MAC."""
    lignes = texte.splitlines()
    entete = next((l.split() for l in lignes if "Ibytes" in l and "Obytes" in l), None)
    if not entete:
        return {}
    ri, ro = len(entete) - entete.index("Ibytes"), len(entete) - entete.index("Obytes")
    res = {}
    for ligne in lignes:
        c = ligne.split()
        if len(c) < max(ri, ro) + 3 or not c[2].startswith("<Link#"):
            continue
        try:
            rx, tx = int(c[-ri]), int(c[-ro])
        except (ValueError, IndexError):
            continue
        res.setdefault(c[0].rstrip("*"), (rx, tx))
    return res


def cartes_debit():
    """[(périphérique, nom de la carte)] d'après « networksetup -listallhardwareports » : en0 -> Wi-Fi…"""
    ok, out = lancer(["networksetup", "-listallhardwareports"], delai=8)
    res, port = [], None
    for ligne in out.splitlines():
        if ligne.startswith("Hardware Port:"):
            port = ligne.split(":", 1)[1].strip()
        elif ligne.startswith("Device:") and port:
            dev = ligne.split(":", 1)[1].strip()
            if dev:
                res.append((dev, port))
            port = None
    return res


def debit_mbps(avant, apres):
    """(reçu, envoyé) en Mb/s entre deux relevés (instant, octets reçus, octets envoyés)."""
    dt = apres[0] - avant[0]
    if dt <= 0:
        return 0.0, 0.0
    return (max(0, apres[1] - avant[1]) * 8 / 1e6 / dt, max(0, apres[2] - avant[2]) * 8 / 1e6 / dt)


def echelle_jolie(m):
    """Plus petite graduation « ronde » qui contient m (0,5 / 1 / 2 / 5 / 10 / 20 / 50 / 100…)."""
    for v in (0.5, 1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000):
        if m <= v:
            return v
    return float(int(m) + 1)


def gigue_serie(pts):
    """Écart de temps de réponse d'un ping au suivant (ms) ; None quand un des deux manque."""
    res, prec = [], None
    for p in pts:
        if p is None:
            res.append(None)
            prec = None
            continue
        res.append(abs(p - prec) if prec is not None else None)
        prec = p
    return res


def gigue_moyenne(pts):
    v = [g for g in gigue_serie(pts) if g is not None]
    return sum(v) / len(v) if v else None


def coups_recents(coups, en_cours, maintenant, fenetre=1800):
    """Coupures (début, durée) des `fenetre` dernières secondes, plus celle en cours si l'appareil ne répond pas."""
    evs = [(t0, du) for t0, du in coups if t0 + du >= maintenant - fenetre]
    if en_cours is not None:
        evs.append((en_cours, max(0.0, maintenant - en_cours)))
    return evs


def cellules_coupures(evs, maintenant, depuis=None, n=60, pas=30):
    """Une valeur par tranche de `pas` secondes (la plus ancienne d'abord) : None = pas encore surveillé,
    sinon le nombre de secondes de coupure dans la tranche (0 = tout va bien)."""
    debut = maintenant - n * pas
    res = []
    for i in range(n):
        a, b = debut + i * pas, debut + (i + 1) * pas
        if depuis is not None and b <= depuis:
            res.append(None)
            continue
        res.append(sum(max(0.0, min(b, t0 + du) - max(a, t0)) for t0, du in evs))
    return res


def cle_ordre_coupure(a, evs):
    """Les appareils en panne d'abord, puis ceux qui ont coupé (les plus touchés en premier), puis les stables."""
    groupe = 0 if a.get("perdu") else (1 if evs else 2)
    return (groupe, -len(evs), tuple(int(x) for x in a["ip"].split(".")))


def _norm(texte):
    """Minuscules, sans accents ni ponctuation : « L-Acoustics » et « lacoustics » deviennent identiques."""
    t_ = unicodedata.normalize("NFKD", str(texte or "")).encode("ascii", "ignore").decode()
    return re.sub(r"[^a-z0-9]", "", t_.lower())


def filtrer_appareils(liste, requete, noms):
    """Garde les appareils dont le nom, l'IP, la MAC, le fabricant ou la note contiennent tous les mots tapés."""
    mots = [_norm(m) for m in str(requete or "").split()]
    mots = [m for m in mots if m]
    if not mots:
        return liste
    res = []
    for a in liste:
        champs = [_norm(noms.get(a["cle"], "") or a.get("nom", "")), _norm(a.get("ip", "")), _norm(a.get("mac", "")),
                  _norm(a.get("fab", "")), _norm(a.get("note", ""))]
        if all(any(m in c for c in champs) for m in mots):
            res.append(a)
    return res


def trier_appareils(liste, col, croissant, noms, vivants, maintenant):
    """Classe les appareils de l'onglet Appareils d'après la colonne choisie. Les cases vides vont toujours à la fin."""
    def ip_cle(a):
        return tuple(int(x) for x in a["ip"].split("."))

    def valeur(a):
        if col == "nom":
            return (noms.get(a["cle"], "") or a.get("nom", "") or "").lower()
        if col == "IP":
            return ip_cle(a)
        if col == "MAC":
            return (a.get("mac", "") or "").lower()
        if col == "fab":
            return (a.get("fab", "") or "").lower()
        if col == "note":
            return (a.get("note", "") or "").lower()
        if col == "etat":
            v = vivants.get(a["cle"])
            if v and not v.get("perdu") and maintenant - v.get("vu", 0) < 90:
                return (0, 0)
            if v and v.get("perdu"):
                return (1, 0)
            return (2, -(a.get("vu") or 0))
        return ip_cle(a)
    pleins = [a for a in liste if valeur(a) not in ("", ())]
    vides = [a for a in liste if valeur(a) in ("", ())]
    pleins.sort(key=lambda a: (valeur(a), ip_cle(a)), reverse=not croissant)
    vides.sort(key=ip_cle)
    return pleins + vides


def libelle_appareil(a):
    return f"{a['nom']} ({a['ip']})" if a.get("nom") else a["ip"]


def problemes_reseau(appareils, evenements, maintenant, fenetre=1800):
    """Ce qui ne va pas en ce moment, pour la fenêtre « problèmes » : appareils perdus, conflits d'IP, erreurs récentes,
    latences hautes. Renvoie une liste de (genre, texte) ; un seul élément « tout va bien » s'il n'y a rien."""
    res = []
    for a in appareils.values():
        if a.get("perdu"):
            res.append(("deconnexion", t("pb_perdu", nom=libelle_appareil(a), depuis=duree_courte(maintenant - a.get("perdu_t", maintenant)))))
    for e in reversed(evenements):
        if maintenant - e.get("t", 0) > fenetre:
            break
        if e.get("g") == "conflit":
            res.append(("conflit", texte_evenement(e)))
        elif e.get("g") in ("erreur", "avert"):
            res.append(("erreur", texte_evenement(e)))
    for a in appareils.values():
        if not a.get("perdu") and a.get("ms") is not None and a["ms"] > 50:
            res.append(("avert", t("pb_latence", nom=libelle_appareil(a), ms=a["ms"])))
    return res or [("connexion", t("pb_aucun"))]


def conflits_systeme(device, ip, depuis="3m"):
    """Cherche dans le journal du Mac les alertes « quelqu'un d'autre utilise mon adresse IP » (macOS les écrit lui-même).
    Renvoie la liste des adresses MAC fautives (vide si rien, ou si le journal n'est pas lisible)."""
    ok, out = lancer(["log", "show", "--last", depuis, "--style", "compact", "--predicate",
                      'eventMessage CONTAINS "is using my IP address"'], delai=25)
    if not ok:
        return []
    macs = []
    for ligne in out.splitlines():
        if "is using my IP address" not in ligne:
            continue
        if ip and ip not in ligne:
            continue
        m = re.search(r"([0-9a-fA-F]{1,2}(?::[0-9a-fA-F]{1,2}){5})", ligne)
        mac = mac_propre(m.group(1)) if m else ""
        if mac and mac not in macs:
            macs.append(mac)
    return macs


def ecrire_pdf(chemin, titre, sous_titre, colonnes, lignes):
    """Écrit un tableau en PDF (A4 paysage, police Helvetica intégrée à tout lecteur PDF : aucune bibliothèque requise).
    `colonnes` : [(titre, largeur en points)] ; `lignes` : liste de listes de textes."""
    LARG, HAUT, MARGE = 842, 595, 36
    HL, TAILLE = 17, 9.5

    def enc(texte):
        b = str(texte).encode("cp1252", "replace")
        return b.replace(b"\\", b"\\\\").replace(b"(", b"\\(").replace(b")", b"\\)")

    def coupe(texte, largeur, taille):
        texte = str(texte).replace("\n", " ")
        n = max(1, int((largeur - 8) / (taille * 0.52)))
        return texte if len(texte) <= n else texte[:max(1, n - 1)] + "…"

    par_page = max(1, int((HAUT - 2 * MARGE - 70) // HL) - 1)
    pages = [lignes[i:i + par_page] for i in range(0, len(lignes), par_page)] or [[]]
    total_l = sum(w for _, w in colonnes)
    contenus = []
    for np_, lots in enumerate(pages, 1):
        c = []
        y = HAUT - MARGE
        c.append(b"BT /F2 18 Tf %d %d Td (" % (MARGE, y - 14) + enc(titre) + b") Tj ET")
        c.append(b"0.45 0.40 0.62 rg BT /F1 9 Tf %d %d Td (" % (MARGE, y - 30) + enc(sous_titre) + b") Tj ET")
        y -= 56
        x = MARGE
        c.append(b"0.78 0.74 1 rg %d %d %d %d re f" % (MARGE, y - 4, total_l, HL))
        c.append(b"0.1 0.1 0.1 rg")
        for nom, w in colonnes:
            c.append(b"BT /F2 %s Tf %.1f %d Td (" % (str(TAILLE).encode(), x + 4, y) + enc(coupe(nom, w, TAILLE)) + b") Tj ET")
            x += w
        y -= HL
        for i, lg in enumerate(lots):
            if i % 2 == 0:
                c.append(b"0.96 0.94 1 rg %d %d %d %d re f" % (MARGE, y - 4, total_l, HL))
            c.append(b"0.1 0.1 0.1 rg")
            x = MARGE
            for (nom, w), val in zip(colonnes, lg):
                c.append(b"BT /F1 %s Tf %.1f %d Td (" % (str(TAILLE).encode(), x + 4, y) + enc(coupe(val, w, TAILLE)) + b") Tj ET")
                x += w
            y -= HL
        pied = "IP Pilot  ·  " + t("pdf_page", p=np_, n=len(pages))
        c.append(b"0.45 0.40 0.62 rg BT /F1 8 Tf %d %d Td (" % (MARGE, MARGE - 14) + enc(pied) + b") Tj ET")
        contenus.append(b"\n".join(c))
    objets = []                                  # index 0 = objet 1
    objets.append(b"<< /Type /Catalog /Pages 2 0 R >>")
    kids = " ".join(f"{5 + 2 * i} 0 R" for i in range(len(pages)))
    objets.append(f"<< /Type /Pages /Kids [{kids}] /Count {len(pages)} >>".encode())
    objets.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
    objets.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")
    for i, cont in enumerate(contenus):
        objets.append(f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {LARG} {HAUT}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> "
                      f"/Contents {6 + 2 * i} 0 R >>".encode())
        objets.append(b"<< /Length %d >>\nstream\n" % len(cont) + cont + b"\nendstream")
    sortie = bytearray(b"%PDF-1.4\n")
    pos = []
    for i, o in enumerate(objets, 1):
        pos.append(len(sortie))
        sortie += b"%d 0 obj\n" % i + o + b"\nendobj\n"
    xref = len(sortie)
    sortie += b"xref\n0 %d\n0000000000 65535 f \n" % (len(objets) + 1)
    for p in pos:
        sortie += b"%010d 00000 n \n" % p
    sortie += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objets) + 1, xref)
    with open(chemin, "wb") as f:
        f.write(bytes(sortie))


def exporter_inventaire_pdf(chemin, inv, noms=None):
    noms = noms_memorises() if noms is None else noms
    cols = [(t("csv_nom"), 170), (  "IP", 105), ("MAC", 120), (t("csv_fabricant"), 170), (t("csv_vu"), 100), (t("csv_note"), 97)]
    lignes = []
    for k, a in sorted(inv.items(), key=lambda kv: tuple(int(x) for x in kv[1].get("ip", "0.0.0.0").split("."))):
        lignes.append([noms.get(k, ""), a.get("ip", ""), a.get("mac", ""), a.get("fab", ""),
                       time.strftime("%Y-%m-%d %H:%M", time.localtime(a.get("vu", 0))) if a.get("vu") else "", a.get("note", "")])
    ecrire_pdf(chemin, t("pdf_t_app"), time.strftime("%d/%m/%Y %H:%M") + f"  ·  {len(lignes)}", cols, lignes)
    return len(lignes)


def exporter_scan_pdf(chemin, r, noms=None):
    noms = noms_memorises() if noms is None else noms
    cols = [("IP", 120), (t("csv_nom"), 190), (t("csv_fabricant"), 190), ("MAC", 130), (t("csv_latence"), 80), (t("csv_ping"), 62)]
    lignes = [[d["ip"], nom_appareil(d, noms), d.get("fabricant", ""), d.get("mac", ""),
               "" if d.get("ms") is None else f"{d['ms']:.1f}".replace(".", ","),
               t("csv_oui") if d.get("ms") is not None else t("csv_non")] for d in r.get("trouves", [])]
    ecrire_pdf(chemin, t("pdf_t_scan"), time.strftime("%d/%m/%Y %H:%M") + f"  ·  {len(lignes)}", cols, lignes)
    return len(lignes)


def exporter_scan_csv(chemin, r, noms=None):
    """Écrit le scan en CSV (séparateur « ; » et UTF-8 avec marque, pour que Excel français l'ouvre bien)."""
    import csv
    noms = noms_memorises() if noms is None else noms
    with open(chemin, "w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow(["IP", t("csv_nom"), t("csv_fabricant"), "MAC", t("csv_latence"), t("csv_ping")])
        for d in r.get("trouves", []):
            w.writerow([d["ip"], nom_appareil(d, noms), d.get("fabricant", ""), d.get("mac", ""),
                        "" if d.get("ms") is None else f"{d['ms']:.1f}".replace(".", ","),
                        t("csv_oui") if d.get("ms") is not None else t("csv_non")])
    return len(r.get("trouves", []))


# ===== écoute des ports (OSC, Art-Net) : lecture des paquets UDP reçus par ce Mac =====
PROTOS = ("osc", "artnet", "manet", "ptp")
PORTS_DEFAUT = {"osc": 8000, "artnet": 6454, "manet": 30020, "ptp": 319}
# MA-Net3 (grandMA3) : UDP multicast sur le port 30020, session 1 = 236.4.1.0 à 236.4.1.4 (239.4.1.x en variante)
PTP_GROUPES = ("224.0.1.129", "224.0.1.130", "224.0.1.131", "224.0.1.132", "224.0.0.107")
PTP_TYPES = {0x0: "Sync", 0x1: "Delay_Req", 0x2: "Pdelay_Req", 0x3: "Pdelay_Resp", 0x8: "Follow_Up", 0x9: "Delay_Resp",
             0xA: "Pdelay_Resp_FU", 0xB: "Announce", 0xC: "Signaling", 0xD: "Management"}
DANTE_MOTS = ("_netaudio", "_dante", "_ravenna")      # types de service « Bonjour » des appareils Dante / AES67 (Ravenna)


PORTS_IP = {"artnet": 6454, "coda": 3000, "shure": 2202, "lacoustics": 4432}      # ports des protocoles « ouverts » (changés par les tests)
PROTO_IP_NOMS = {"artnet": "Art-Net", "coda": "CODA", "shure": "Shure", "lacoustics": "L-Acoustics"}
ARTNET_IPPROG_CMD = 0x80 | 0x04 | 0x02     # « autoriser la programmation » + « programmer l'IP » + « programmer le masque »


def artnet_ipprog(ip_cible, cmd=0, ip_nouvelle="", masque="", delai=2.5, port=None):
    """Envoie un ArtIpProg (OpCode 0xF800) à un appareil Art-Net et attend son ArtIpProgReply (0xF900).
    cmd = 0 : simple question (l'appareil répond avec ses réglages actuels, sans rien changer).
    Renvoie {"ip", "masque", "dhcp", "de"} ou None s'il n'y a pas de réponse."""
    import select
    import socket
    port = port or PORTS_IP["artnet"]

    def quatre(a):
        return socket.inet_aton(a) if a else b"\x00\x00\x00\x00"
    paquet = (b"Art-Net\x00" + b"\x00\xf8" + b"\x00\x0e" + b"\x00\x00" + bytes([cmd & 0xFF, 0])
              + quatre(ip_nouvelle) + quatre(masque) + b"\x00\x00" + b"\x00" * 8)
    socks = []
    try:
        s1 = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s1.bind(("", 0))
        socks.append(s1)
    except OSError:
        return None
    try:                                                   # certains appareils répondent vers le port 6454
        s2 = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s2.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if hasattr(socket, "SO_REUSEPORT"):
            s2.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        s2.bind(("", 6454))
        socks.append(s2)
    except OSError:
        pass
    res = None
    try:
        s1.sendto(paquet, (ip_cible, port))
        t0 = time.time()
        while time.time() - t0 < delai and res is None:
            pret, _, _ = select.select(socks, [], [], 0.2)
            for sk in pret:
                try:
                    data, adr = sk.recvfrom(2048)
                except OSError:
                    continue
                if len(data) < 27 or data[:8] != b"Art-Net\x00" or data[8:10] != b"\x00\xf9":
                    continue
                ip_r, sm_r = socket.inet_ntoa(data[16:20]), socket.inet_ntoa(data[20:24])
                if adr[0] == ip_cible or (ip_nouvelle and ip_r == ip_nouvelle):
                    res = {"ip": ip_r, "masque": sm_r, "dhcp": bool(data[26] & 0x40), "de": adr[0]}
                    break
    except OSError:
        res = None
    finally:
        for sk in socks:
            try:
                sk.close()
            except OSError:
                pass
    return res


def _ip_pad(ip):
    """192.168.1.22 -> 192.168.001.022 (CODA et Shure écrivent les adresses sur 15 caractères)."""
    return ".".join(f"{int(x):03d}" for x in ip.split("."))


def _ip_nette(ip):
    return ".".join(str(int(x)) for x in ip.split("."))


def coda_devinfo(ip_cible, delai=1.8, port=None):
    """Amplificateur CODA (LINUS) : « *GETDEVINFO » en UDP sur le port 3000, réponse « *DEVINFO_modèle_MAC »."""
    import select
    import socket
    port = port or PORTS_IP["coda"]
    socks = []
    try:
        s1 = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s1.bind(("", 0))
        socks.append(s1)
    except OSError:
        return None
    try:
        s2 = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s2.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if hasattr(socket, "SO_REUSEPORT"):
            s2.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        s2.bind(("", port))
        socks.append(s2)
    except OSError:
        pass
    res = None
    try:
        s1.sendto(b"*GETDEVINFO", (ip_cible, port))
        t0 = time.time()
        while time.time() - t0 < delai and res is None:
            pret, _, _ = select.select(socks, [], [], 0.2)
            for sk in pret:
                try:
                    data, adr = sk.recvfrom(2048)
                except OSError:
                    continue
                m = re.match(r"\*DEVINFO_(.+)_([0-9A-Fa-f]{12})", data.decode("ascii", "ignore").strip())
                if m and adr[0] == ip_cible:
                    res = {"modele": m.group(1), "mac": m.group(2).upper(), "de": adr[0]}
                    break
    except OSError:
        res = None
    finally:
        for sk in socks:
            try:
                sk.close()
            except OSError:
                pass
    return res


def coda_changeip(ip_cible, nouvelle_ip, mac, port=None):
    """« *CHANGEIP=nouvelle_ip(15 car.):MAC » : l'ampli ne répond pas, on vérifie donc en l'interrogeant à sa nouvelle adresse."""
    import socket
    port = port or PORTS_IP["coda"]
    sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sk.sendto(f"*CHANGEIP={_ip_pad(nouvelle_ip)}:{mac}".encode("ascii"), (ip_cible, port))
    except OSError:
        return None
    finally:
        sk.close()
    time.sleep(1.5)
    r = coda_devinfo(nouvelle_ip, delai=3.0, port=port)
    return {"ip": nouvelle_ip, "masque": ""} if r else None


def _lac_trame(op, grp, idn, data=b"", *suite):
    """Trame L-COM (amplis L-Acoustics, TCP 4432) : « L » 00 longueur(2) puis enregistrements op, 03, groupe(2), id(2), taille(2), données.
    `suite` : enregistrements supplémentaires (op, grp, id) dans la même trame."""
    corps = bytes([op, 3]) + struct.pack(">HHH", grp, idn, len(data)) + data
    for o2, g2, i2 in suite:
        corps += bytes([o2, 3]) + struct.pack(">HHH", g2, i2, 0)
    return b"L\x00" + struct.pack(">H", 4 + len(corps)) + corps


def _lac_lire(buf):
    res = []
    while len(buf) >= 4 and buf[0] == 0x4C:
        n = struct.unpack(">H", buf[2:4])[0]
        if n < 4 or len(buf) < n:
            break
        m, buf = buf[4:n], buf[n:]
        j = 0
        while j + 8 <= len(m):
            g, i, ln = struct.unpack(">HHH", m[j + 2:j + 8])
            res.append((m[j], g, i, m[j + 8:j + 8 + ln]))
            j += 8 + ln
    return res, buf


def _lac_collecter(sk, duree):
    import socket
    sk.settimeout(0.3)
    fin = time.time() + duree
    buf, tout = b"", []
    while time.time() < fin:
        try:
            d = sk.recv(65536)
        except socket.timeout:
            continue
        except OSError:
            break
        if not d:
            break
        buf += d
        r, buf = _lac_lire(buf)
        tout += r
    return tout


def _lac_infos(rs):
    inf = {}
    for op, g, i, d in rs:
        if op in (0x09, 0x0A) and g == 1:
            if i == 0x20 and len(d) == 4:
                inf["ip"] = ".".join(str(b) for b in d)
            elif i == 0x21 and len(d) == 6:
                inf["mac"] = d.hex().upper()
            elif i == 0x29:
                inf["nom"] = d.decode("latin1")
            elif i == 0x04:
                inf["modele"] = d.decode("latin1")
    return inf


def _lac_log(txt):
    """Journal de diagnostic L-Acoustics (~/ip_pilot_lac.log)."""
    try:
        with open(os.path.expanduser("~/ip_pilot_lac.log"), "a", encoding="utf-8") as f:
            f.write(time.strftime("%H:%M:%S ") + txt + "\n")
    except OSError:
        pass


def lac_devinfo(ip_cible, delai=1.5, port=None):
    """Ampli L-Acoustics : lit modèle, IP, MAC et nom en L-COM (lecture seule). None s'il ne répond pas."""
    import socket
    port = port or PORTS_IP["lacoustics"]
    _lac_log(f"lac_devinfo {ip_cible}:{port}")
    try:
        sk = socket.create_connection((ip_cible, port), 2.5)
    except OSError as e:
        _lac_log(f"  connexion impossible : {e!r}")
        return None
    try:
        sk.sendall(_lac_trame(0, 1, 0x04, b"", (0, 1, 0x20), (0, 1, 0x21), (0, 1, 0x29)))     # une seule trame, comme LA Network Manager
        rs = _lac_collecter(sk, delai)
        inf = _lac_infos(rs)
        _lac_log(f"  {len(rs)} enregistrements, infos = {inf}")
    except Exception as e:  # noqa: BLE001
        _lac_log(f"  erreur : {e!r}")
        return None
    finally:
        sk.close()
    return inf if inf.get("mac") and inf.get("ip") else None


def lac_changeip(ip_cible, nouvelle_ip, port=None):
    """Change l'IP d'un ampli L-Acoustics (même échange que LA Network Manager), puis vérifie à la nouvelle adresse."""
    import socket
    port = port or PORTS_IP["lacoustics"]
    try:
        sk = socket.create_connection((ip_cible, port), 3)
    except OSError:
        return None
    try:
        sk.sendall(_lac_trame(9, 3, 0x0A, b"\x00\x00\x00\x00"))
        time.sleep(0.01)
        sk.sendall(_lac_trame(9, 1, 0x20, bytes(int(x) for x in nouvelle_ip.split("."))))
        _lac_collecter(sk, 1.5)
    except OSError:
        pass
    finally:
        try:
            sk.close()
        except OSError:
            pass
    time.sleep(1.0)
    r = lac_devinfo(nouvelle_ip, delai=2.0, port=port)
    return {"ip": nouvelle_ip, "masque": ""} if r else None


def shure_net_get(ip, delai=2.5, port=None):
    """Shure ULX-D : « < GET NET_SETTINGS SC > » en TCP sur le port 2202."""
    import socket
    port = port or PORTS_IP["shure"]
    try:
        sk = socket.create_connection((ip, port), timeout=delai)
    except OSError:
        return None
    res = None
    try:
        sk.settimeout(0.4)
        sk.sendall(b"< GET NET_SETTINGS SC >")
        buf = ""
        t0 = time.time()
        while time.time() - t0 < delai and res is None:
            try:
                d_ = sk.recv(2048)
            except socket.timeout:
                continue
            if not d_:
                break
            buf += d_.decode("ascii", "ignore")
            m = re.search(r"<\s*REP\s+NET_SETTINGS\s+SC\s+(\w+)\s+(\d+\.\d+\.\d+\.\d+)\s+(\d+\.\d+\.\d+\.\d+)\s+(\d+\.\d+\.\d+\.\d+)", buf)
            if m:
                res = {"mode": m.group(1), "ip": _ip_nette(m.group(2)), "masque": _ip_nette(m.group(3)),
                       "gw": _ip_nette(m.group(4))}
    except OSError:
        res = None
    finally:
        try:
            sk.close()
        except OSError:
            pass
    return res


_SHURE_DIAG = {}           # dernier échange de shure_net_set : ordre envoyé, réponse brute, état à l'ancienne adresse



def shure_net_set(ip, nouvelle_ip, masque, passerelle, port=None):
    """« < SET NET_SETTINGS SC MANUAL ip masque passerelle > », puis on se reconnecte à la nouvelle adresse pour vérifier."""
    import socket
    port = port or PORTS_IP["shure"]
    try:
        sk = socket.create_connection((ip, port), timeout=2.5)
    except OSError:
        return None
    _SHURE_DIAG.clear()
    envoi = f"< SET NET_SETTINGS SC MANUAL {_ip_pad(nouvelle_ip)} {_ip_pad(masque)} {_ip_pad(passerelle)} >"
    _SHURE_DIAG["envoye"] = envoi
    recu = ""
    try:
        sk.sendall(envoi.encode("ascii"))
        sk.settimeout(0.3)
        t0 = time.time()
        while time.time() - t0 < 1.5:                      # on lit ce que l'appareil répond (erreur, acceptation…)
            try:
                d_ = sk.recv(2048)
            except socket.timeout:
                continue
            if not d_:
                break
            recu += d_.decode("ascii", "ignore")
    except OSError:
        pass
    finally:
        try:
            sk.close()
        except OSError:
            pass
    _SHURE_DIAG["recu"] = recu.strip()
    time.sleep(1.0)
    r = shure_net_get(nouvelle_ip, delai=4.0, port=port)
    if r:
        return {"ip": r["ip"], "masque": r["masque"]}
    _SHURE_DIAG["ancien"] = shure_net_get(ip, delai=3.0, port=port)      # l'appareil répond-il encore à l'ancienne adresse ?
    return None


def shure_net_auto(ip, port=None):
    """Passe un Shure en DHCP : « < SET NET_SETTINGS SC AUTO na na na > » (« na » = sans objet en mode AUTO).
    Renvoie True si la commande a pu être envoyée."""
    import socket
    port = port or PORTS_IP["shure"]
    try:
        sk = socket.create_connection((ip, port), timeout=2.5)
    except OSError:
        return False
    try:
        sk.sendall(b"< SET NET_SETTINGS SC AUTO na na na >")
        time.sleep(0.6)
        return True
    except OSError:
        return False
    finally:
        try:
            sk.close()
        except OSError:
            pass


def detecter_protocoles_ip(ip):
    """Interroge l'appareil avec chaque protocole ouvert connu (en parallèle, sans rien changer).
    Renvoie {"artnet": {...}, "coda": {...}, "shure": {...}} avec seulement ceux qui répondent."""
    res = {}

    def lance(nom, fn):
        try:
            r = fn()
        except Exception:  # noqa: BLE001
            r = None
        if r:
            res[nom] = r
    ths = [threading.Thread(target=lance, args=(n, f), daemon=True) for n, f in (
        ("artnet", lambda: artnet_ipprog(ip, 0, delai=2.0)), ("coda", lambda: coda_devinfo(ip)),
        ("shure", lambda: shure_net_get(ip)), ("lacoustics", lambda: lac_devinfo(ip)))]
    for th in ths:
        th.start()
    for th in ths:
        th.join(5)
    return res


def ptp_decoder(data):
    """En-tête PTP version 2 (IEEE 1588-2008, 34 octets) + corps d'un Announce. None si ce n'est pas du PTPv2."""
    if len(data) < 34 or (data[1] & 0x0F) != 2:
        return None
    typ = data[0] & 0x0F
    ident = ":".join(f"{b:02x}" for b in data[20:28])
    res = {"type": typ, "nom": PTP_TYPES.get(typ, f"0x{typ:X}"), "dom": data[4], "ident": ident,
           "port": int.from_bytes(data[28:30], "big"), "seq": int.from_bytes(data[30:32], "big"),
           "deux_temps": bool(data[6] & 0x02)}
    if typ == 0xB and len(data) >= 64:
        res["gm"] = {"p1": data[47], "classe": data[48], "precision": data[49], "p2": data[52],
                     "id": ":".join(f"{b:02x}" for b in data[53:61]),
                     "pas": int.from_bytes(data[61:63], "big"), "source": data[63]}
    return res


MANET_GROUPES = tuple(f"{b}.4.1.{i}" for b in (236, 239) for i in range(5))
F_MONO = "Menlo"
ART_OPS = {0x2000: "ArtPoll", 0x2100: "ArtPollReply", 0x5000: "ArtDmx", 0x5100: "ArtNzs", 0x5200: "ArtSync",
           0x6000: "ArtAddress", 0x6100: "ArtInput", 0x7000: "ArtTodRequest", 0x8000: "ArtTimeCode",
           0x9700: "ArtTrigger", 0xF000: "ArtFirmwareMaster"}


def _osc_chaine(data, i):
    j = data.index(b"\x00", i)
    return data[i:j].decode("utf-8", "replace"), i + ((j - i + 4) // 4) * 4


def osc_decoder(data):
    """Lit un paquet OSC (message seul ou « bundle ») : renvoie une liste de (adresse, [valeurs])."""
    sortie = []

    def lire(paquet):
        if paquet.startswith(b"#bundle\x00"):
            i = 16
            while i + 4 <= len(paquet):
                n = struct.unpack(">i", paquet[i:i + 4])[0]
                i += 4
                if n <= 0 or i + n > len(paquet):
                    break
                lire(paquet[i:i + n])
                i += n
            return
        if not paquet.startswith(b"/"):
            raise ValueError("pas de l'OSC")
        adresse, i = _osc_chaine(paquet, 0)
        if i >= len(paquet) or paquet[i:i + 1] != b",":
            sortie.append((adresse, []))
            return
        tags, i = _osc_chaine(paquet, i)
        args = []
        for c in tags[1:]:
            if c == "i":
                args.append(struct.unpack(">i", paquet[i:i + 4])[0]); i += 4
            elif c == "f":
                args.append(struct.unpack(">f", paquet[i:i + 4])[0]); i += 4
            elif c in "sS":
                v, i = _osc_chaine(paquet, i); args.append(v)
            elif c == "b":
                n = struct.unpack(">i", paquet[i:i + 4])[0]
                args.append(f"blob {n} o"); i += 4 + ((n + 3) // 4) * 4
            elif c == "h":
                args.append(struct.unpack(">q", paquet[i:i + 8])[0]); i += 8
            elif c == "d":
                args.append(struct.unpack(">d", paquet[i:i + 8])[0]); i += 8
            elif c == "t":
                args.append("date"); i += 8
            elif c == "c":
                args.append(chr(struct.unpack(">i", paquet[i:i + 4])[0])); i += 4
            elif c in "rm":
                args.append("•"); i += 4
            elif c == "T":
                args.append(True)
            elif c == "F":
                args.append(False)
            elif c == "N":
                args.append(None)
            elif c == "I":
                args.append(float("inf"))
            else:
                break
        sortie.append((adresse, args))
    try:
        lire(bytes(data))
    except (struct.error, ValueError, IndexError):
        pass
    return sortie


def osc_valeur_texte(args, virgule=False):
    """Valeurs d'un message OSC écrites en une ligne (3 décimales au plus)."""
    morceaux = []
    for v in args:
        if isinstance(v, bool):
            morceaux.append("on" if v else "off")
        elif isinstance(v, float):
            s = f"{v:.3f}".rstrip("0").rstrip(".")
            s = "0" if s in ("", "-", "-0") else s
            morceaux.append(s.replace(".", ",") if virgule else s)
        elif v is None:
            morceaux.append("nil")
        else:
            morceaux.append(str(v))
    return "  ".join(morceaux)


def osc_jauge(args):
    """Position (0 à 1) à montrer sur la jauge : premier nombre entre 0 et 1 (fader, mute…), sinon None."""
    for v in args:
        if isinstance(v, bool):
            return 1.0 if v else 0.0
        if isinstance(v, (int, float)):
            return float(v) if 0.0 <= v <= 1.0 else None
        return None
    return None


def artnet_decoder(data):
    """Lit un paquet Art-Net : renvoie un dict (op, nom, et pour ArtDmx : univ, dmx) ou None."""
    data = bytes(data)
    if len(data) < 12 or data[:8] != b"Art-Net\x00":
        return None
    op = struct.unpack("<H", data[8:10])[0]
    res = {"op": op, "nom": ART_OPS.get(op, f"0x{op:04X}")}
    if op == 0x5000 and len(data) >= 18:
        n = struct.unpack(">H", data[16:18])[0]
        res["univ"] = data[14] | (data[15] << 8)
        res["seq"] = data[12]
        res["dmx"] = data[18:18 + n]
    elif op == 0x2100 and len(data) >= 44:
        res["court"] = data[26:44].split(b"\x00")[0].decode("utf-8", "replace")
    return res


def artnet_barres(dmx, n=64):
    """512 canaux résumés en `n` barres (niveau le plus haut de chaque groupe), valeurs de 0 à 255."""
    dmx = bytes(dmx).ljust(512, b"\x00")[:512]
    pas = 512 // n
    return [max(dmx[i * pas:(i + 1) * pas]) for i in range(n)]


# ----- MIDI : lecture des messages (octets bruts) -----
MIDI_MSGS = ("NOTE_OFF", "NOTE_ON", "POLYPRESSURE", "CONTROLCHANGE", "PROGRAMCHANGE", "CHANNELPRESSURE", "PITCHBEND",
             "SYSTEMEXCLUSIVE", "QUARTERFRAME", "SONGPOSITION", "SONGSELECT", "TUNEREQUEST", "CLOCK", "START",
             "CONTINUE", "STOP", "ACTIVESENSING", "SYSTEMRESET")
_MIDI_VOIX = {0x80: "NOTE_OFF", 0x90: "NOTE_ON", 0xA0: "POLYPRESSURE", 0xB0: "CONTROLCHANGE", 0xC0: "PROGRAMCHANGE",
              0xD0: "CHANNELPRESSURE", 0xE0: "PITCHBEND"}
_MIDI_SYS = {0xF0: "SYSTEMEXCLUSIVE", 0xF1: "QUARTERFRAME", 0xF2: "SONGPOSITION", 0xF3: "SONGSELECT",
             0xF6: "TUNEREQUEST", 0xF8: "CLOCK", 0xFA: "START", 0xFB: "CONTINUE", 0xFC: "STOP",
             0xFE: "ACTIVESENSING", 0xFF: "SYSTEMRESET"}
_NOTES = ("C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B")


def midi_nom_note(n, do_central="C4"):
    """Numéro de note MIDI -> nom (60 = C4, ou C3 selon la convention du pupitre/logiciel)."""
    decal = 1 if do_central == "C4" else 2
    return f"{_NOTES[n % 12]}{n // 12 - decal}"


def midi_decoder(msg):
    """Lit un message MIDI (liste d'octets). Renvoie un dict : type, canal (1 à 16, None pour les messages système),
    d1, d2, cle (identifie la « ligne » du tableau), niveau (0 à 1, pour la jauge) ; ou None si ce n'est pas du MIDI."""
    msg = [int(b) & 0xFF for b in msg]
    if not msg or msg[0] < 0x80:
        return None
    s = msg[0]
    d1 = msg[1] if len(msg) > 1 else 0
    d2 = msg[2] if len(msg) > 2 else 0
    if s < 0xF0:
        typ, canal = _MIDI_VOIX[s & 0xF0], (s & 0x0F) + 1
        if typ == "NOTE_ON" and d2 == 0:                 # note-on de vélocité 0 = note-off
            typ = "NOTE_OFF"
        if typ in ("NOTE_ON", "NOTE_OFF"):
            cle, niveau = ("NOTE", canal, d1), (d2 / 127 if typ == "NOTE_ON" else 0.0)
        elif typ == "POLYPRESSURE":
            cle, niveau = (typ, canal, d1), d2 / 127
        elif typ == "CONTROLCHANGE":
            cle, niveau = (typ, canal, d1), d2 / 127
        elif typ == "PROGRAMCHANGE":
            cle, niveau = (typ, canal), d1 / 127
        elif typ == "CHANNELPRESSURE":
            cle, niveau = (typ, canal), d1 / 127
        else:  # PITCHBEND : 14 bits
            cle, niveau = (typ, canal), ((d1 | (d2 << 7)) / 16383)
        return {"type": typ, "canal": canal, "d1": d1, "d2": d2, "cle": cle, "niveau": min(1.0, niveau)}
    typ = _MIDI_SYS.get(s)
    if typ is None:
        return None
    res = {"type": typ, "canal": None, "d1": d1, "d2": d2, "cle": (typ,), "niveau": None}
    if typ == "SYSTEMEXCLUSIVE":
        res["octets"] = len(msg)
    return res


def midi_libelle(r, noms=False, do_central="C4"):
    """Texte de la première colonne : « ch 1 · CC 7 », « ch 3 · Note C4 », « CLOCK »…"""
    typ, canal = r["type"], r["canal"]
    pref = f"ch {canal} · " if canal else ""
    if typ in ("NOTE_ON", "NOTE_OFF", "POLYPRESSURE"):
        n = midi_nom_note(r["d1"], do_central) if noms else str(r["d1"])
        return pref + (f"Note {n}" if typ != "POLYPRESSURE" else f"Poly {n}")
    if typ == "CONTROLCHANGE":
        return pref + f"CC {r['d1']}"
    if typ == "PROGRAMCHANGE":
        return pref + "PROGRAM"
    if typ == "CHANNELPRESSURE":
        return pref + "CHANNEL PRESSURE"
    if typ == "PITCHBEND":
        return pref + "PITCHBEND"
    return typ


def midi_valeur_texte(r, hexa=False):
    """Texte de la colonne « valeur » pour un message MIDI."""
    def f(v):
        return f"0x{v:02X}" if hexa else str(v)
    typ = r["type"]
    if typ == "NOTE_ON":
        return "ON · vel " + f(r["d2"]) if r["d2"] else "OFF"
    if typ == "NOTE_OFF":
        return "OFF"
    if typ in ("POLYPRESSURE", "CONTROLCHANGE"):
        return f(r["d2"])
    if typ in ("PROGRAMCHANGE", "CHANNELPRESSURE", "SONGSELECT"):
        return f(r["d1"])
    if typ in ("PITCHBEND", "SONGPOSITION"):
        v = r["d1"] | (r["d2"] << 7)
        return f"0x{v:04X}" if hexa else str(v)
    if typ == "QUARTERFRAME":
        return f"{r['d1'] >> 4}:{r['d1'] & 15}"
    if typ == "SYSTEMEXCLUSIVE":
        return t("midi_octets", n=r.get("octets", 0))
    return ""


