def artnet_famille(nom):
    """Nom de la case à cocher qui gouverne un type de paquet Art-Net (les types peu courants sont regroupés)."""
    return nom if nom in ART_OPS.values() else ART_AUTRES


def stats_latence(points):
    """points : liste de ms (ou None = pas de réponse). Renvoie (min, moyenne, max, % de pertes) ou None s'il n'y a rien."""
    if not points:
        return None
    bons = [p for p in points if p is not None]
    perte = round(100 * (len(points) - len(bons)) / len(points))
    if not bons:
        return (0.0, 0.0, 0.0, perte)
    return (min(bons), sum(bons) / len(bons), max(bons), perte)


def ordre_chaine(trouves, tri):
    """Ordre des appareils dans la vue « chaîne » : 'ip' (adresse) ou 'ms' (temps de réponse croissant, sans réponse à la fin)."""
    if tri == "ms":
        return sorted(trouves, key=lambda d: (d["ms"] is None, d["ms"] or 0, tuple(int(x) for x in d["ip"].split("."))))
    return sorted(trouves, key=lambda d: tuple(int(x) for x in d["ip"].split(".")))


