def enregistrer_polices():
    """Rend les polices du dossier « polices » utilisables par l'app (rien n'est installé sur le Mac)."""
    dossier = None
    for d in (RESSOURCES, os.path.join(RESSOURCES, "assets")):
        c = os.path.join(d, "polices")
        if os.path.isdir(c):
            dossier = c
            break
    if not dossier:
        return
    try:
        import ctypes
        import ctypes.util
        ct = ctypes.cdll.LoadLibrary(ctypes.util.find_library("CoreText"))
        cf = ctypes.cdll.LoadLibrary(ctypes.util.find_library("CoreFoundation"))
        cf.CFURLCreateFromFileSystemRepresentation.restype = ctypes.c_void_p
        cf.CFURLCreateFromFileSystemRepresentation.argtypes = [ctypes.c_void_p, ctypes.c_char_p,
                                                               ctypes.c_long, ctypes.c_bool]
        ct.CTFontManagerRegisterFontsForURL.restype = ctypes.c_bool
        ct.CTFontManagerRegisterFontsForURL.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_void_p]
        for nom in sorted(os.listdir(dossier)):
            if nom.lower().endswith((".ttf", ".otf")):
                chemin = os.path.join(dossier, nom).encode("utf-8")
                url = cf.CFURLCreateFromFileSystemRepresentation(None, chemin, len(chemin), False)
                ct.CTFontManagerRegisterFontsForURL(url, 1, None)  # 1 = seulement pour cette application
    except Exception:
        journal_exc()


def choisir_polices():
    """Si une police embarquée n'a pas pu être chargée, on prend une police de secours du Mac."""
    global F_TITRE, F_TEXTE, F_SAISIE
    try:
        import tkinter.font as tkfont
        dispo = set(tkfont.families())
    except Exception:
        return
    if F_TITRE not in dispo:
        F_TITRE = REPLI["Lilita One"]
    if F_TEXTE not in dispo:
        F_TEXTE = REPLI["Gochi Hand"]
    if F_SAISIE not in dispo:
        F_SAISIE = REPLI["Patrick Hand"]


def tronquer(texte, n):
    return texte if len(texte) <= n else texte[: n - 1] + "…"


_CACHE_CONTOUR = {}


def contour(x1, y1, x2, y2, r=14, graine=1, amp=2.2, pas=70):
    """Points d'un rectangle arrondi dessiné à la main (à utiliser avec smooth=True). Résultat gardé en mémoire :
    redessiner une fenêtre (changement d'onglet, de thème) ne recalcule plus ces centaines de formes."""
    cle = (x1, y1, x2, y2, r, graine, amp, pas)
    r_ = _CACHE_CONTOUR.get(cle)
    if r_ is None:
        if len(_CACHE_CONTOUR) > 4000:
            _CACHE_CONTOUR.clear()
        r_ = _CACHE_CONTOUR[cle] = _contour_calcul(*cle)
    return list(r_)


def _contour_calcul(x1, y1, x2, y2, r=14, graine=1, amp=2.2, pas=70):
    rnd = random.Random(graine)
    cotes = [((x1 + r, y1), (x2 - r, y1), (x2, y1)),
             ((x2, y1 + r), (x2, y2 - r), (x2, y2)),
             ((x2 - r, y2), (x1 + r, y2), (x1, y2)),
             ((x1, y2 - r), (x1, y1 + r), (x1, y1))]
    pts = []
    for a, b, coin in cotes:
        n = max(1, int(math.hypot(b[0] - a[0], b[1] - a[1]) // pas))
        for k in range(n + 1):
            t = k / n
            pts += [a[0] + (b[0] - a[0]) * t + rnd.uniform(-amp, amp),
                    a[1] + (b[1] - a[1]) * t + rnd.uniform(-amp, amp)]
        pts += [coin[0] + rnd.uniform(-amp, amp) * .6, coin[1] + rnd.uniform(-amp, amp) * .6]
    return pts


def tourner(points, cx, cy, degres):
    a = math.radians(degres)
    c, s = math.cos(a), math.sin(a)
    sortie = []
    for i in range(0, len(points), 2):
        dx, dy = points[i] - cx, points[i + 1] - cy
        sortie += [cx + dx * c - dy * s, cy + dx * s + dy * c]
    return sortie


def points_etoile(cx, cy, r, rot=0, branches=5, creux=0.45):
    pts = []
    for i in range(branches * 2):
        rayon = r if i % 2 == 0 else r * creux
        a = math.radians(rot - 90 + i * 180 / branches)
        pts += [cx + rayon * math.cos(a), cy + rayon * math.sin(a)]
    return pts


def points_eclair(cx, cy, s, rot=0):
    base = [(0.15, -1.0), (-0.55, 0.12), (-0.08, 0.12), (-0.32, 1.0), (0.58, -0.22), (0.1, -0.22), (0.5, -1.0)]
    pts = []
    for x, y in base:
        pts += [cx + x * s, cy + y * s]
    return tourner(pts, cx, cy, rot)


def asset(nom):
    for dossier in (RESSOURCES, os.path.join(RESSOURCES, "assets")):
        chemin = os.path.join(dossier, nom)
        if os.path.exists(chemin):
            return chemin
    return None


def melange(c1, c2, t):
    """Couleur intermédiaire entre deux couleurs « #rrggbb » (t = 0 → c1, t = 1 → c2)."""
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(int(round(x + (y - x) * t)) for x, y in zip(a, b))


def couper_haut(pts, ycut):
    """Garde la partie d'un polygone située au-dessus de la ligne y = ycut (pour les paupières)."""
    sortie = []
    n = len(pts)
    for i in range(n):
        a, b = pts[i], pts[(i + 1) % n]
        a_ok, b_ok = a[1] <= ycut, b[1] <= ycut
        if a_ok:
            sortie.append(a)
        if a_ok != b_ok and b[1] != a[1]:
            u = (ycut - a[1]) / (b[1] - a[1])
            sortie.append((a[0] + u * (b[0] - a[0]), ycut))
    return sortie


def a_plat(points):
    return [c for p in points for c in p]


def croissant(cx, cy, r, decal=(0.5, -0.35), r2=0.82, n=36):
    """Points d'un croissant de lune (lune pleine moins un disque décalé)."""
    ix, iy, ri = decal[0] * r, decal[1] * r, r2 * r
    ext = []
    for k in range(n):
        a = 2 * math.pi * k / n
        ext.append((r * math.cos(a), r * math.sin(a)))
    garde = [(math.hypot(x - ix, y - iy) >= ri) for x, y in ext]
    if all(garde):
        return [(cx + x, cy + y) for x, y in ext]
    depart = next(i for i in range(n) if garde[i] and not garde[i - 1])
    ordre = [ext[(depart + k) % n] for k in range(n) if garde[(depart + k) % n]]
    inter = []
    for k in range(n * 2):
        a = 2 * math.pi * k / (n * 2)
        x, y = ix + ri * math.cos(a), iy + ri * math.sin(a)
        if math.hypot(x, y) <= r:
            inter.append((x, y))
    # on relie la fin de l'arc extérieur au bon bout de l'arc intérieur
    fin = ordre[-1]
    inter.sort(key=lambda p: math.atan2(p[1] - iy, p[0] - ix))
    # rotation pour que le premier point soit le plus proche de la fin de l'arc extérieur
    j = min(range(len(inter)), key=lambda q: math.hypot(inter[q][0] - fin[0], inter[q][1] - fin[1]))
    # on cherche le sens qui finit près du début de l'arc extérieur
    a1 = inter[j:] + inter[:j]
    a2 = [a1[0]] + a1[:0:-1]
    debut = ordre[0]
    cand = min((a1, a2), key=lambda L: math.hypot(L[-1][0] - debut[0], L[-1][1] - debut[1]))
    return [(cx + x, cy + y) for x, y in ordre + cand]


def facilite(u):
    """Courbes d'accélération (u entre 0 et 1)."""
    return max(0.0, min(1.0, u))


