class AideSurvol:
    """Une petite bulle d'aide, discrète, quand le pointeur reste immobile (0,7 s) sur un élément du canevas.
    `tags` : {tag du dessin: clé de AIDES_TEXTES}. Rien n'est lié élément par élément : un seul suivi du pointeur,
    donc ça ne ralentit pas le survol des boutons."""
    DELAI = 0.7
    LARGEUR_MAX = 230

    def __init__(self, cv, tags=None, bornes=None):
        self.cv = cv
        self.base = getattr(cv, "_c", cv)                 # le vrai canvas Tk (coordonnées en pixels réels)
        self.tags = dict(tags or {})
        self.bornes = bornes
        self.pos = None
        self.t_bouge = 0.0
        self.minuteur = None
        self.cible = None                                  # (tag, zone réelle) de la bulle affichée
        cv.bind("<Motion>", self._bouge, add="+")
        cv.bind("<Leave>", lambda e: self.cacher(), add="+")
        cv.bind("<ButtonPress>", self._clic, add="+")
        self.bloque = False                                # après un clic : pas de bulle tant que le pointeur n'a pas bougé
        self.garde = None
        try:
            cv.winfo_toplevel().bind("<FocusOut>", lambda e: self.cacher(), add="+")
        except Exception:  # noqa: BLE001
            journal_exc()

    def _clic(self, e=None):
        self.bloque = True
        self.cacher()

    def _pointeur_sur_moi(self):
        """Le pointeur est-il vraiment sur ce canevas ? (une autre fenêtre ouverte par-dessus, comme le Radar, n'envoie
        aucun « la souris sort » : la bulle restait alors affichée jusqu'à la fermeture de cette fenêtre.)"""
        try:
            b = self.base
            dessus = b.winfo_containing(b.winfo_pointerx(), b.winfo_pointery())
            return dessus is not None and (dessus is b or str(dessus).startswith(str(b)))
        except Exception:  # noqa: BLE001
            return True

    def _garder(self):
        self.garde = None
        if self.cible is None:
            return
        try:
            present = bool(self.base.find_withtag("aide_mini"))
            z = self.cible[1]
            px = self.base.winfo_pointerx() - self.base.winfo_rootx()
            py = self.base.winfo_pointery() - self.base.winfo_rooty()
            dedans = z[0] - 4 <= px <= z[2] + 4 and z[1] - 4 <= py <= z[3] + 4
        except Exception:  # noqa: BLE001
            self.cacher()
            return
        if not present or not dedans or not self._pointeur_sur_moi():
            self.cacher()
            return
        self.garde = self.base.after(250, self._garder)

    def _cle(self, tag):
        if tag in self.tags:
            return self.tags[tag]
        for p, k in self.tags.items():
            if p.endswith("*") and tag.startswith(p[:-1]):
                return k
        return None

    def cacher(self):
        self.cible = None
        if self.garde is not None:
            try:
                self.base.after_cancel(self.garde)
            except Exception:  # noqa: BLE001
                journal_exc()
            self.garde = None
        try:
            self.cv.delete("aide_mini")
        except Exception:  # noqa: BLE001
            journal_exc()

    def _bouge(self, e):
        p = self.pos
        if self.bloque and (p is None or abs(e.x - p[0]) + abs(e.y - p[1]) >= 3):
            self.bloque = False                            # le pointeur a vraiment bougé : la bulle peut revenir
        self.pos = (e.x, e.y)
        self.t_bouge = time.time()
        if self.cible is not None:
            try:
                present = bool(self.base.find_withtag("aide_mini"))
                z = self.cible[1]
            except Exception:  # noqa: BLE001
                present, z = False, (0, 0, 0, 0)
            if present and z[0] - 4 <= e.x <= z[2] + 4 and z[1] - 4 <= e.y <= z[3] + 4:
                return
            self.cacher()
        if self.minuteur is None:
            try:
                self.minuteur = self.base.after(250, self._verif)
            except Exception:  # noqa: BLE001
                self.minuteur = None

    def _verif(self):
        self.minuteur = None
        reste = self.DELAI - (time.time() - self.t_bouge)
        if reste > 0.03:
            try:
                self.minuteur = self.base.after(int(reste * 1000) + 20, self._verif)
            except Exception:  # noqa: BLE001
                journal_exc()
            return
        self._montrer()

    def _montrer(self):
        if self.cible is not None or not self.pos or self.bloque:
            return
        base = self.base
        if not self._pointeur_sur_moi():
            return
        try:
            if base.find_withtag("menu_bd") or base.find_withtag("menu_cartes") or base.find_withtag("bulle_nom"):
                return
            x, y = self.pos
            trouve = None
            for it in reversed(base.find_overlapping(x - 1, y - 1, x + 1, y + 1)):
                tgs = base.gettags(it)
                if "aide_mini" in tgs:
                    return
                for tg in tgs:
                    k = self._cle(tg)
                    if k:
                        trouve = (tg, k)
                        break
                if trouve:
                    break
            if not trouve:
                return
            tg, k = trouve
            texte = aide_texte(k)
            zone_r = base.bbox(tg)
            zone = self.cv.bbox(tg)
            if not texte or not zone or not zone_r:
                return
            self._dessiner(zone, texte)
            self.cible = (tg, zone_r)
            self.garde = base.after(250, self._garder)
        except Exception as ex:  # noqa: BLE001
            print("aide :", repr(ex), file=sys.stderr)

    def _bornes(self):
        if self.bornes:
            return self.bornes
        try:
            return (0, 0, int(self.base.winfo_width()), int(self.base.winfo_height()))
        except Exception:  # noqa: BLE001
            return (0, 0, 760, 420)

    def _dessiner(self, zone, texte):
        cv = self.cv
        tag = ("aide_mini",)
        bx1_, by1_, bx2_, by2_ = self._bornes()
        police = (F_TEXTE, 14)
        mesure = cv.create_text(-3000, -3000, text=texte, font=police, width=self.LARGEUR_MAX)
        mb = cv.bbox(mesure)
        cv.delete(mesure)
        tw = (mb[2] - mb[0]) if mb else 160
        th = (mb[3] - mb[1]) if mb else 20
        L, H = tw + 22, th + 14
        cx = (zone[0] + zone[2]) / 2
        bx1 = max(bx1_ + 4, min(cx - L / 2, bx2_ - 4 - L))
        bx2 = bx1 + L
        dessus = zone[1] - 12 - H >= by1_ + 2
        if dessus:
            by2 = zone[1] - 10
            by1 = by2 - H
            bord, pointe = by2, zone[1] - 1
        else:
            by1 = zone[3] + 10
            by2 = by1 + H
            bord, pointe = by1, zone[3] + 1
        tx = max(bx1 + 16, min(cx, bx2 - 16))
        sens = 1 if dessus else -1                         # la base de la queue est du côté de la bulle
        queue_ = [tx - 8, bord - 2 * sens, cx if abs(cx - tx) < 12 else tx, pointe, tx + 6, bord - 2 * sens]
        cv.create_polygon(contour(bx1 + 3, by1 + 4, bx2 + 3, by2 + 4, 10, 521, 0.8, 50), smooth=True, fill=NOIR,
                          outline=NOIR, width=2, tags=tag)
        cv.create_polygon([q + (3 if i % 2 == 0 else 4) for i, q in enumerate(queue_)], fill=NOIR, outline=NOIR,
                          width=2, joinstyle="round", tags=tag)
        cv.create_polygon(contour(bx1, by1, bx2, by2, 10, 522, 1.0, 50), smooth=True, fill=BULLE_FOND, outline=NOIR,
                          width=2, joinstyle="round", tags=tag)
        cv.create_polygon(queue_, fill=BULLE_FOND, outline=NOIR, width=2, joinstyle="round", tags=tag)
        ligne = bord - 1.2 * sens
        cv.create_text((bx1 + bx2) / 2, (by1 + by2) / 2 + 0.5, text=texte, font=police, fill=BULLE_TEXTE,
                       width=self.LARGEUR_MAX, justify="center", tags=tag)



def tracer_queue_bd(cv, q, tags):
    """Queue de bulle ouverte (un « V » au trait épais, intérieur crème) : elle se fond dans le bord de la bulle.
    Le remplissage crème coupe le bord (et l'ombre) sous la queue ; seuls les deux côtés du V sont tracés."""
    cv.create_polygon(q, fill=BULLE_FOND, outline="", tags=tags)
    cv.create_line([q[0], q[1], q[2], q[3], q[4], q[5]], fill=NOIR, width=3, joinstyle="round", capstyle="round", tags=tags)


def cv_existe(cv, tag):
    """Vrai s'il reste au moins un élément portant ce tag."""
    try:
        return bool(cv.find_withtag(tag))
    except Exception:  # noqa: BLE001
        return False


class CadenceAdaptative:
    """Choisit le rythme d'une animation d'après ce que l'ordinateur supporte VRAIMENT.

    Mesurer seulement le temps passé dans notre code ne suffit pas : une grande partie du coût d'une image est le
    dessin de Tk, qui a lieu juste après (sur Mac il peut être important). On mesure donc aussi le « retard » : le temps
    réellement écoulé entre deux images moins ce qu'on avait prévu (dessin, autres tâches, Mac chargé).
    Occupation d'une image = travail + retard. Le délai visé est 2,2 × cette occupation (le processeur reste libre
    plus de la moitié du temps), jamais moins que la cadence de base. La charge générale du Mac est prise en compte.
    Descend vite quand ça rame, remonte doucement. Les mouvements sont calculés d'après l'heure réelle : seule la
    finesse change, jamais la vitesse de l'animation."""

    def __init__(self, base_ms, plafond_ms=200.0):
        self.base, self.plafond = float(base_ms), float(plafond_ms)
        self.occup = 0.0
        self.cible = self.base
        self._debut_prec = None
        self._prevu = 0.0
        self._cpu_t, self._cpu_f = 0.0, 1.0

    def _facteur_cpu(self, maintenant):
        if maintenant - self._cpu_t > 5.0:                 # on sonde la charge générale du Mac toutes les 5 s
            self._cpu_t = maintenant
            try:
                ch = os.getloadavg()[0] / max(1, os.cpu_count() or 1)
            except (OSError, AttributeError):
                ch = 0.0
            self._cpu_f = 1.0 if ch < 0.7 else (1.3 if ch < 1.2 else 1.8)
        return self._cpu_f

    def fps(self):
        return 1000.0 / max(1.0, self.cible)

    def suivant(self, debut, travail_ms, base_ms=None):
        """`debut` = time.perf_counter() au début de l'image, `travail_ms` = sa durée côté Python.
        Renvoie le délai (ms) à attendre avant la prochaine image."""
        base = float(base_ms) if base_ms else self.base
        retard = 0.0
        if self._debut_prec is not None:
            reel = (debut - self._debut_prec) * 1000.0
            if reel < 1000.0:                              # au-delà : fenêtre cachée ou Mac en veille, on ignore
                retard = max(0.0, min(300.0, reel - self._prevu))
        self._debut_prec = debut
        occ = travail_ms + retard
        if self.occup <= 0.0:
            self.occup = occ
        elif occ > self.occup:
            self.occup = 0.6 * self.occup + 0.4 * occ      # ça rame : on réagit vite
        else:
            self.occup = 0.97 * self.occup + 0.03 * occ    # ça va mieux : on remonte doucement
        self.cible = max(base, min(self.plafond, 2.2 * self.occup * self._facteur_cpu(time.time())))
        delai = max(4, int(self.cible - travail_ms))
        self._prevu = delai + travail_ms
        return delai


class ToileEchelle:
    """Enveloppe d'un canvas Tk : tout le dessin est écrit en « coordonnées logiques » (la fenêtre de 1140 x 860),
    et cette enveloppe l'agrandit (ou le réduit) pour la taille réelle de la fenêtre :
    positions, tailles de police et épaisseurs de trait sont multipliées par `k`, puis décalées de (ox, oy)
    pour que le dessin reste centré."""

    def __init__(self, vraie):
        self._c = vraie
        self.k = 1.0
        self.ox = 0.0
        self.oy = 0.0

    def regler(self, k, ox, oy):
        self.k, self.ox, self.oy = float(k), float(ox), float(oy)

    def __getattr__(self, nom):                  # tout le reste (delete, bind, tag_bind, configure…) passe tel quel
        if nom == "_c":
            raise AttributeError(nom)
        return getattr(self._c, nom)

    @staticmethod
    def _plat(args):
        sortie = []
        for a in args:
            if isinstance(a, (list, tuple)):
                sortie += ToileEchelle._plat(a)
            else:
                sortie.append(a)
        return sortie

    def _xy(self, args):
        return [(self.ox if i % 2 == 0 else self.oy) + c * self.k for i, c in enumerate(self._plat(args))]

    def _opts(self, kw):
        o = dict(kw)
        for cle in ("width", "height"):
            if isinstance(o.get(cle), (int, float)):
                o[cle] = o[cle] * self.k
        f = o.get("font")
        if isinstance(f, (tuple, list)) and len(f) >= 2 and isinstance(f[1], (int, float)):
            f = list(f)
            f[1] = max(1, int(round(f[1] * self.k)))
            o["font"] = tuple(f)
        return o

    @staticmethod
    def _lisser(xy, pas=4):
        """Courbe lisse d'un polygone (même rendu que smooth=True) calculée une seule fois ici : Tk n'a plus à
        recalculer toutes les courbes à chaque fois qu'un morceau de l'écran est redessiné."""
        n = len(xy) // 2
        if n >= 40:                  # contour déjà très dense : on garde moins de points (la peinture coûte par sommet)
            pas = 1
        elif n >= 20:
            pas = min(pas, 2)
        P = [(xy[2 * i], xy[2 * i + 1]) for i in range(n)]
        out = []
        for i in range(n):
            a, b, c = P[i - 1], P[i], P[(i + 1) % n]
            x0, y0 = (a[0] + b[0]) / 2, (a[1] + b[1]) / 2
            x2, y2 = (b[0] + c[0]) / 2, (b[1] + c[1]) / 2
            for k in range(1, pas + 1):
                u = k / pas
                v = 1 - u
                out += [v * v * x0 + 2 * u * v * b[0] + u * u * x2, v * v * y0 + 2 * u * v * b[1] + u * u * y2]
        return out

    def create_polygon(self, *a, **kw):
        xy = self._xy(a)
        o = self._opts(kw)
        if o.get("smooth") and len(xy) >= 12:
            xy = self._lisser(xy)
            o["smooth"] = False
            i = self._c.create_polygon(*xy, **o)
            self.__dict__.setdefault("_lisses", set()).add(i)
            return i
        return self._c.create_polygon(*xy, **o)

    def tag_bind(self, tag, sequence=None, func=None, add=None):
        """Comme Canvas.tag_bind, mais sans fuite : tkinter garde TOUTES les commandes Tcl qu'il crée (une par liaison)
        jusqu'à la fermeture de la fenêtre. Or l'écran se redessine souvent : sans ce ménage, des milliers de commandes
        s'accumulaient et l'application ralentissait peu à peu. Ici on libère l'ancienne commande quand une liaison est
        remplacée, et celles d'un élément quand il est supprimé."""
        if func is None:
            return self._c.tag_bind(tag, sequence, func, add)
        liens = self.__dict__.setdefault("_liens", {})
        cle = (str(tag), sequence)
        anciens = liens.get(cle, [])
        nom = self._c.tag_bind(tag, sequence, func, add)
        if add in ("+", True):
            anciens.append(nom)
            liens[cle] = anciens
        else:
            self._liberer_plus_tard([a for a in anciens if a != nom])   # la nouvelle liaison a remplacé l'ancienne
            liens[cle] = [nom]
        if isinstance(tag, int) or str(tag).isdigit():
            self.__dict__.setdefault("_liens_id", set()).add(cle)
        return nom

    def _liberer_plus_tard(self, noms):
        """Libère des commandes Tcl devenues inutiles, mais pas tout de suite : Tk peut encore avoir un événement en
        attente qui les appelle (ex. « souris quitte l'élément » juste après un redessin). On attend, puis on ne
        supprime que ce qui n'est vraiment plus utilisé."""
        if not noms:
            return
        en_attente = self.__dict__.setdefault("_a_liberer", [])
        en_attente.extend(noms)
        if self.__dict__.get("_purge_prevue"):
            return
        self._purge_prevue = True

        def purger():
            self._purge_prevue = False
            vivants = set()
            for l_ in self.__dict__.get("_liens", {}).values():
                vivants.update(l_)
            lot, self._a_liberer = self.__dict__.get("_a_liberer", []), []
            for n_ in lot:
                if n_ in vivants:
                    continue
                try:
                    self._c.deletecommand(n_)
                except Exception:  # noqa: BLE001
                    journal_exc()
        try:
            self._c.after(1500, purger)
        except Exception:  # noqa: BLE001
            self._purge_prevue = False

    def _liens_liberer(self, ids):
        """Libère les commandes liées à des éléments (identifiants numériques) qui vont disparaître."""
        cles_id = self.__dict__.get("_liens_id")
        if not cles_id:
            return
        liens = self.__dict__.get("_liens", {})
        for cle in [c for c in cles_id if c[0] in ids]:
            self._liberer_plus_tard(liens.pop(cle, []))
            cles_id.discard(cle)

    def _groupes_etendre(self, a):
        """Pour une suppression : ajoute les lignes des textes repliés visés (ou oublie tous les groupes si « all »)."""
        gt = self.__dict__.get("_gt")
        if gt:
            if "all" in a:
                gt.clear()
            else:
                sup = []
                for x in a:
                    g = self._groupe(x)
                    if g is not None:
                        sup += g["ids"]
                        gt.pop(g["ids"][0], None)
                if sup:
                    a = tuple(a) + tuple(sup)
        return a

    def delete(self, *a):
        a = self._groupes_etendre(a)
        if "all" in a:
            self.__dict__.setdefault("_lisses", set()).clear()
        if self.__dict__.get("_liens_id") or self.__dict__.get("_lisses"):
            try:
                ids = set()
                for x in a:
                    ids.update(str(i) for i in (self._c.find_all() if x == "all" else self._c.find_withtag(x)))
                self._liens_liberer(ids)
                if "all" not in a and self.__dict__.get("_lisses"):
                    self._lisses.difference_update(int(i) for i in ids)
            except Exception:  # noqa: BLE001
                journal_exc()
        return self._c.delete(*a)

    def create_line(self, *a, **kw):
        return self._c.create_line(*self._xy(a), **self._opts(kw))

    def create_oval(self, *a, **kw):
        return self._c.create_oval(*self._xy(a), **self._opts(kw))

    def create_arc(self, *a, **kw):
        return self._c.create_arc(*self._xy(a), **self._opts(kw))

    # ----- texte replié : interligne resserré entre les lignes d'une même phrase -----
    # Tk n'offre aucun réglage d'interligne. Quand un texte (avec `width`) passe réellement à la ligne, on le dessine donc
    # ligne par ligne : espace réduit entre deux lignes de la MÊME phrase, espace normal avant un nouveau paragraphe (\n).
    # Un texte qui tient sur une ligne reste un élément Tk ordinaire.
    _RELAYER = ("text", "font", "width", "anchor", "justify")

    def create_text(self, x, y, **kw):
        inter = kw.pop("interligne", None)
        if inter is None:
            inter = INTERLIGNE
        o = self._opts(kw)
        px, py = self._xy((x, y))
        if inter < 0.999 and isinstance(o.get("text"), str) and o.get("width"):
            g = self._groupe_creer(px, py, o, inter)
            if g is not None:
                return g
        return self._c.create_text(px, py, **o)

    def _police(self, o):
        import tkinter.font as tkfont
        cache = self.__dict__.setdefault("_polices_g", {})
        f = o.get("font") or "TkDefaultFont"
        cle = tuple(f) if isinstance(f, (list, tuple)) else str(f)
        ent = cache.get(cle)
        if ent is None:
            fo = tkfont.Font(root=self._c, font=f)
            ent = cache[cle] = (fo, fo.metrics("linespace"))
        return ent

    @staticmethod
    def _plier(texte, mes, larg):
        """Découpe `texte` comme Tk (aux espaces, mot trop long coupé), renvoie [(ligne, début_de_paragraphe)].
        `mes(texte)` donne la largeur en pixels."""
        sortie = []
        for p, para in enumerate(texte.split("\n")):
            cour, premiere = "", True
            for mot in para.split(" "):
                essai = (cour + " " + mot) if cour else mot
                if not cour or mes(essai) <= larg:
                    cour = essai
                else:
                    sortie.append((cour, premiere or False))
                    premiere = False
                    cour = mot
                while mes(cour) > larg and len(cour) > 1:           # mot plus large que la zone : coupé
                    n = max(1, int(len(cour) * larg / max(1, mes(cour))))
                    sortie.append((cour[:n], premiere))
                    premiere = False
                    cour = cour[n:]
            sortie.append((cour, premiere))
        return sortie

    def _mesure(self, o):
        """Mesure de largeur de texte avec mémoire (Font.measure est lent : les mêmes mots reviennent à chaque redessin)."""
        fo, lh = self._police(o)
        cache = self.__dict__.setdefault("_mes_cache", {})
        if len(cache) > 6000:
            cache.clear()
        f = o.get("font") or "TkDefaultFont"
        cle_f = tuple(f) if isinstance(f, (list, tuple)) else str(f)

        def mes(txt):
            k = (cle_f, txt)
            v = cache.get(k)
            if v is None:
                v = cache[k] = fo.measure(txt)
            return v
        return mes, lh

    def _groupe_creer(self, px, py, o, inter):
        mes, lh = self._mesure(o)
        t_ = o["text"]
        if "\n" not in t_ and mes(t_) <= o["width"]:
            return None                                   # tient sur une ligne : élément Tk ordinaire (cas le plus courant)
        lignes = self._plier(t_, mes, o["width"])
        if not any(i > 0 and not deb for i, (_, deb) in enumerate(lignes)):
            return None                                   # rien ne passe à la ligne : élément Tk ordinaire
        g = {"px": px, "py": py, "o": dict(o), "inter": inter, "ids": []}
        self._groupe_poser(g)
        premier = g["ids"][0]
        gt = self.__dict__.setdefault("_gt", {})
        if len(gt) > 600:                                 # ménage : groupes dont les éléments ont été supprimés
            for k in [k for k in gt if not self._c.type(k)]:
                gt.pop(k, None)
        gt[premier] = g
        return premier

    def _groupe_poser(self, g):
        """(Re)dessine les lignes d'un groupe en réutilisant les éléments existants."""
        o, px, py, inter = g["o"], g["px"], g["py"], g["inter"]
        mes, lh = self._mesure(o)
        lignes = self._plier(o["text"], mes, o["width"])
        pas = [0.0]
        for i in range(1, len(lignes)):
            pas.append(pas[-1] + (lh if lignes[i][1] else lh * inter))
        haut = pas[-1] + lh
        larg = max(mes(l) for l, _ in lignes)
        a = o.get("anchor", "center")
        if a == "center":
            h_, v_ = "c", "c"
        else:
            h_ = "w" if "w" in a else ("e" if "e" in a else "c")
            v_ = "n" if "n" in a else ("s" if "s" in a else "c")
        y0 = py if v_ == "n" else (py - haut if v_ == "s" else py - haut / 2)
        x0 = px if h_ == "w" else (px - larg if h_ == "e" else px - larg / 2)
        just = o.get("justify", "left")
        opts = {k: v for k, v in o.items() if k not in ("text", "width", "anchor", "justify")}
        ids = g["ids"]
        for i, (l, _) in enumerate(lignes):
            if just == "center":
                xx, an = x0 + larg / 2, "n"
            elif just == "right":
                xx, an = x0 + larg, "ne"
            else:
                xx, an = x0, "nw"
            yy = y0 + pas[i]
            if i < len(ids):
                self._c.coords(ids[i], xx, yy)
                self._c.itemconfigure(ids[i], text=l or " ", anchor=an, **{k: v for k, v in opts.items() if k in ("font", "fill")})
            else:
                ids.append(self._c.create_text(xx, yy, text=l or " ", anchor=an, **opts))
        for extra in ids[len(lignes):]:
            self._c.delete(extra)
        del ids[len(lignes):]

    def _groupe(self, item):
        gt = self.__dict__.get("_gt")
        if not gt:
            return None
        try:
            return gt.get(int(item))
        except (TypeError, ValueError):
            return None

    def create_image(self, x, y, **kw):
        return self._c.create_image(*self._xy((x, y)), **self._opts(kw))

    def create_window(self, x, y, **kw):
        gel = self.__dict__.get("gel")
        if gel is not None and kw.get("state") != "hidden":
            # pendant une reconstruction, un composant natif (champ, liste) n'apparaît pas tout de suite : sur Mac il
            # s'affiche aussitôt, avant que le dessin soit peint, et on voit un cadre vide + la langue au premier plan
            kw["state"] = "hidden"
            i = self._c.create_window(*self._xy((x, y)), **self._opts(kw))
            gel.append(i)
            return i
        return self._c.create_window(*self._xy((x, y)), **self._opts(kw))

    def image_fond(self, x, y, image):
        """Image posée en pixels réels (le fond ne suit pas l'échelle)."""
        return self._c.create_image(x, y, image=image, anchor="nw", tags=("fond_tuile",))

    def coords(self, item, *a):
        g = self._groupe(item)
        if g is not None:
            if not a:
                return [(g["px"] - self.ox) / self.k, (g["py"] - self.oy) / self.k]
            g["px"], g["py"] = self._xy(a)
            self._groupe_poser(g)
            return None
        if not a:
            v = self._c.coords(item)
            return [((c - self.ox) if i % 2 == 0 else (c - self.oy)) / self.k for i, c in enumerate(v)]
        xy = self._xy(a)
        if item in self.__dict__.get("_lisses", ()) and len(xy) >= 12:
            xy = self._lisser(xy)
        return self._c.coords(item, *xy)

    def deplacer_tout(self, dx, dy):
        """Décale TOUT le dessin de (dx, dy) pixels écran, y compris l'origine mémorisée des textes à lignes multiples
        (sinon leur prochaine mise à jour se pose à l'ancien endroit, et les lignes s'empilent)."""
        self._c.move("all", dx, dy)
        self._c.move("fond_tuile", -dx, -dy)         # la texture de fond reste en place (elle couvre toute la fenêtre)
        for g in self.__dict__.get("_gt", {}).values():
            g["px"] += dx
            g["py"] += dy

    def move(self, tag, dx, dy):
        g = self._groupe(tag)
        if g is not None:
            g["px"] += dx * self.k
            g["py"] += dy * self.k
        return self._c.move(g["ids"] if g is not None and False else tag, dx * self.k, dy * self.k) if g is None else \
            [self._c.move(i, dx * self.k, dy * self.k) for i in g["ids"]] and None

    def bbox(self, *tags):
        g = self._groupe(tags[0]) if len(tags) == 1 else None
        if g is not None:
            bs = [self._c.bbox(i) for i in g["ids"]]
            bs = [b for b in bs if b]
            b = (min(b[0] for b in bs), min(b[1] for b in bs), max(b[2] for b in bs), max(b[3] for b in bs)) if bs else None
        else:
            b = self._c.bbox(*tags)
        if not b:
            return b
        return ((b[0] - self.ox) / self.k, (b[1] - self.oy) / self.k,
                (b[2] - self.ox) / self.k, (b[3] - self.oy) / self.k)

    def itemconfigure(self, item, **kw):
        g = self._groupe(item)
        if g is not None and kw:
            o = self._opts(kw)
            if any(c in o for c in self._RELAYER):
                g["o"].update({c: o.pop(c) for c in self._RELAYER if c in o})
            if "interligne" in kw:
                g["inter"] = kw["interligne"]
            if o:
                g["o"].update({c: v for c, v in o.items() if c in ("font", "fill")})
                for i in g["ids"]:
                    self._c.itemconfigure(i, **o)
            self._groupe_poser(g)
            return None
        return self._c.itemconfigure(item, **self._opts(kw))

    itemconfig = itemconfigure

    def itemcget(self, item, option):
        g = self._groupe(item)
        if g is not None and option == "text":
            return g["o"]["text"]
        return self._c.itemcget(item, option)

    def vers_logique(self, x, y):
        """Position de la souris (en pixels de la fenêtre) -> position dans le dessin."""
        return (x - self.ox) / self.k, (y - self.oy) / self.k


class TexteDessine:
    """Remplace un tk.Text : le texte est DESSINÉ sur le canvas (aucun widget natif permanent, donc pas de repeint
    complet de la fenêtre à chaque changement d'onglet). Même petite interface : delete / insert / tag_configure."""

    def __init__(self, app, x1, y1, x2, y2, taille=14, pad=8, barre=None, onglet=None):
        self.app, self.zone, self.taille, self.pad = app, (x1, y1, x2, y2), taille, pad
        self.barre, self.onglet_barre = barre, onglet      # barre : clé de la barre de défilement (None = aucune)
        self.unites, self.couleurs, self.decal = [], {}, 0
        self.tag = "td%d" % id(self)
        self._sale = False
        app.textes_dessines.append(self)

    def tag_configure(self, tag, foreground=None, **_kw):
        if foreground:
            self.couleurs[tag] = foreground

    def delete(self, *_a):
        self.unites, self.decal = [], 0
        self._planifier()

    def insert(self, _idx, texte, tag=None):
        lignes = texte.split("\n")
        for i, l in enumerate(lignes):
            if l == "" and i == len(lignes) - 1:
                continue
            self.unites.append((l, tag))
        self._planifier()

    def _planifier(self):
        if not self._sale:
            self._sale = True
            try:
                self.app.after_idle(self.rendre)
            except Exception:  # noqa: BLE001
                self._sale = False

    def _aller_barre(self, debut):
        self.decal = min(max(0, int(round(debut))), max(0, len(self.unites) - 1))
        self.rendre()

    def defiler(self, haut):
        nv = min(max(0, self.decal + haut), max(0, len(self.unites) - 1))
        if nv != self.decal:
            self.decal = nv
            self.rendre()

    def rendre(self):
        self._sale = False
        if self not in self.app.textes_dessines:
            return
        cv = self.app.cv
        try:
            cv.delete(self.tag)
            x1, y1, x2, y2 = self.zone
            y = y1 + 4
            montrees = 0
            larg = x2 - x1 - 2 * self.pad - (22 if self.barre else 0)
            for texte, tag in self.unites[self.decal:]:
                it = cv.create_text(x1 + self.pad, y, text=texte or " ", anchor="nw", width=larg,
                                    fill=self.couleurs.get(tag, ENCRE), font=(F_SAISIE, self.taille), tags=(self.tag,),
                                    interligne=INTERLIGNE_LOG)
                bb = cv.bbox(it)
                if not bb:
                    break
                bas = bb[3]          # texte replié = une ligne par élément : la hauteur de bbox est exacte
                if bas > y2 - 3 and y > y1 + 4:       # une ligne coupée par le bas du cadre : on ne la montre pas
                    cv.delete(it)
                    break
                montrees += 1
                y = bas + 2
            if self.barre and (self.onglet_barre is None or self.app.onglet == self.onglet_barre):
                n = len(self.unites)
                trop = self.decal > 0 or montrees < n
                self.app.barre_defil(self.barre, x2 - 15, y1 + 2, y2 - 2, n if trop else 1, 1, self.decal, self._aller_barre)
            for sur in ("menu_bd", "menu_cartes", "infobulle", "bulle_aide", "fx"):      # les bulles et effets restent devant
                if cv.find_withtag(sur):
                    cv.tag_lower(self.tag, sur)
                    break
        except Exception:  # noqa: BLE001
            journal_exc()

    def _hauteur(self, texte, largeur_px, k):
        """Hauteur logique d'un texte replié à `largeur_px` pixels (mêmes retours à la ligne que le canvas : aux espaces)."""
        try:
            import tkinter.font as tkfont
            cache = self.__dict__.setdefault("_polices", {})
            taille = max(1, int(round(self.taille * k)))
            f = cache.get(taille)
            if f is None:
                f = cache[taille] = tkfont.Font(family=F_SAISIE, size=taille)
            lignes, cour = 1, ""
            for mot in texte.split(" "):
                essai = (cour + " " + mot) if cour else mot
                if f.measure(essai) <= largeur_px:
                    cour = essai
                    continue
                if cour:
                    lignes += 1
                cour = mot
                while f.measure(cour) > largeur_px and len(cour) > 1:      # mot plus large que la zone : coupé
                    lignes += 1
                    cour = cour[max(1, int(len(cour) * largeur_px / max(1, f.measure(cour)))):]
            lh = max(f.metrics("linespace") / k, 1.2 * self.taille)        # jamais moins de 1,2 × la taille de police
            return lh * (1 + INTERLIGNE_LOG * (lignes - 1))
        except Exception:  # noqa: BLE001
            return 1.2 * self.taille

    def destroy(self):
        try:
            self.app.cv.delete(self.tag)
        except Exception:  # noqa: BLE001
            journal_exc()
        try:
            self.app.textes_dessines.remove(self)
        except ValueError:
            pass


class ChampPares:
    """Champ de saisie « paresseux » : dessiné (cadre + texte) tant qu'on n'y touche pas ; le vrai tk.Entry n'est créé
    qu'au clic et détruit quand on le quitte. Interface compatible avec l'ancien tuple (boite, entree)."""

    def __init__(self, app, cle, boite, x1, y1, x2, y2, variable, police=17, centre=False, couleur=None,
                 famille=None, fond=None, a_ouvrir=None, a_fermer=None, a_echap=None):
        self.app, self.cle, self.boite = app, cle, boite
        self.famille, self.fond = famille or F_SAISIE, fond or CREME_CLAIR
        self.a_ouvrir, self.a_fermer, self.a_echap, self.annule = a_ouvrir, a_fermer, a_echap, False
        self.zone = (x1, y1, x2, y2)
        self.var, self.police, self.centre = variable, police, centre
        self.couleur = couleur
        self.actif = True
        self.reserve = 0                 # place laissée à droite (ex. une croix pour effacer)
        self.gauche = 12                 # marge à gauche du texte (ex. plus grande pour laisser la place à une loupe)
        self.bord_actif = ROUGE          # couleur du cadre pendant la saisie
        self.curseur = ROUGE             # couleur du curseur de saisie
        self.entree = self.fen = None
        self.tag = "cp_" + cle
        self.texte = app.cv.create_text(0, 0, text="", anchor=("center" if centre else "w"),
                                        font=(self.famille, police), fill=ENCRE, tags=(self.tag,))
        self._trace = variable.trace_add("write", lambda *_: self.maj_texte())
        self.maj_texte()
        # zone cliquable : le cadre et le texte
        for it in (boite, self.texte):
            app.cv.addtag_withtag(self.tag + "_hit", it)
        app.cv.tag_bind(self.tag + "_hit", "<Button-1>", lambda e: self.ouvrir())
        app.cv.tag_bind(self.tag + "_hit", "<Enter>", lambda e: self.actif and app._curseur("xterm"))
        app.cv.tag_bind(self.tag + "_hit", "<Leave>", lambda e: app._curseur(""))

    # --- dessin
    def maj_texte(self):
        cv = self.app.cv
        x1, y1, x2, y2 = self.zone
        try:
            txt = self.var.get()
            dispo = (x2 - x1 - self.gauche - 6 - self.reserve) * cv.k
            cv.itemconfigure(self.texte, text=txt,
                             fill=(self.couleur or ENCRE) if self.actif else GRIS_TEXTE)
            def large():
                bb = cv.bbox(self.texte)
                return bb and (bb[2] - bb[0]) > dispo
            if large():
                while len(txt) > 1 and large():
                    txt = txt[:-1]
                    cv.itemconfigure(self.texte, text=txt + "…")
            if self.centre:
                cv.coords(self.texte, (x1 + x2) / 2, (y1 + y2) / 2 + 1)
            else:
                cv.coords(self.texte, x1 + self.gauche, (y1 + y2) / 2 + 1)
        except Exception:  # noqa: BLE001
            journal_exc()

    # --- interface de l'ancien Entry
    def configure(self, state=None, **_kw):
        if state is not None:
            self.actif = state != "disabled"
            if not self.actif:
                self.fermer()
            self.maj_texte()

    def get(self):
        return self.var.get()

    def focus_set(self):
        self.ouvrir()

    def destroy(self):
        self.fermer(rendre_focus=False)
        try:
            self.var.trace_remove("write", self._trace)
        except Exception:  # noqa: BLE001
            journal_exc()

    # --- vraie saisie, seulement pendant l'édition
    def ouvrir(self):
        app = self.app
        if not self.actif or self.entree is not None:
            return
        cv = app.cv
        x1, y1, x2, y2 = self.zone
        self.annule = False
        if self.a_ouvrir:
            self.a_ouvrir()
        try:
            e = tk.Entry(app.parent_widgets(), textvariable=self.var, bg=self.fond,
                         fg=self.couleur or ENCRE, relief="flat", bd=0, highlightthickness=0, insertbackground=self.curseur,
                         font=(self.famille, max(1, int(round(self.police * cv.k)))),
                         justify=("center" if self.centre else "left"),
                         selectbackground=LILAS_CLAIR, selectforeground=ENCRE)
            self.fen = cv.create_window(x1 + self.gauche, y1 + 5, window=e, anchor="nw",
                                        width=x2 - x1 - self.gauche - 12 - self.reserve, height=y2 - y1 - 10)
        except Exception as ex:  # noqa: BLE001
            print("saisie :", repr(ex), file=sys.stderr)
            return
        self.entree = e
        cv.itemconfigure(self.texte, state="hidden")
        cv.itemconfigure(self.boite, outline=self.bord_actif, width=3.6)
        e.bind("<FocusOut>", lambda ev: self.fermer(rendre_focus=False))
        e.bind("<Return>", lambda ev: self.fermer())
        e.bind("<KP_Enter>", lambda ev: self.fermer())
        e.bind("<Escape>", lambda ev: (setattr(self, "annule", True), self.fermer()))
        e.bind("<Tab>", lambda ev: self.voisin(1))
        e.bind("<ISO_Left_Tab>", lambda ev: self.voisin(-1))
        e.bind("<Shift-Tab>", lambda ev: self.voisin(-1))

        def donner_focus():
            if self.entree is e:
                try:
                    e.focus_force()
                    e.icursor("end")
                except Exception:  # noqa: BLE001
                    journal_exc()
        e.after_idle(donner_focus)
        e.after(60, donner_focus)          # le clic sur le fond du canvas reprend le focus juste après : on le reprend

    def fermer(self, rendre_focus=True):
        e, self.entree = self.entree, None
        if e is None:
            return
        cv = self.app.cv
        try:
            cv.delete(self.fen)
            e.destroy()
        except Exception:  # noqa: BLE001
            journal_exc()
        self.fen = None
        try:
            rappel = self.a_echap if self.annule else self.a_fermer
            if rappel:
                rappel()
            cv.itemconfigure(self.texte, state="normal")
            cv.itemconfigure(self.boite, outline=NOIR, width=2.6)
            self.maj_texte()
            if rendre_focus:
                cv.focus_set()
        except Exception:  # noqa: BLE001
            journal_exc()

    def voisin(self, sens):
        champs = [c for c in self.app.champs.values() if isinstance(c[1], ChampPares) and c[1].actif]
        objets = [c[1] for c in champs]
        if self not in objets:
            return "break"
        suivant = objets[(objets.index(self) + sens) % len(objets)]
        self.fermer(rendre_focus=False)
        if suivant is not self:
            suivant.ouvrir()
        return "break"


class App(tk.Tk):
    ECHELLE_MIN, ECHELLE_MAX = 0.6, 2.5
    pause_langue = 0.0
