    def dessiner_tout(self):
        cv = self.cv
        self._fen_masq = []
        self.boutons = {}
        self.champs = {}
        self.champs_fen = {}
        self.textes_dessines = []
        self.cartes = {}
        self.ronds = {}
        self.etoiles_scint = []
        self.effets = []
        self.zzz = []

        # fond lilas à lettres de graffiti (ciel étoilé la nuit)
