        # décor qui passe derrière les fenêtres
        self.decor()

        # la mascotte (en haut à droite) ; sa langue-câble sort de sa bouche
        self.tete_dessiner()
        if self.onglet != "config":              # onglets Appareils et Monitor : langues + fiches, sans le branchement
            self._cab_skip, self._prise_skip = frozenset(), frozenset({0, 1})
