    def petits_ronds(self, fixe=None):
        """Les quatre petits ronds : animations, son, langue, mode nuit (de gauche à droite)."""
        def dessin_langue(cx, cy, tags):
            self.cv.create_text(cx, cy + 1, text=LANGUE.upper(), font=(F_TITRE, 15), fill=ENCRE, tags=tags)

        def dessin_son(cx, cy, tags):
            self.pictogramme("son" if self.son_actif else "muet", cx - 1, cy, ENCRE, 0.72, tags)

        def dessin_anim(cx, cy, tags):
            self.pictogramme("anim" if self.anim_actives else "anim_off", cx, cy, ENCRE, 0.72, tags)

        def dessin_nuit(cx, cy, tags):
            self.pictogramme("soleil" if NUIT else "lune", cx, cy, ENCRE, 0.8, tags)

        def dessin_reglages(cx, cy, tags):
            self.proto_dessin_engrenage(cx, cy, tags)

        decalage = 0 if fixe is None else 736 - 930
        for k_, (cle, x, commande, dessin) in enumerate((("anim", 930, self.basculer_anim, dessin_anim),
                                         ("son", 962, self.basculer_son, dessin_son),
                                         ("langue", 994, self.basculer_langue, dessin_langue),
                                         ("nuit", 1026, self.basculer_nuit, dessin_nuit),
                                         ("reglages", 1058, self.ouvrir_reglages, dessin_reglages))):
            y_ = fixe if fixe is not None else round(self.centre_barre(355, 140, 1050, 600, 0.35, x) - 0.5, 1)
            if fixe is not None:
                x = 863 - 40 * (4 - k_)                   # écartés de 40 ; le dernier (réglages) finit au bord de la bulle
                decalage = 0
            self.rond(cle, x + decalage, y_, commande, dessin)

    SIGNATURE_STYLE = {"lignes": ("GOONY",), "souligne": True, "angle": -90}     # GOONY de bas en haut, souligné + astérisque rose
    SIGNATURE = (1089, 836, 27)       # position (x, y) et hauteur des lettres du tag GOONY ; None = pas de tag

    def signature_dessiner(self):
        if not self.SIGNATURE:
            return
        cv = self.cv
        for pts, ep, role in signature_traits(*self.SIGNATURE, **self.SIGNATURE_STYLE):
            plat = [c for p in pts for c in p]
            cv.create_line(plat, fill=ROSE if role == "rose" else ENCRE, width=ep, capstyle="round",
                           joinstyle="round", tags=("signature",))

    # ===== « À propos » et menus du haut de l'écran =====
    def ouvrir_reglages(self):
        try:
            if getattr(self, "_fen_reglages", None) is not None and self._fen_reglages.winfo_exists():
                self._fen_reglages.deiconify()
                self._fen_reglages.lift()
                return
        except Exception:  # noqa: BLE001
            journal_exc()
        try:
            self._fen_reglages = fenetre_reglages(self)
        except Exception as e:  # noqa: BLE001
            self._fen_reglages = None
            print("fenêtre des réglages :", repr(e), file=sys.stderr)

    def ouvrir_apropos(self):
        try:
            if getattr(self, "_fen_apropos", None) is not None and self._fen_apropos.winfo_exists():
                self._fen_apropos.deiconify()
                self._fen_apropos.lift()
                return
        except Exception:
            journal_exc()
        try:
            self._fen_apropos = fenetre_apropos(self)
        except Exception as e:  # noqa: BLE001
            self._fen_apropos = None
            print("fenêtre à propos :", repr(e), file=sys.stderr)

    def faire_un_don(self):
        lien = lien_don()
        if lien:
            ouvrir_lien(lien)
        else:
            self.ouvrir_apropos()

    def creer_menus(self):
        """Barre de menus du Mac (en haut de l'écran) : « À propos » dans le menu IP Pilot, et un menu « Infos »."""
        try:
            barre = tk.Menu(self)
            pomme = tk.Menu(barre, name="apple")
            pomme.add_command(label=t("menu_apropos"), command=self.ouvrir_apropos)
            pomme.add_command(label=t("menu_bug"), command=self.ouvrir_bug)
            barre.add_cascade(menu=pomme)
            reseau = tk.Menu(barre, name="reseau", tearoff=0)
            reseau.add_command(label=t("menu_scanner"), command=self.ouvrir_scan)
            reseau.add_checkbutton(label=t("menu_surv"), variable=self._var_surv, command=self.menu_surv)
            reseau.add_command(label=t("menu_histo"), command=self.ouvrir_historique)
            reseau.add_command(label=t("menu_detective"), command=self.ouvrir_detective)
            reseau.add_command(label=t("menu_synoptique"), command=self.ouvrir_synoptique)
            reseau.add_separator()
            reseau.add_command(label=t("menu_export"), command=self.exporter_scan)
            reseau.add_command(label=t("menu_export_app"), command=self.app_exporter)
            reseau.add_command(label=t("menu_export_proto"),
                               command=lambda: self.proto_exporter(self.SOUS_PROTO[self.mon_data.get("proto_i", 0)]))
            reseau.add_separator()
            reseau.add_command(label=t("menu_export_pdf"), command=lambda: self.exporter_scan("pdf"))
            reseau.add_command(label=t("menu_export_app_pdf"), command=lambda: self.app_exporter("pdf"))
            reseau.add_command(label=t("menu_export_proto_pdf"),
                               command=lambda: self.proto_exporter(self.SOUS_PROTO[self.mon_data.get("proto_i", 0)], "pdf"))
            barre.add_cascade(label=t("menu_reseau"), menu=reseau)
            infos = tk.Menu(barre, name="infos", tearoff=0)
            infos.add_command(label=t("menu_apropos"), command=self.ouvrir_apropos)
            infos.add_command(label=t("menu_reglages"), command=self.ouvrir_reglages)
            infos.add_command(label=t("menu_bug"), command=self.ouvrir_bug)
            infos.add_command(label=t("menu_don"), command=self.faire_un_don)
            barre.add_cascade(label=t("menu_infos"), menu=infos)
            self.config(menu=barre)
            self._barre_menus = barre
            self.createcommand("tkAboutDialog", self.ouvrir_apropos)
            self.createcommand("::tk::mac::ShowPreferences", self.ouvrir_reglages)
        except Exception as e:  # noqa: BLE001
            print("menus :", repr(e), file=sys.stderr)

    # ===== onglets : Configuration | Appareils | Monitoring =====
    ONGLETS = (("config", "onglet_config"), ("appareils", "onglet_appareils"), ("monitoring", "onglet_mon"),
               ("protocoles", "onglet_proto"))
    OK_FOND = "#238A52"             # bandeau « tout va bien » (même couleur de jour comme de nuit)

    def onglets_dessiner(self):
        cv = self.cv
        for i, (cle, libelle) in enumerate(self.ONGLETS):
            x1, y1 = 40 + i * 156, 106
            x2, y2 = x1 + 146, 138
            actif = self.onglet == cle
            tag = f"onglet_{cle}"
            cv.create_polygon(contour(x1 + 4, y1 + 5, x2 + 4, y2 + 5, 10, i + 90, 1.0, 40), smooth=True,
                              fill=NOIR, outline=NOIR, width=3, tags=(tag,))
            corps = cv.create_polygon(contour(x1, y1, x2, y2, 10, i + 80, 1.4, 40), smooth=True,
                                      fill=CREME if actif else LILAS_CLAIR, outline=NOIR, width=3, tags=(tag,))
            tx = cv.create_text((x1 + x2) / 2, (y1 + y2) / 2 + 1, text=t(libelle), font=(F_TEXTE, 19),
                                fill=ENCRE, tags=(tag,))
            self.ajuster(tx, F_TEXTE, 19, x2 - x1 - 20)
            cv.tag_bind(tag, "<ButtonPress-1>", lambda e, c=cle, cp=corps: self._appui_onglet(c, cp))

            def survol(v, c=corps, a=actif, k=cle):
                self._curseur("pointinghand" if v else "")
                if not a:
                    cv.itemconfigure(c, fill=LILAS_PALE if v else LILAS_CLAIR)
            cv.tag_bind(tag, "<Enter>", lambda e, k=cle, f=survol: self._survol_lisse("o_" + k, True, f))
            cv.tag_bind(tag, "<Leave>", lambda e, k=cle, f=survol: self._survol_lisse("o_" + k, False, f))
            if cle == "protocoles":
                self._pastille_beta(x2 - 8, y1 - 6)

    def _pastille_beta(self, cx, cy):
        """Petite pastille penchée « bêta » sur le coin de l'onglet Protocoles ; un clic dessus ouvre la bulle d'explication."""
        import math
        cv = self.cv
        ang = math.radians(9)
        w, h = 25, 11
        pts = []
        for px, py in ((-w, -h), (w, -h), (w, h), (-w, h)):
            pts += [cx + px * math.cos(ang) - py * math.sin(ang), cy + px * math.sin(ang) + py * math.cos(ang)]
        tag = ("pastille_beta",)
        cv.create_polygon([p + 2 for p in pts], fill=NOIR, outline=NOIR, width=3, joinstyle="round", tags=tag)
        cv.create_polygon(pts, fill=ROUGE_VIF, outline=NOIR, width=2, joinstyle="round", tags=tag)
        tx = cv.create_text(cx, cy, text=t("proto_beta"), font=(F_TEXTE, 13), fill=CLAIR, angle=-9, tags=tag)
        self.ajuster(tx, F_TEXTE, 13, 2 * w - 8)

    def _appui_onglet(self, cle, corps):
        """L'onglet réagit dès l'appui (pas au relâchement) : couleur d'abord, puis le contenu."""
        if cle == self.onglet or self.occupe:
            return
        try:
            self.cv.itemconfigure(corps, fill=CREME)
        except Exception:
            journal_exc()
        self.choisir_onglet(cle)

    def choisir_onglet(self, cle):
        if cle == self.onglet or self.occupe:
            return
        self.jouer("pop")
        if self.onglet == "protocoles":
            for n_ in PROTOS + ("midi", "dante"):      # on quitte l'onglet : l'écoute s'arrête
                self.proto_arreter(n_)
        self.onglet = cle
        self.reconstruire_ui(self.cle_bulle)

    def aller_monitoring(self, scan=False):
        if self.onglet != "monitoring":
            self.choisir_onglet("monitoring")
        if scan and self.onglet == "monitoring":
            self.scan_maintenant()

    def _fenetres_annexes_fermer(self):
        for f in list(getattr(self, "_popups", [])):
            try:
                f.destroy()
            except Exception:
                journal_exc()
        self._popups = []

    # ----- données du monitoring (alimentées par la surveillance et par les scans) -----
    def mon_integrer(self, r, etat=None):
        """Range un résultat de scan dans les tables du monitoring et de l'inventaire."""
        d = self.mon_data
        maintenant = time.time()
        if maintenant - self.__dict__.get("_purge_t", 0) > 3600:           # oubli des appareils sans importance, une fois par heure
            self._purge_t = maintenant
            if purger_inventaire(self.inv, self.__dict__.get("_debut_session", maintenant), epingles=self.epingles()):
                sauver_inventaire(self.inv)
        if d.get("reseau") not in ("", r["reseau"]):
            d["app"].clear()
        d["reseau"], d["ip"] = r["reseau"], r["ip"]
        if r.get("device"):
            d["device"] = r["device"]
        d["carte"] = r.get("service") or r.get("device") or d.get("carte", "")
        noms = noms_memorises()
        presents = set()
        nouveaux = False
        macs_connues = {}                      # ip -> mac déjà vue : si l'ARP a raté un tour, on garde la même identité
        for k_, a_ in sorted(self.inv.items(), key=lambda kv: kv[1].get("vu", 0)):
            if a_.get("mac") and a_.get("ip"):
                macs_connues[a_["ip"]] = (a_["mac"], a_.get("fab", ""))
        for x in r["trouves"]:
            if not x.get("mac") and x["ip"] in macs_connues:
                x["mac"], x["fabricant"] = macs_connues[x["ip"]]
            k = cle_appareil(x)
            if x.get("mac") and x["ip"] != k and x["ip"] in d["app"] and not d["app"][x["ip"]].get("mac"):
                d["app"].pop(x["ip"], None)      # l'ancienne fiche sans MAC (même IP) est fusionnée
            a0 = d["app"].get(k)
            if a0 is not None and a0.get("perdu") and a0.get("repond") and x["ms"] is None:
                # appareil qui répondait au ping et ne répond plus : sa ligne ARP reste un moment dans la table du Mac
                # après son départ ; elle ne suffit pas à le dire revenu (il resterait vert, par à-coups, alors qu'il est perdu)
                continue
            presents.add(k)
            a = d["app"].setdefault(k, {"hist": deque(maxlen=90), "coups": deque(maxlen=300), "depuis": maintenant})
            a.update(ip=x["ip"], mac=x.get("mac", ""), fab=x.get("fabricant", ""), ms=x["ms"],
                     nom=nom_appareil(x, noms), perdu=False, vu=maintenant, passif=x["ms"] is None)
            a.pop("perdu_t", None)
            if x["ms"] is not None:
                a["repond"] = True
            a["hist"].append(x["ms"])
            a["npts"] = a.get("npts", 0) + 1
            if noter_vu(self.inv, x, maintenant, r.get("reseau", ""), r.get("service") or r.get("device") or ""):
                nouveaux = True
            self.inv[k]["nom"] = a["nom"]
        if etat is not None:
            for k, x in etat.get("appareils", {}).items():
                a = d["app"].get(k)
                if a is not None and k not in presents:
                    a["hist"].append(None)
                    a["npts"] = a.get("npts", 0) + 1
                    if x.get("perdu") and not a.get("perdu"):
                        a["perdu"], a["ms"], a["perdu_t"] = True, None, maintenant
        if etat is not None:
            # coupures vues par la surveillance : début = dernière fois vu, fin = retour de la réponse
            prec = d.get("cycle_t", maintenant)
            for k, a in d["app"].items():
                if k in presents:
                    if a.get("coup_t0") is not None:
                        a["coups"].append((a["coup_t0"], max(1.0, maintenant - a["coup_t0"])))
                        a["coup_t0"] = None
                elif a.get("coup_t0") is None and k in etat.get("appareils", {}):
                    a["coup_t0"] = max(a.get("vu", prec), prec)
            d["cycle_t"] = maintenant
        if nouveaux or maintenant - d.get("inv_sauve", 0) > 60:
            d["inv_sauve"] = maintenant
            sauver_inventaire(self.inv)

    def mon_maj(self, force=False):
        if not self.ui_prete or self.onglet in ("config", "protocoles"):
            return
        if self.__dict__.get("_menu_cartes") and not force:
            return
        if self.onglet == "appareils":
            if not getattr(self, "_edit", None) and not (self._menu and not force):
                d_ = self.mon_data
                maintenant_ = time.time()
                sig_a = (len(self.inv), len(self.suivi), d_.get("app_carte"), d_.get("app_tri"),
                         tuple(sorted((k, bool(v.get("perdu")), maintenant_ - v.get("vu", 0) < 90)
                                      for k, v in d_["app"].items())))
                if force or sig_a != d_.get("app_sig"):
                    d_["app_sig"] = sig_a
                    self.app_dessiner_dyn()
            return
        d = self.mon_data
        if self._menu and not force:               # le menu clic droit est ouvert : on ne redessine pas dessous
            return
        sig = (tuple(sorted((k, a["ip"], round(a["ms"]) if a["ms"] is not None else None, a.get("perdu"), a.get("nom"))
                            for k, a in d["app"].items())),
               d.get("sel"), d.get("scroll"), d.get("ordre"), self.surv_actif(), self.v_recherche.get(),
               int(time.time()) if any(a.get("perdu") for a in d["app"].values()) else 0,
               d.get("conflit_t", 0) > time.time() - 600,
               int(time.time() // 30),
               tuple((k, len(a.get("coups", ())), a.get("coup_t0") is not None) for k, a in d["app"].items()))
        gsig = self.gr_signature()
        if force or sig != d.get("sig"):
            d["sig"] = sig
            self.mon_dessiner_dyn()
        if force or gsig != d.get("gsig"):               # les courbes se redessinent aussi quand le reste change
            d["gsig"] = gsig
            self.mon_dessiner_graphe()
        self.mon_hist_maj(force)

    # ----- onglet Monitoring -----
    def dessiner_monitoring(self):
        cv = self.cv
        self.petits_ronds(fixe=123)
        # grand panneau de gauche : appareils + santé (une ligne par appareil : état, nom, latence, jauge de 30 minutes)
        self.fenetre_dessinee(30, 262, 695, 845, 311, t("mon_appareils"), incl=-0.2, deco=False)
        self.rond("ordre", 620, round(self.centre_barre(30, 262, 695, 845, -0.2, 620) - 0.5, 1), self.mon_changer_ordre,
                  self.mon_dessin_ordre)
        self.rond("coup_aide", 662, round(self.centre_barre(30, 262, 695, 845, -0.2, 662) - 0.5, 1),
                  self.ouvrir_aide_coupures,
                  lambda cx, cy, tg: self.cv.create_text(cx, cy + 1, text="?", font=(F_TITRE, 17), fill=ENCRE, tags=tg))
        self.champ("mon_rech", 46, 308, 380, 340, self.v_recherche)          # barre de recherche (IP, nom, MAC, fabricant)
        self.champs["mon_rech"][1].reserve = 26                              # place de la croix « effacer »
        self.champs["mon_rech"][1].bord_actif = NOIR                         # le cadre reste noir pendant la saisie
        self.champs["mon_rech"][1].curseur = NOIR                            # et le curseur aussi
        self.champs["mon_rech"][1].gauche = 42                               # le texte commence après la loupe
        # petite loupe dessinée ; elle porte la même étiquette « zone cliquable » que le champ
        _hit = (self.champs["mon_rech"][1].tag + "_hit",)
        cv_ = self.cv
        cv_.create_oval(60, 315, 73.6, 328.6, outline=ENCRE, width=2.6, tags=_hit)
        cv_.create_line(71.9, 326.9, 78.7, 333.7, fill=ENCRE, width=3.0, capstyle="round", tags=_hit)
        # carte réseau surveillée (même bouton que dans l'onglet Appareils)
        nom_c = self.mon_data.get("carte") or self.surv_carte_reglee()
        self._mon_carte_txt = nom_c
        self.bouton("mon_carte", 48, 788, 236, 830, self.tronque_px(nom_c or t("mon_carte_aucune"), F_TEXTE, 19, 100),
                    self.mon_carte_menu, "creme", 15,
                    icone="wifi" if re.search(r"wi-?fi|airport", nom_c or "", re.I) else "prise")
        cv.create_polygon(206, 804, 220, 804, 213, 814, fill=ENCRE, outline=ENCRE, width=1, joinstyle="round",
                          tags=("btn_mon_carte",))
        self.bouton("mon_scan", 250, 788, 298, 830, "", self.scan_maintenant, "creme", 17, icone="actualiser")
        # colonne de droite : historique (en haut), courbes (en bas)
        self.fenetre_dessinee(710, 262, 1050, 546, 323, t("mon_histo"), incl=-0.25, deco=False)
        yh = self.centre_barre(710, 262, 1050, 546, -0.25, 985)
        # trois petits boutons ronds à plat (comme « ? », langue, sons, nuit) : danger · poubelle · agrandir
        def icone_ronde(nom, cle):
            return lambda cx, cy, tg: self.pictogramme(
                nom, cx, cy, (ROUGE if cle == "mon_f_pb" else CLAIR) if self.ronds.get(cle, {}).get("actif") else ENCRE, 0.9, tg)
        self.rond("mon_f_pb", 941, round(self.centre_barre(710, 262, 1050, 546, -0.25, 941), 1), self.mon_filtre_basculer,
                  icone_ronde("danger", "mon_f_pb"))
        self.rond("mon_vider", 985, round(yh, 1), self.mon_vider_histo, icone_ronde("corbeille", "mon_vider"))
        self.rond("mon_agrandir", 1029, round(self.centre_barre(710, 262, 1050, 546, -0.25, 1029), 1), self.ouvrir_historique,
                  icone_ronde("agrandir", "mon_agrandir"))
        self.rond_actif("mon_f_pb", self.mon_data["filtre"] == "pb")
        cadre_h = self.cadre_dessine(728, 308, 1032, 534, 331)
        cv.tag_bind(cadre_h, "<Double-Button-1>", lambda e: self.after(1, self.ouvrir_historique))
        self.mon_texte = TexteDessine(self, 728, 308, 1032, 534, taille=14, pad=7)
        self._histo_masque = []
        for genre, couleur in (("connexion", VERT_OK), ("deconnexion", ATTENTION), ("erreur", ERREUR),
                               ("avert", ATTENTION), ("conflit", ERREUR), ("info", VIOLET)):
            self.mon_texte.tag_configure(genre, foreground=couleur)
        cv.tag_bind(self.mon_texte.tag, "<Double-Button-1>", lambda e: self.after(1, self.ouvrir_historique))
        self.fenetre_dessinee(710, 561, 1050, 845, 331, "", incl=0.25, deco=False)
        for cle_r, cx_, sens in (("gr_prec", 986, -1), ("gr_suiv", 1024, 1)):
            self.rond(cle_r, cx_, round(self.centre_barre(710, 561, 1050, 845, 0.25, cx_) - 0.5, 1),
                      lambda s_=sens: self.gr_aller(s_), self.gr_dessin_fleche(sens))
        self.mon_data["sig"] = None
        self.mon_data["hist_sig"] = None
        self.mon_data["_schema"] = None
        self.mon_dessiner_dyn()

    @staticmethod
    def mon_dessin_ordre_texte(ordre):
        return {"ip": "IP", "ms": "ms"}.get(ordre, "état")

    def mon_dessin_ordre(self, cx, cy, tags):
        self.cv.create_text(cx, cy + 1, text=self.mon_dessin_ordre_texte(self.mon_data["ordre"]),
                            font=(F_TITRE, 11), fill=ENCRE, tags=tags)

    def surv_carte_reglee(self):
        try:
            return str(lire_reglages().get("surv_carte") or "")
        except Exception:  # noqa: BLE001
            return ""

    def mon_carte_menu(self):
        """Quelle carte réseau le Monitor surveille (ou « automatique » = celle du profil)."""
        self.cartes_menu(self.app_cartes_toutes(), self.surv_carte_reglee(), self.mon_carte_choisir,
                         special=("", t("mon_carte_auto")), grises=True)

    def mon_carte_choisir(self, c):
        """Le Monitor suit désormais la carte `c` ('' = automatique) : on relance la surveillance sur ce réseau."""
        sauver_reglage(surv_carte=c)
        self.jouer("pop")
        d = self.mon_data
        d["app"].clear()
        d["reseau"] = ""
        d["carte"] = c
        if c:                                   # l'onglet Appareils suit la même carte (et inversement)
            d["app_carte"] = c
        else:
            d.pop("app_carte", None)
        d["app_set"] = set()
        d["app_scroll"] = 0
        if self.surv_actif():
            self.surv_arreter()
            self.surv_demarrer(c or None, silencieux=True)
        self.mon_maj(True)

    def mon_changer_ordre(self):
        d = self.mon_data
        d["ordre"] = {"ip": "ms", "ms": "etat"}.get(d["ordre"], "ip")
        d["_ordre_ms"] = None
        self.jouer("pop")
        self.rond_redessiner("ordre")
        self.mon_maj(True)

    def mon_filtre(self, f):
        self.mon_data["filtre"] = f
        self.rond_actif("mon_f_pb", f == "pb")
        self.mon_hist_maj(True)

    def mon_filtre_basculer(self):
        self.jouer("pop")
        self.mon_filtre("tout" if self.mon_data.get("filtre") == "pb" else "pb")

    def mon_vider_histo(self):
        if not messagebox.askyesno("IP Pilot", t("hist_vider_q"), parent=self):
            return
        vider_evenements()
        self.mon_data["conflit_t"] = 0
        self.mon_maj(True)


    def mon_selectionner(self, cle):
        self.mon_data["sel"] = cle
        self.mon_data["gr_apps"] = None            # les courbes suivent l'appareil choisi dans la liste
        self.jouer("clic")
        self.mon_maj(True)

    def mon_lignes(self):
        d = self.mon_data
        liste = [dict(a, cle=k) for k, a in d["app"].items()]
        if d["ordre"] == "etat":              # problèmes d'abord : déconnectés, puis ceux qui ont eu une coupure, puis les stables
            maintenant_ = time.time()
            liste.sort(key=lambda a: cle_ordre_coupure(a, coups_recents(a.get("coups", ()), a.get("coup_t0"), maintenant_)))
            return self.epingles_en_tete(liste)
        if d["ordre"] != "ms":
            return self.epingles_en_tete(ordre_chaine(liste, d["ordre"]))
        # tri par temps de réponse : l'ordre est figé 20 s, sinon les lignes sautent à chaque mesure
        memo, maintenant = d.get("_ordre_ms"), time.time()
        cles = {a["cle"] for a in liste}
        if not memo or set(memo[1]) != cles or maintenant - memo[0] > 20:
            memo = (maintenant, [a["cle"] for a in ordre_chaine(liste, "ms")])
            d["_ordre_ms"] = memo
        rang = {k: i for i, k in enumerate(memo[1])}
        return self.epingles_en_tete(sorted(liste, key=lambda a: rang[a["cle"]]))

    def _recherche_changee(self):
        """Saisie dans la barre de recherche : la liste est refiltrée (un court délai évite de redessiner à chaque lettre)."""
        if self._rech_job:
            try:
                self.after_cancel(self._rech_job)
            except Exception:  # noqa: BLE001
                journal_exc()
        def aller():
            self._rech_job = None
            if self.onglet == "monitoring":
                self.mon_data["scroll"] = 0
                self.mon_maj(True)
        self._rech_job = self.after(120, aller)

    def mon_filtrer(self, liste):
        q = self.v_recherche.get().strip().lower()
        if not q:
            return liste
        sortie = []
        for a in liste:
            mac = a.get("mac") or ""
            champs = (a.get("nom"), a.get("ip"), mac, a.get("fab"), a.get("note"), fabricant(mac) if mac else "")
            if any(q in str(c).lower() for c in champs if c):
                sortie.append(a)
        return sortie

    def mon_aller(self, debut):
        self.mon_data["scroll"] = debut
        self.mon_maj(True)

    def mon_dessiner_dyn(self):
        if self.__dict__.get("_menu_cartes"):
            return
        cv = self.cv
        d = self.mon_data
        cv.delete("mon_dyn")
        nom_c = d.get("carte") or self.surv_carte_reglee()
        if nom_c != self.__dict__.get("_mon_carte_txt") and "mon_carte" in self.boutons:
            self._mon_carte_txt = nom_c
            self.bouton_definir("mon_carte", texte=self.tronque_px(nom_c or t("mon_carte_aucune"), F_TEXTE, 19, 100))
        liste_tout = self.mon_lignes()
        liste = self.mon_filtrer(liste_tout)
        if d.get("sel") not in d["app"]:
            d["sel"] = liste_tout[0]["cle"] if liste_tout else None
        perdus = [a for a in liste_tout if a.get("perdu")]
        conflit = d.get("conflit_t", 0) > time.time() - 600
        total = len(liste_tout)
        nb = len(liste)
        # --- bandeau
        arp_ligne = arp_vus = 0
        if not total:
            fond, gros = "#6B5FA8", "—"
        else:
            # rouge seulement si on perd un appareil « vert » (ping + ARP) : les appareils « bleus » (ARP seul) partent et
            # reviennent sans cesse, ils ne doivent pas garder le bandeau rouge en permanence
            perdus_verts = [a for a in perdus if not a.get("passif")]
            fond = ROUGE if (perdus_verts or conflit) else self.OK_FOND
            # le gros chiffre ne compte que le matériel « vert » (celui qui répond au ping) ; les appareils « bleus »
            # (ARP seul : téléphones, objets connectés) sont résumés en petit dessous
            verts = [a for a in liste_tout if not a.get("passif")]
            arp_vus = total - len(verts)
            arp_ligne = sum(1 for a in liste_tout if a.get("passif") and not a.get("perdu"))
            gros = t("mon_total", ok=sum(1 for a in verts if not a.get("perdu")), n=len(verts)) if verts else "—"
        # le bandeau n'est redessiné que si son contenu change (couleur, chiffre, résumé ARP, thème, langue)
        sig_ban = (fond, gros, arp_ligne, arp_vus, NUIT, LANGUE)
        if sig_ban != d.get("_ban") or not cv.find_withtag("bandeau"):
            d["_ban"] = sig_ban
            cv.delete("bandeau")
            cv.create_polygon(contour(30 + 6, 150 + 7, 1050 + 6, 244 + 7, 20, 303, 1.2, 80), smooth=True, fill=NOIR,
                              outline=NOIR, width=3, joinstyle="round", tags=("mon_ban", "bandeau"))
            cv.create_polygon(contour(30, 150, 1050, 244, 20, 301, 2.0, 80), smooth=True, fill=fond, outline=NOIR,
                              width=3, joinstyle="round", tags=("mon_ban", "bandeau"))
            if arp_vus:
                g = cv.create_text(530, 197, text=gros, font=(F_TITRE, 60), fill=CLAIR, tags=("mon_ban", "bandeau"))
                self.ajuster(g, F_TITRE, 60, 450)
                petit = t("mon_arp_1" if arp_ligne == 1 else "mon_arp_n", m=arp_ligne, n=arp_vus)
                # le résumé des appareils « ARP seul » : à droite du bandeau, pastille bleue + texte, l'ensemble centré dans la zone
                # libre à droite du gros chiffre (sur une ligne si ça tient, sinon sur deux)
                mes = cv.create_text(-3000, -3000, text=petit, font=(F_TEXTE, 16), anchor="nw")
                mb = cv.bbox(mes)
                cv.delete(mes)
                lt = (mb[2] - mb[0]) if mb else 240
                deux = lt + 26 > 270
                if deux:
                    petit = petit.replace(" par ARP", "\npar ARP").replace(" via ARP", "\nvia ARP")
                    lt = lt * 0.62
                x0 = 902 - (26 + lt) / 2                          # centre de la zone libre : entre la fin du chiffre et le bord
                cv.create_oval(x0, (187 if deux else 197) - 7, x0 + 14, (187 if deux else 197) + 7, fill=PASSIF, outline=NOIR,
                               width=2, tags=("mon_ban", "bandeau"))
                cv.create_text(x0 + 26, 197, text=petit, font=(F_TEXTE, 16), fill=CLAIR, anchor="w", width=260, justify="left",
                               tags=("mon_ban", "bandeau"))
            else:
                g = cv.create_text(540, 197, text=gros, font=(F_TITRE, 64), fill=CLAIR, tags=("mon_ban", "bandeau"))
                self.ajuster(g, F_TITRE, 64, 700)
            cv.tag_bind("bandeau", "<ButtonRelease-1>", lambda e: self.after(1, self.ouvrir_problemes))
            cv.tag_bind("bandeau", "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind("bandeau", "<Leave>", lambda e: self._curseur(""))
        # --- le grand panneau : une ligne par appareil (case, état, nom, latence, jauge de 30 minutes)
        N = 10
        Y0, PAS, HR = 352, 40, 33
        X1, X2 = 46, 668                       # bords des lignes
        cache_m = self.__dict__.setdefault("_mes_cache", {})
        if len(cache_m) > 3000:
            cache_m.clear()

        def mesure(txt, police, taille):                 # largeur d'un texte (mémorisée : mesurer sur le canevas coûte cher)
            k_ = (txt, police, taille)
            if k_ not in cache_m:
                m_ = cv.create_text(-3000, -3000, text=txt, font=(police, taille), anchor="nw")
                b_ = cv.bbox(m_)
                cv.delete(m_)
                cache_m[k_] = (b_[2] - b_[0]) if b_ else 0
            return cache_m[k_]
        # colonne du nom : assez large pour lire en entier le plus long nom de la liste (150 px au plus), puis la latence
        # et la jauge viennent se coller juste derrière
        NX = 108
        wn = max([mesure(self.nom_court(a_), F_TEXTE, 14) for a_ in liste] + [mesure("255.255.255.255", F_TEXTE, 14)
                 if not liste else 0])
        wn = min(150, wn) + 3
        # colonne latence : juste la largeur d'une valeur courante (« 88.8 ms »), plus large seulement si une latence dépasse 100 ms
        lent = any(a_.get("ms") is not None and not a_.get("perdu") and a_["ms"] >= 100 for a_ in liste)
        MSR = NX + wn + 4 + mesure("888.8 ms" if lent else "88.8 ms", F_SAISIE, 14)         # bord droit de la colonne latence
        GX1, GX2, ECART = round(MSR + 10), 656, 7           # la jauge : 60 tranches de 30 s, un petit blanc tous les 10 minutes
        cw = (GX2 - GX1 - 2 * ECART) / 60.0

        def xc(i):
            return GX1 + i * cw + (i // 20) * ECART
        d["scroll"] = max(0, min(d.get("scroll", 0), max(0, nb - N)))
        perdu_fond = "#FFD9D2" if not NUIT else "#6A2F4F"
        vide_perdu = "#F0BFB6" if not NUIT else "#82405F"
        maintenant = time.time()
        if self.v_recherche.get():
            cv.create_text(363, 325, text="✕", font=(F_TEXTE, 15), fill=GRIS_TEXTE, tags=("mon_dyn", "rech_x"))
            cv.tag_bind("rech_x", "<ButtonRelease-1>", lambda e: self.after(1, lambda: self.v_recherche.set("")))
            cv.tag_bind("rech_x", "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind("rech_x", "<Leave>", lambda e: self._curseur(""))
        if not liste:
            cv.create_text(360, 520, text=t("mon_vide") if not liste_tout else t("mon_aucun"), font=(F_TEXTE, 17), fill=GRIS_TEXTE,
                           width=420, justify="center", tags=("mon_dyn",))
        # Seules les lignes dont le contenu a changé sont redessinées (une ligne = ~70 éléments de dessin) : si la liste, la
        # largeur des colonnes ou le thème changent, on repart de zéro ; sinon on compare chaque ligne à ce qui est affiché.
        page = liste[d["scroll"]:d["scroll"] + N]
        sigs = d.setdefault("_lignes", {})
        schema = (GX1, wn, MSR, tuple(a_["cle"] for a_ in page), NUIT, LANGUE, perdu_fond)
        if schema != d.get("_schema") or (sigs and not cv.find_withtag("mon_ligne")):
            cv.delete("mon_ligne")
            sigs.clear()
            d["_schema"] = schema
        suivis_ = self.suivi
        epingles_ = self.epingles()
        for i in range(len(page), N):
            if i in sigs:
                cv.delete(f"mon_r{i}")
                cv.delete(f"mon_c{i}")
                del sigs[i]
        for i, a in enumerate(page):
            y = Y0 + i * PAS
            sel = a["cle"] == d["sel"]
            tag = f"mon_r{i}"
            ct = f"mon_c{i}"
            perdu = bool(a.get("perdu"))
            evs = coups_recents(a.get("coups", ()), a.get("coup_t0"), maintenant)
            # (None = pas encore surveillé, 0 = vert, 1 = orange, 2 = rouge) : seule la couleur compte pour savoir s'il faut redessiner
            cellules = tuple(None if s_ is None else (0 if s_ <= 0 else (2 if s_ >= 5 else 1))
                             for s_ in cellules_coupures(evs, maintenant, a.get("depuis")))
            nom = self.nom_court(a)
            ms = "" if perdu else (f"{a['ms']:.1f} ms" if a["ms"] is not None else "—")
            couleur_ms = ERREUR if perdu else (GRIS_TEXTE if a["ms"] is None else (VERT_OK if a["ms"] <= 50 else ATTENTION))
            sig = (a["cle"], sel, perdu, bool(a.get("passif")), bool(evs), nom, ms, couleur_ms, cellules,
                   a["cle"] in suivis_, a["cle"] in epingles_)
            if sigs.get(i) == sig:
                continue
            sigs[i] = sig
            cv.delete(tag)
            cv.delete(ct)
            cv.create_polygon(contour(X1 + 3, y + 3, X2 + 3, y + HR + 3, 8, i + 30, 0.7, 40), smooth=True,
                              fill=NOIR, outline=NOIR, width=2, tags=("mon_ligne", tag))
            cv.create_polygon(contour(X1, y, X2, y + HR, 8, i + 10, 0.9, 40), smooth=True,
                              fill=perdu_fond if perdu else (LILAS_PALE if sel else CREME_CLAIR),
                              outline=ROSE if sel else NOIR, width=4 if sel else 2.4, tags=("mon_ligne", tag))
            passif = bool(a.get("passif")) and not perdu
            etat_ = "perdu" if perdu else ("arp" if passif else ("coupure" if evs else "ok"))
            yc = y + HR / 2
            self.pastille_etat(82, yc - 8, 98, yc + 8, etat_, ("mon_ligne", tag))
            tn, coupe = self.texte_fixe(NX, yc + 0.5, nom, F_TEXTE, 14, wn, anchor="w",
                                        fill=ERREUR if perdu else ENCRE, tags=("mon_ligne", tag))
            if coupe:
                self.nom_complet_bulle(tn, nom)
            cv.create_text(MSR, yc + 1.5, text=ms, anchor="e", font=(F_SAISIE, 14), fill=couleur_ms,
                           tags=("mon_ligne", tag))
            # la jauge : 60 tranches de 30 s, de fines barres arrondies (vert = rien, orange < 5 s, rouge ≥ 5 s de coupure)
            gh = 17
            gy = y + HR / 2 - gh / 2
            lb = max(2.0, cw - 2.4)
            for j, s_ in enumerate(cellules):
                if s_ is None:
                    fond = vide_perdu if perdu else CREME_GRIS
                elif s_ == 0:
                    fond = VERT_OK
                else:
                    fond = ERREUR if s_ == 2 else ATTENTION
                xm = xc(j) + cw / 2
                cv.create_line(xm, gy + lb / 2, xm, gy + gh - lb / 2, fill=fond, width=lb, capstyle="round",
                               tags=("mon_ligne", tag))
            cv.tag_bind(tag, "<Button-1>", lambda e, k=a["cle"]: self.mon_selectionner(k))
            self.lier_clic_droit(tag, a["cle"])
            if a["cle"] in suivis_:
                self.suivi_pastille(98, yc - 7, ("mon_ligne", tag))
            cv.tag_bind(tag, "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind(tag, "<Leave>", lambda e: self._curseur(""))
            # petite case à cocher : surveillance continue de cet appareil (clic = ne sélectionne pas la ligne)
            actif_ = a["cle"] in suivis_
            cv.create_polygon(contour(55, yc - 8, 71, yc + 8, 4, i + 50, 0.3, 30), smooth=True,
                              fill=ROSE if actif_ else CREME, outline=NOIR, width=2.2, tags=("mon_ligne", ct))
            if actif_:
                cv.create_line(58, yc + 0.5, 62, yc + 4.5, 68, yc - 4.5, fill=NOIR, width=2.6, capstyle="round",
                               joinstyle="round", tags=("mon_ligne", ct))
            cv.tag_bind(ct, "<Button-1>", lambda e, k=a["cle"]: self.after(1, lambda: self.suivi_basculer(k)))
            cv.tag_bind(ct, "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind(ct, "<Leave>", lambda e: self._curseur(""))
            if a["cle"] in epingles_:
                self.vignette_epingle(X2 - 1, y + 1, ("mon_ligne", tag))
        # repères de temps : redessinés seulement si leur position ou leur texte change
        ly = Y0 + min(N, len(liste)) * PAS + 5
        sig_axe = (bool(liste), GX1, ly, LANGUE, NUIT)
        if sig_axe != d.get("_axe") or (liste and not cv.find_withtag("mon_axe")):
            d["_axe"] = sig_axe
            cv.delete("mon_axe")
            if liste:
                # chacun CENTRÉ sous l'endroit qu'il désigne (début de la jauge, les deux petits blancs, fin)
                import tkinter.font as tkfont
                if self.__dict__.get("_pol_rep") is None:
                    self._pol_rep = tkfont.Font(family=F_SAISIE, size=11)
                pol_rep = self._pol_rep
                # le PREMIER CHIFFRE de « −30 min », « −20 min », « −10 min » est posé pile sur l'endroit désigné
                # (début de la jauge, premier espace vide, second espace vide) ; le « 0 » reste centré à la fin
                for x_rep, txt_rep in ((GX1 + cw / 2 - 7, t("coup_debut")), (xc(20) - ECART / 2, "−20 min"),
                                       (xc(40) - ECART / 2 - 1, "−10 min")):
                    avant = pol_rep.measure(txt_rep[0]) + pol_rep.measure(txt_rep[1]) / 2
                    cv.create_text(x_rep - avant, ly, text=txt_rep, anchor="w", font=(F_SAISIE, 11), fill=VIOLET,
                                   tags=("mon_axe",))
                cv.create_text(GX2, ly, text=t("coup_fin"), anchor="center", font=(F_SAISIE, 11), fill=VIOLET,
                               tags=("mon_axe",))
        if nb > N:
            cv.create_text(668, 809, text=f"{d['scroll'] + 1}–{min(nb, d['scroll'] + N)} / {nb}", anchor="e",
                           font=(F_SAISIE, 14), fill=GRIS_TEXTE, tags=("mon_dyn",))
        self.barre_defil("mon", 683, 352, 754, nb, N, d["scroll"], self.mon_aller)
        self.menu_remonter()
        self.mon_dessiner_graphe()
        self.menu_remonter()

    GRAPHES = ("debit", "lat", "pertes", "gigue")

    @staticmethod
    def nom_court(a):
        return a.get("nom") or a["ip"]

    # ===== débit des cartes réseau (relevé chaque seconde) =====
    def debit_demarrer(self):
        if getattr(self, "_debit_th", None):
            return
        etat = self.debit

        def boucle():
            derniere = 0.0
            while True:
                try:
                    if not etat["noms"] or time.time() - derniere > 15:
                        etat["noms"] = dict(cartes_debit())
                        derniere = time.time()
                    if getattr(self, "onglet", "") != "monitoring":     # débit affiché seulement dans Monitoring
                        etat["prev"].clear()                           # (le 1er point au retour ne mélange pas l'absence)
                        time.sleep(1.0)
                        continue
                    ok, out = lancer(["netstat", "-ib"], delai=4)
                    if ok:
                        maintenant = time.time()
                        for dev, (rx, tx) in lire_octets(out).items():
                            if etat["noms"] and dev not in etat["noms"]:
                                continue
                            avant = etat["prev"].get(dev)
                            etat["prev"][dev] = (maintenant, rx, tx)
                            if avant:
                                etat["pts"].setdefault(dev, deque(maxlen=120)).append(debit_mbps(avant, (maintenant, rx, tx)))
                        etat["v"] += 1
                except Exception as e:  # noqa: BLE001
                    print("débit :", repr(e), file=sys.stderr)
                time.sleep(1.0)
        self._debit_th = threading.Thread(target=boucle, daemon=True)
        self._debit_th.start()

    def debit_carte_profil(self, nom=None):
        """Périphérique (en0…) de la première carte du profil de Configuration (sinon chaîne vide)."""
        try:
            if nom is None:
                nom = (self.ifaces[0].get("interface") or "").strip() if self.ifaces else ""
        except (AttributeError, IndexError, TypeError):
            return ""
        if not nom:
            return ""
        for dev, port in self.debit["noms"].items():
            if port == nom:
                return dev
        return ""

    def debit_selection(self):
        """Cartes dont on trace le débit : le choix de l'utilisateur, sinon la carte du réseau surveillé."""
        d = self.mon_data
        if "gr_cartes" not in d:
            d["gr_cartes"] = [str(c) for c in (lire_reglages().get("debit_cartes") or [])]
        connues = set(self.debit["noms"]) | set(self.debit["pts"])
        sel = [c for c in d["gr_cartes"] if c in connues]
        if sel:
            return sel[:6]
        dev = self.debit_carte_profil()
        if dev:
            return [dev]
        dev = d.get("device") or ""
        if dev in connues:
            return [dev]
        if self.debit["noms"]:
            return [sorted(self.debit["noms"])[0]]
        return sorted(self.debit["pts"])[:1]

    # ===== courbes du bas (flèches ‹ › dans la barre rouge) =====
    def gr_appareils(self):
        d = self.mon_data
        sel = [c for c in (d.get("gr_apps") or []) if c in d["app"]]
        if sel:
            return sel[:6]
        suivis = [c for c in self.suivi if c in d["app"]][:6]      # les appareils cochés (surveillance continue) sont tracés d'office
        if d.get("sel") in d["app"] and d["sel"] not in suivis:
            suivis = (suivis + [d["sel"]])[-6:]                     # ... avec celui qui est sélectionné dans la liste
        if suivis:
            return suivis
        # rien de choisi : on trace d'office les premiers appareils suivis (leurs pings de santé)
        actifs = [c for c in sorted(d["app"]) if not d["app"][c].get("passif")]
        return actifs[:3]

    def serie_appareil(self, cle, n=90):
        s_ = self.suivi.get(cle)
        if s_:
            return list(s_["pts"])[-n:]
        a = self.mon_data["app"].get(cle)
        return list(a["hist"])[-n:] if a else []

    def gr_signature(self):
        d = self.mon_data
        mode = self.GRAPHES[d.get("gr_i", 0) % len(self.GRAPHES)]
        if mode == "debit":
            return (mode, tuple(self.debit_selection()), self.debit["v"], tuple(sorted(self.debit["noms"])))
        cles = self.gr_appareils()
        return (mode, tuple(cles), tuple((c, d["app"][c].get("npts", 0), len(self.suivi[c]["pts"]) if c in self.suivi else 0,
                                          d["app"][c].get("nom")) for c in cles))

    def gr_aller(self, sens):
        d = self.mon_data
        d["gr_i"] = (d.get("gr_i", 0) + sens) % len(self.GRAPHES)
        self.jouer("pop")
        self.mon_dessiner_graphe()

    def gr_dessin_fleche(self, sens):
        def dessin(cx, cy, tags):
            if sens < 0:
                pts = (cx + 3.5, cy - 8, cx - 4.5, cy, cx + 3.5, cy + 8)
            else:
                pts = (cx - 3.5, cy - 8, cx + 4.5, cy, cx - 3.5, cy + 8)
            self.cv.create_polygon(*pts, fill=ENCRE, outline=ENCRE, width=2, joinstyle="round", tags=tags)
        return dessin

    def gr_basculer(self, mode, cle):
        """Ajoute ou retire une carte / un appareil des courbes (au moins un, six au plus)."""
        d = self.mon_data
        sel = list(self.debit_selection() if mode == "debit" else self.gr_appareils())
        if cle in sel:
            if len(sel) > 1:
                sel.remove(cle)
        elif len(sel) < 6:
            sel.append(cle)
        if mode == "debit":
            d["gr_cartes"] = sel
            sauver_reglage(debit_cartes=sel)
        else:
            d["gr_apps"] = sel
        self.jouer("pop")
        self.mon_dessiner_graphe()

    def gr_menu(self, e, mode):
        """Petit menu natif avec une case par carte / appareil : on coche pour ajouter, on décoche pour retirer."""
        m = tk.Menu(self, tearoff=0)
        self._gr_vars = []
        if mode == "debit":
            actuel = set(self.debit_selection())
            noms = dict(self.debit["noms"])
            for c in self.debit["pts"]:
                noms.setdefault(c, c)
            entrees = [(c, f"{n}  ({c})") for c, n in sorted(noms.items(), key=lambda x: x[1])]
        else:
            actuel = set(self.gr_appareils())
            entrees = [(a["cle"], libelle_appareil(a)) for a in self.mon_lignes()]
        for cle, lib in entrees:
            v = tk.BooleanVar(value=cle in actuel)
            self._gr_vars.append(v)
            m.add_checkbutton(label=lib, variable=v, command=lambda c=cle: self.gr_basculer(mode, c))
        if not entrees:
            m.add_command(label=t("gr_aucun"), state="disabled")
        try:
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()

    def gr_puces(self, items, mode, tags):
        """Rangée de pastilles (une par carte / appareil, clic = retirer) et bouton « + » pour en ajouter.
        Tout reste dans le cadre : la largeur des pastilles s'adapte et les noms trop longs sont raccourcis."""
        cv = self.cv
        x, y1, y2 = 726, 606, 628
        cy = (y1 + y2) / 2
        visibles = items[:3]
        reste = len(items) - len(visibles)
        n = len(visibles)
        plusieurs = len(items) > 1
        place = 310 - (36 if reste > 0 else 24) - 6 - 5 * max(0, n - 1)
        w = min(150 if n == 1 else 112, place / max(1, n))
        for i, (nom, col, cle) in enumerate(visibles):
            tag = f"gr_p{i}"
            cv.create_polygon(contour(x, y1, x + w, y2, 10, i + 400, 0.5, 30), smooth=True, fill=CREME_CLAIR, outline=NOIR,
                              width=2, tags=tags + (tag,))
            cv.create_oval(x + 7, cy - 5, x + 17, cy + 5, fill=col, outline=NOIR, width=1.5, tags=tags + (tag,))
            zone = w - 24 - (18 if plusieurs else 8)
            txt = tronquer(nom, max(4, int(zone / 6.4)))
            tid = cv.create_text(x + 22, cy + 0.5, text=txt, anchor="w", font=(F_TEXTE, 13), fill=ENCRE,
                                 tags=tags + (tag,))
            self.ajuster(tid, F_TEXTE, 13, zone)
            cv.tag_bind(tag, "<ButtonRelease-1>", lambda e: self.after(1, lambda ev=e: self.gr_menu(ev, mode)))
            if plusieurs:
                tag_x = f"gr_x{i}"
                cv.create_text(x + w - 11, cy + 0.5, text="×", font=(F_TITRE, 17), fill=ENCRE, tags=tags + (tag_x, tag))
                cv.tag_bind(tag_x, "<ButtonRelease-1>",
                            lambda e, c=cle: (self.after(1, lambda: self.gr_basculer(mode, c)), "break")[1])
            cv.tag_bind(tag, "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind(tag, "<Leave>", lambda e: self._curseur(""))
            x += w + 5
        etiquette = f"+{reste}" if reste > 0 else "+"
        wp = 24 if reste <= 0 else 36
        cv.create_polygon(contour(x, y1, x + wp, y2, 10, 499, 0.5, 30), smooth=True, fill=ROSE, outline=NOIR, width=2,
                          tags=tags + ("gr_plus",))
        cv.create_text(x + wp / 2, cy + 0.5, text=etiquette, font=(F_TITRE, 14), fill=CLAIR, tags=tags + ("gr_plus",))
        cv.tag_bind("gr_plus", "<ButtonRelease-1>", lambda e: self.after(1, lambda: self.gr_menu(e, mode)))
        cv.tag_bind("gr_plus", "<Enter>", lambda e: self._curseur("pointinghand"))
        cv.tag_bind("gr_plus", "<Leave>", lambda e: self._curseur(""))

    def gr_legende(self, entrees, tags, large=False):
        cv = self.cv
        par_ligne = 1 if large else 3
        largeur = 300 if large else 98
        for i, (txt, col) in enumerate(entrees[:6]):
            x = 728 + (i % par_ligne) * (largeur + 6)
            y = 817 + (i // par_ligne) * 16
            decal = 0
            if col:
                cv.create_oval(x, y - 5, x + 10, y + 5, fill=col, outline=NOIR, width=1.5, tags=tags)
                decal = 15
            tid = cv.create_text(x + decal, y, text=txt, anchor="w", font=(F_SAISIE, 13), fill=VIOLET, tags=tags)
            self.ajuster(tid, F_SAISIE, 13, largeur - decal)

    def mon_dessiner_graphe(self):
        cv = self.cv
        d = self.mon_data
        cv.delete("gr_dyn")
        tags = ("gr_dyn",)
        mode = self.GRAPHES[d.get("gr_i", 0) % len(self.GRAPHES)]
        yt = self.centre_barre(710, 561, 1050, 845, 0.25, 732)
        tt = cv.create_text(732, yt - 1.2, text=t("gr_" + mode), anchor="w", font=(F_TITRE, 18), fill=CLAIR, tags=tags)
        self.ajuster(tt, F_TITRE, 18, 215)
        if mode == "debit":
            cles = self.debit_selection()
            items = [(self.debit["noms"].get(c, c), COULEURS_COURBES[i % 6], c) for i, c in enumerate(cles)]
        else:
            cles = self.gr_appareils()
            items = [(self.nom_court(d["app"][c]), COULEURS_COURBES[i % 6], c) for i, c in enumerate(cles)]
        self.gr_puces(items, mode, tags)
        self.cadre_dessine(725, 640, 1036, 806, 341, tags=tags)
        gx1, gy1, gx2, gy2 = 778, 664, 1024, 790
        NP = 60
        series, couleurs, legende, unite, mx, barres, large = [], [], [], "ms", 10.0, None, False
        message = ""
        f1 = (lambda v: f"{v:.1f}".replace(".", ",")) if LANGUE == "fr" else (lambda v: f"{v:.1f}")
        if mode == "debit":
            unite = "Mb/s"
            pts = {c: list(self.debit["pts"].get(c, ()))[-NP:] for c in cles}
            if len(cles) == 1 and pts[cles[0]]:
                p = pts[cles[0]]
                series = [[v[0] for v in p], [v[1] for v in p]]
                couleurs = ["#4A78E6", ROSE]
                legende = [(t("gr_recu", v=f"{f1(p[-1][0])} Mb/s"), couleurs[0]),
                           (t("gr_envoye", v=f"{f1(p[-1][1])} Mb/s"), couleurs[1])]
            else:
                for i, c in enumerate(cles):
                    p = pts[c]
                    if not p:
                        continue
                    series.append([v[0] + v[1] for v in p])
                    couleurs.append(COULEURS_COURBES[i % 6])
                    legende.append((f"{tronquer(self.debit['noms'].get(c, c), 8)} {f1(p[-1][0] + p[-1][1])}", couleurs[-1]))
            hauts = [x for s_ in series for x in s_]
            mx = echelle_jolie(max(hauts) * 1.1) if hauts else 1
            if not series:
                message = t("gr_attente")
        else:
            if not cles:
                message = "—"
            actifs = [c for c in cles if not d["app"][c].get("passif")]
            if cles and not actifs:
                if all(d["app"][c].get("perdu") for c in cles):      # disparu du réseau : ni ping ni ARP
                    message = t("gr_perdus") if len(cles) > 1 else t("mon_perdu_msg")
                else:
                    message = t("gr_passifs") if len(cles) > 1 else t("mon_passif")
            if mode == "lat":
                for i, c in enumerate(cles):
                    if c in actifs:
                        series.append(self.serie_appareil(c, 90))
                        couleurs.append(COULEURS_COURBES[i % 6])
                bons = [p for s_ in series for p in s_ if p is not None]
                mx = max(10.0, (max(bons) if bons else 10.0) * 1.25)
                if len(actifs) == 1:
                    large = True
                    st = stats_latence(series[0])
                    legende = [(t("lat_stats", mn=st[0], moy=st[1], mx=st[2], p=st[3]) if st else t("lat_attente"), None)]
                    s_ = self.suivi.get(actifs[0])
                    if s_:
                        n = len(s_["pertes"])
                        mxd = max((p_[1] for p_ in s_["pertes"]), default=0)
                        legende.append((t("suivi_stats", n=n, mx=duree_precise(mxd)) if n else t("suivi_stats0"),
                                        ERREUR if n else VERT_OK))
                else:
                    for i, c in enumerate(actifs):
                        ser = self.serie_appareil(c, 90)
                        dernier = next((p for p in reversed(ser) if p is not None), None) if ser else None
                        legende.append((f"{tronquer(self.nom_court(d['app'][c]), 8)} {f1(dernier) if dernier is not None else '—'}",
                                        COULEURS_COURBES[cles.index(c) % 6]))
            elif mode == "pertes":
                unite, mx = "%", 100.0
                sers = [self.serie_appareil(c, 90)[-40:] for c in actifs]
                L = max((len(s_) for s_ in sers), default=0)
                fr = []
                for i in range(L):
                    idx = i - L
                    vals = [s_[idx] for s_ in sers if len(s_) >= -idx]
                    fr.append(sum(v is None for v in vals) / len(vals) if vals else 0.0)
                barres = fr
                nb = sum(len(s_) for s_ in sers)
                pertes = sum(v is None for s_ in sers for v in s_)
                if nb:
                    large = True
                    legende = [(t("gr_pertes_txt", n=pertes, m=nb, p=round(100 * pertes / nb)), ERREUR if pertes else VERT_OK)]
            else:  # gigue
                for i, c in enumerate(cles):
                    if c in actifs:
                        ser = gigue_serie(self.serie_appareil(c, 90))
                        series.append(ser)
                        couleurs.append(COULEURS_COURBES[i % 6])
                        moy = gigue_moyenne(self.serie_appareil(c, 90))
                        legende.append((t("gr_gigue_txt", nom=tronquer(self.nom_court(d["app"][c]), 7),
                                          v=f1(moy) if moy is not None else "—"), couleurs[-1]))
                bons = [g for s_ in series for g in s_ if g is not None]
                mx = echelle_jolie(max(bons) * 1.25) if bons else 1
                if len(legende) > 3:
                    legende = legende[:6]
        fmt = (lambda v: f"{v:.0f}") if mx >= 10 else (lambda v: f"{v:g}")
        for fr_ in (0, 0.5, 1):
            y = gy2 - (gy2 - gy1) * fr_
            cv.create_line(gx1, y, gx2, y, fill=CREME_GRIS, dash=(3, 4), width=1.5, tags=tags)
            tl = cv.create_text(gx1 - 7, y, text=fmt(mx * fr_), anchor="e", font=(F_SAISIE, 12), fill=VIOLET, tags=tags)
            self.ajuster(tl, F_SAISIE, 12, 40)
        tu = cv.create_text(732, 651, text=unite, anchor="w", font=(F_SAISIE, 12), fill=VIOLET, tags=tags)
        self.ajuster(tu, F_SAISIE, 12, 50)
        pas = (gx2 - gx1) / (NP - 1)
        if barres is not None:
            pb = (gx2 - gx1) / 40.0
            L = len(barres)
            for i, f_ in enumerate(barres):
                if f_ <= 0:
                    continue
                x2_ = gx2 - (L - 1 - i) * pb
                h = max(3.0, (gy2 - gy1) * f_)
                cv.create_polygon(x2_ - pb + 1, gy2 - h, x2_ - 1, gy2 - h, x2_ - 1, gy2, x2_ - pb + 1, gy2, fill=ERREUR,
                                  outline=NOIR, width=1.5, tags=tags)
        for ser, col in zip(series, couleurs):
            reste = ser[-NP:]
            x0 = gx2 - pas * (len(reste) - 1)
            morceau = []

            def tracer(m_, col=col):
                if len(m_) >= 4:
                    cv.create_line(m_, fill=NOIR, width=7, capstyle="round", joinstyle="round", tags=tags)
                    cv.create_line(m_, fill=col, width=3.5, capstyle="round", joinstyle="round", tags=tags)
                elif len(m_) == 2:
                    cv.create_oval(m_[0] - 4, m_[1] - 4, m_[0] + 4, m_[1] + 4, fill=col, outline=NOIR, width=2, tags=tags)
            for k, p in enumerate(reste):
                x = x0 + k * pas
                if p is None:
                    tracer(morceau)
                    morceau = []
                    if mode == "lat" and len(series) == 1:
                        cv.create_line(x, gy1, x, gy2, fill=ERREUR, width=2, dash=(3, 3), tags=tags)
                    continue
                morceau += [x, gy2 - (gy2 - gy1) * min(p, mx) / mx]
            tracer(morceau)
        if message:
            cv.create_text((gx1 + gx2) / 2, (gy1 + gy2) / 2, text=message, font=(F_TEXTE, 15), fill=GRIS_TEXTE, width=230,
                           justify="center", tags=tags)
        elif barres is not None and not barres:
            cv.create_text((gx1 + gx2) / 2, (gy1 + gy2) / 2, text=t("lat_attente"), font=(F_TEXTE, 15), fill=GRIS_TEXTE,
                           tags=tags)
        self.gr_legende(legende, tags, large)


    def mon_hist_maj(self, force=False):
        w = getattr(self, "mon_texte", None)
        if w is None or self.onglet != "monitoring":
            return
        evts = lire_evenements()
        f = self.mon_data["filtre"]
        sig = (len(evts), f, evts[-1]["t"] if evts else 0)
        if not force and sig == self.mon_data.get("hist_sig"):
            return
        self.mon_data["hist_sig"] = sig
        genres = None if f == "tout" else ("deconnexion", "erreur", "avert", "conflit")
        w.delete("1.0", "end")
        affiches = [e for e in evts if genres is None or e.get("g") in genres]
        if not affiches:
            w.insert("end", t("hist_vide"), "info")
        for e in reversed(affiches[-400:]):
            quand = time.strftime("%d/%m %H:%M:%S", time.localtime(e.get("t", 0)))
            w.insert("end", f"{quand}   {texte_evenement(e)}\n", e.get("g", "info"))

