    def bulle_aide_fermer(self, e=None):
        if self.cv.find_withtag("bulle_aide"):
            self._ba_ferme_t = time.time()
        self.cv.delete("bulle_aide")

    def bulle_aide_ouvrir(self, cx, cy, texte, largeur=380, titre="", haut=False, legende=None, x1=None):
        """Petite bulle de BD sous un bouton « ? » (cx, cy) : se ferme au clic n'importe où ou avec Échap."""
        cv = self.cv
        if not self.__dict__.get("_ba_lie"):
            self._ba_lie = True
            cv.bind("<ButtonPress-1>", self.bulle_aide_fermer, add="+")
        if time.time() - self.__dict__.get("_ba_ferme_t", 0) < 0.4:
            return                                         # ce clic vient de fermer la bulle : on ne la rouvre pas
        cv.delete("bulle_aide")
        tag = ("bulle_aide",)
        mesure = cv.create_text(-3000, -3000, text=texte, font=(F_TEXTE, 14), width=largeur - 40, anchor="nw")
        mb = cv.bbox(mesure)
        cv.delete(mesure)
        h_txt = (mb[3] - mb[1]) if mb else 120
        legende = list(legende or [])
        h_leg = (28 * len(legende) - 8) if legende else 0       # lignes « pastille de couleur + explication »
        H = int(h_txt + 36 + h_leg)
        if x1 is not None:
            bx1 = x1
            bx2 = bx1 + largeur
        else:
            bx2 = min(1100, cx + 44)     # le bord droit dépasse le bouton : la queue repose sur le bord droit, pas sur le coin arrondi
            bx1 = bx2 - largeur
        if haut:                                           # bouton en bas de la fenêtre : la bulle s'ouvre vers le haut
            by2 = cy - 29
            by1 = by2 - H
            queue_ = [cx - 12, by2 - 3, cx, cy - 19, cx + 9, by2 - 3]
        else:
            by1 = cy + 29
            by2 = by1 + H
            queue_ = [cx - 12, by1 + 3, cx, cy + 19, cx + 9, by1 + 3]
        cv.create_polygon(contour(bx1 + 5, by1 + 6, bx2 + 5, by2 + 6, 16, 521, 1.0, 60), smooth=True, fill=NOIR,
                          outline=NOIR, width=3, tags=tag)
        cv.create_polygon(contour(bx1, by1, bx2, by2, 16, 522, 1.4, 60), smooth=True, fill=BULLE_FOND, outline=NOIR,
                          width=3, joinstyle="round", tags=tag)
        tracer_queue_bd(cv, queue_, tag)
        ycol = by2 - 1.5 if haut else by1 + 1.5
        for k, (couleur, ligne) in enumerate(legende):
            yl = by1 + 22 + 28 * k
            cv.create_oval(bx1 + 22, yl - 8, bx1 + 38, yl + 8, fill=couleur, outline=NOIR, width=2, tags=tag)
            cv.create_text(bx1 + 48, yl, text=ligne, anchor="w", font=(F_TEXTE, 15), fill=BULLE_TEXTE, tags=tag)
        cv.create_text(bx1 + 20, by1 + 18 + h_leg, text=texte, anchor="nw", font=(F_TEXTE, 14), fill=BULLE_TEXTE,
                       width=largeur - 40, tags=tag)

    def ouvrir_aide_appareils(self):
        """Bouton « ? » de l'onglet Appareils : code couleur des pastilles, rythme des scans, appareils « ARP seulement »."""
        r = self.ronds["app_aide"]
        q, sc = perf()[1], perf()[0]
