    def app_recherche_dessiner(self):
        """Barre de recherche (un vrai champ de saisie) au-dessus du tableau."""
        cv = self.cv
        d = self.mon_data
        cv.create_polygon(contour(49, 207, 526, 243, 12, 415, 0.8, 60), smooth=True, fill=NOIR, outline=NOIR, width=3)
        boite_rech = cv.create_polygon(contour(46, 203, 523, 239, 12, 414, 1.2, 60), smooth=True, fill=CREME_CLAIR,
                                       outline=NOIR, width=3, joinstyle="round")
        cv.create_oval(60, 212, 76, 228, outline=ENCRE, width=3)               # petite loupe dessinée
        cv.create_line(74, 226, 82, 234, fill=ENCRE, width=3.4, capstyle="round")
        self.app_rech = None
        self._fen_masq = []
        try:
            def change(*_):
                d["app_recherche"] = var.get()
                att = self.__dict__.get("_rech_att")
                if att is not None:
                    try:
                        self.after_cancel(att)
                    except Exception:
                        journal_exc()
                self._rech_att = self.after(160, self.app_recherche_appliquer)
            var = tk.StringVar(value=d.get("app_recherche", ""))
            self.app_rech_var = var
            self.app_rech = ChampPares(self, "app_rech", boite_rech, 80, 203, 486, 239, var, police=19,
                                       famille=F_TEXTE, a_echap=lambda: var.set(""))
            var.trace_add("write", change)
        except Exception as e:  # noqa: BLE001
            print("recherche :", repr(e), file=sys.stderr)
        # petite croix pour tout effacer
        cv.create_oval(490, 211, 512, 233, fill=CREME, outline=NOIR, width=2, tags=("app_rech_x",))
        cv.create_line(496, 217, 506, 227, fill=ENCRE, width=2.4, capstyle="round", tags=("app_rech_x",))
        cv.create_line(506, 217, 496, 227, fill=ENCRE, width=2.4, capstyle="round", tags=("app_rech_x",))
        cv.tag_bind("app_rech_x", "<Button-1>", lambda e: self.app_recherche_vider())
        cv.tag_bind("app_rech_x", "<Enter>", lambda e: self._curseur("pointinghand"))
        cv.tag_bind("app_rech_x", "<Leave>", lambda e: self._curseur(""))

    def app_recherche_appliquer(self):
        self._rech_att = None
        if self.onglet == "appareils":
            self.mon_data["app_scroll"] = 0
            self.app_dessiner_dyn()

    def app_recherche_vider(self):
        self.mon_data["app_recherche"] = ""
        try:
            self.app_rech_var.set("")
        except Exception:
            journal_exc()
        self.cv.focus_set()
        self.app_recherche_appliquer()

    def app_lignes(self):
        liste = [dict(a, cle=k) for k, a in self.inv.items() if a.get("ip")]
        choix = self.app_carte_choisie()
        if not choix:
            return []                             # aucune carte choisie : rien à montrer
        if choix != "*":
            liste = [a for a in liste if a.get("carte") == choix]
        d = self.mon_data
        # seulement ce qui est sur le réseau actuel (en ligne ou déconnecté) ; les autres restent dans l'inventaire
        # (noms, notes) et réapparaissent, avec leurs infos, la prochaine fois qu'ils se connectent
        liste = [a for a in liste if a["cle"] in d["app"]]
        noms = noms_memorises()
        liste = filtrer_appareils(liste, d.get("app_recherche", ""), noms)
        col, croissant = d.get("app_tri", ("etat", True))
        return self.epingles_en_tete(trier_appareils(liste, col, croissant, noms, d["app"], time.time()))

    # ----- appareils épinglés : toujours en haut des listes (Appareils, Monitor : liste et santé) -----
    def epingles(self):
        d = self.mon_data
        if "epingles" not in d:
            d["epingles"] = {str(k) for k in lire_reglages().get("epingles", []) if k}
        return d["epingles"]

    def epingles_en_tete(self, liste, cle=lambda a: a["cle"]):
        """Remonte les appareils épinglés (leur ordre relatif ne change pas)."""
        ep = self.epingles()
        if not ep:
            return liste
        return [a for a in liste if cle(a) in ep] + [a for a in liste if cle(a) not in ep]

    def app_epingler(self):
        """Bouton punaise : épingle l'appareil sélectionné (ou la sélection), un second clic le désépingle."""
        d = self.mon_data
        cles = [k for k in d.get("app_set", set()) if k in self.inv] or ([d["app_sel"]] if d.get("app_sel") in self.inv else [])
        if not cles:
            return
        ep = self.epingles()
        if all(k in ep for k in cles):
            ep.difference_update(cles)
        else:
            ep.update(cles)
        sauver_reglage(epingles=sorted(ep))
        d["app_scroll"] = 0
        d["scroll"] = 0
        self.jouer("pop")
        self.app_dessiner_dyn()

    def pastille_etat(self, x1, y1, x2, y2, etat, tags):
        """Voyant d'état d'un appareil : vert (« ok » : ping + ARP), bleu (« arp » : ARP seulement), rouge (« perdu » : rien), orange (« coupure » : connecté mais coupure récente).
        Une bulle rappelle le code couleur quand la souris reste dessus."""
        couleur = {"ok": VERT_OK, "arp": PASSIF, "perdu": ERREUR, "hors": GRIS_TEXTE, "coupure": ATTENTION}[etat]
        o = self.cv.create_oval(x1, y1, x2, y2, fill=couleur, outline=NOIR, width=2, tags=tags)
        self.nom_complet_bulle(o, t("etat_" + etat), centre=True)
        return o

    def vignette_epingle(self, cx, cy, tags):
        """Petite vignette ronde rose avec une punaise, posée sur le coin haut droit de la case d'un appareil épinglé."""
        self.cv.create_oval(cx - 9, cy - 9, cx + 9, cy + 9, fill=ROSE, outline=NOIR, width=2, tags=tags)
        self.pictogramme("punaise", cx, cy, ENCRE, 0.5, tags)

    def app_epingle_maj(self):
        """Le bouton punaise garde son aspect naturel : il ne passe plus en rouge quand la sélection est épinglée
        (la vignette rose sur la case de l'appareil suffit)."""
        return

    def app_trier(self, col):
        """Clic sur un titre de colonne : tri croissant, puis décroissant au second clic."""
        d = self.mon_data
        ancien, croissant = d.get("app_tri", ("etat", True))
        d["app_tri"] = (col, not croissant) if ancien == col else (col, True)
        d["app_scroll"] = 0
        self.jouer("pop")
        self.app_dessiner_dyn()

    def app_cartes(self):
        """Cartes réseau connues de l'inventaire (celles où des appareils ont été vus)."""
        return sorted({a.get("carte") for a in self.inv.values() if a.get("carte")})

    # ----- liste des cartes réseau, commune à Config / Appareils / Monitoring -----
    def _cartes_lire(self):
        """{carte: adresse IP ('' = aucune)} d'après le Mac. Peut prendre du temps : jamais sur le fil principal."""
        res = {}
        try:
            for dev, nom in cartes_debit():
                res[nom] = adresse_de_carte(dev)[0]
        except Exception:  # noqa: BLE001
            journal_exc()
        return res

    def cartes_rafraichir(self, force=False):
        """Relit les cartes en arrière-plan (au plus toutes les 5 s) ; les menus s'ouvrent sur la dernière lecture."""
        th = getattr(self, "_cartes_th", None)
        if th is not None and th.is_alive():
            return
        if not force and time.time() - getattr(self, "_cartes_t", 0) < 5:
            return

        def tache():
            res = self._cartes_lire()
            self._cartes_c, self._cartes_t = res, time.time()
        self._cartes_th = threading.Thread(target=tache, daemon=True)
        self._cartes_th.start()

    def cartes_cache(self):
        c = getattr(self, "_cartes_c", None)
        if c is None:                                   # toute première fois, avant la fin de la lecture de départ
            c = self._cartes_c = self._cartes_lire()
            self._cartes_t = time.time()
        self.cartes_rafraichir()
        return c

    def _cartes_boucle(self):
        """Garde la liste des cartes à jour (toutes les 10 s, en arrière-plan) pour que les menus s'ouvrent sans attendre."""
        try:
            self.cartes_rafraichir()
            self.after(10000, self._cartes_boucle)
        except Exception:  # noqa: BLE001
            journal_exc()

    def _cartes_txt_nb(self, n):
        return t("cartes_ap0") if n == 0 else t("cartes_ap1") if n == 1 else t("cartes_apn", n=n)

    def cartes_menu(self, noms, courant, choisir, special=None, grises=True):
        """Menu des cartes réseau, présenté pareil partout : « carte — IP … — n appareils ».
        Les cartes avec une adresse IP d'abord, celles sans adresse ensuite (grisées si `grises`).
        Dessiné dans la fenêtre (et non un menu natif du Mac : celui-ci pouvait rester coincé et bloquer tous les clics)."""
        info = self.cartes_cache()
        compte = self.app_compte_cartes()
        entrees = []                                    # (libellé, valeur, actif) ; None = trait de séparation
        if special:
            entrees += [(special[1], special[0], True), None]
        avec = sorted((n for n in noms if info.get(n)), key=str.lower)
        sans = sorted((n for n in noms if not info.get(n)), key=str.lower)
        for n in avec:
            entrees.append((f"{n}  —  {t('cartes_ip', ip=info[n])}  —  {self._cartes_txt_nb(compte.get(n, 0))}", n, True))
        if avec and sans:
            entrees.append(None)
        for n in sans:
            entrees.append((f"{n}  —  {t('mon_carte_sans_ip')}", n, not grises))
        self.menu_liste_ouvrir(entrees, courant, choisir)

    def menu_liste_fermer(self, *_):
        cv = self.cv
        if cv.find_withtag("menu_cartes"):
            self._mc_ferme_t = time.time()
        cv.delete("menu_cartes")
        self.survol_oublier("mc_")

    def _mc_hors(self, e):
        cv = self.cv
        if not cv.find_withtag("menu_cartes"):
            return
        if time.time() - self.__dict__.get("_mc_ouvert_t", 0) < 0.3:
            return                                      # ce même clic vient d'ouvrir la liste : il ne doit pas la refermer
        marques = cv.gettags("current") if cv.find_withtag("current") else ()
        if "menu_cartes" not in marques:
            self.after(1, self.menu_liste_fermer)

    def menu_liste_ouvrir(self, entrees, courant, choisir):
        """Petite liste de choix en bulle de BD, au-dessus du pointeur (ou dessous s'il n'y a pas la place)."""
        if time.time() - self.__dict__.get("_mc_ferme_t", 0) < 0.35:
            return                                      # ce clic vient de fermer la liste : on ne la rouvre pas
        self.menu_liste_fermer()
        self._mc_ferme_t = 0
        cv = self.cv
        if not self.__dict__.get("_mc_lie"):
            self._mc_lie = True
            cv.bind("<ButtonPress-1>", self._mc_hors, add="+")
            self.bind("<Escape>", self.menu_liste_fermer, add="+")
        px, py = cv.vers_logique(self.winfo_pointerx() - cv.winfo_rootx(), self.winfo_pointery() - cv.winfo_rooty())
        H_ENT, H_SEP = 24, 8
        larg = 0
        for e in entrees:
            if e:
                m_ = cv.create_text(-3000, -3000, text=e[0], font=(F_TEXTE, 12), anchor="nw")
                bb = cv.bbox(m_)
                cv.delete(m_)
                larg = max(larg, (bb[2] - bb[0]) if bb else 300)
        L = int(min(900, max(220, larg + 52)))
        H = 14 + sum(H_SEP if e is None else H_ENT for e in entrees)
        bx1 = max(14, min(px - 40, 1118 - L))
        by2 = py - 26
        by1 = by2 - H
        if by1 < 8:
            by1 = py + 26
            by2 = by1 + H
            if by2 > 852:
                by1 = max(8, 852 - H)
                by2 = by1 + H
        bx2 = bx1 + L
        tag = ("menu_cartes",)
        self._mc_ouvert_t = time.time()
        cv.create_polygon(contour(bx1 + 4, by1 + 5, bx2 + 4, by2 + 5, 12, 631, 1.2, 80), smooth=True, fill=NOIR,
                          outline=NOIR, width=3, tags=tag)
        cv.create_polygon(contour(bx1, by1, bx2, by2, 12, 632, 1.2, 80), smooth=True, fill=BULLE_FOND, outline=NOIR,
                          width=3, joinstyle="round", tags=tag)
        y = by1 + 7
        for k, e in enumerate(entrees):
            if e is None:
                cv.create_line(bx1 + 12, y + H_SEP / 2, bx2 - 12, y + H_SEP / 2, fill="#CFC3E6", width=1.6, tags=tag)
                y += H_SEP
                continue
            libelle, valeur, actif = e
            etiq = f"mc_{k}"
            fond = cv.create_polygon(contour(bx1 + 6, y + 1, bx2 - 6, y + H_ENT - 1, 6, 650 + k, 0.5, 60), smooth=True,
                                     fill=BULLE_FOND, outline="", tags=tag + (etiq,))
            if valeur == courant:
                cv.create_oval(bx1 + 13, y + H_ENT / 2 - 4, bx1 + 21, y + H_ENT / 2 + 4, fill=ROSE, outline=NOIR, width=2,
                               tags=tag + (etiq,))
            cv.create_text(bx1 + 30, y + H_ENT / 2, text=libelle, anchor="w", font=(F_TEXTE, 12),
                           fill=BULLE_TEXTE if actif else GRIS_TEXTE, tags=tag + (etiq,))
            if actif:
                def survol(v, f=fond):
                    cv.itemconfigure(f, fill=LILAS_PALE if v else BULLE_FOND)
                    self._curseur("pointinghand" if v else "")
                cv.tag_bind(etiq, "<Enter>", lambda e_, k_=etiq, f=survol: self._survol_lisse(k_, True, f))
                cv.tag_bind(etiq, "<Leave>", lambda e_, k_=etiq, f=survol: self._survol_lisse(k_, False, f))
                cv.tag_bind(etiq, "<Button-1>", lambda e_, v_=valeur: self._mc_choisir(v_, choisir))
            y += H_ENT

    def _mc_choisir(self, valeur, choisir):
        self.menu_liste_fermer()
        self._curseur("")
        self.after(1, lambda: choisir(valeur))

    def app_compte_cartes(self):
        """{carte: nombre d'appareils} comptés comme dans la liste de l'onglet Appareils : ceux qui sont sur le réseau actuel
        (en ligne ou déconnectés), sans les appareils mémorisés d'une session précédente."""
        d_app = self.mon_data["app"]
        compte = {}
        for k, a in self.inv.items():
            if a.get("ip") and a.get("carte") and k in d_app:
                compte[a["carte"]] = compte.get(a["carte"], 0) + 1
        return compte

    def app_cartes_toutes(self):
        """Cartes de l'inventaire + toutes les cartes réseau du Mac (Wi-Fi compris), même sans appareil vu dessus."""
        mac = [n for n in self.cartes_cache() if not re.search(r"bluetooth|bridge|pont|iphone|ipad", n, re.I)]
        return sorted(set(self.app_cartes()) | set(mac))

    def app_carte_choisie(self):
        """« * » = toutes, « » = aucune. Par défaut aucune carte n'est choisie : l'utilisateur doit en sélectionner une
        (ou choisir un profil dans Configuration, qui sélectionne la première carte du profil)."""
        d = self.mon_data
        c = d.get("app_carte") or ""
        if c not in ("*", "") and c not in self.app_cartes_toutes():
            c = ""
        return c

    def app_texte_carte(self):
        c = self.app_carte_choisie()
        if not c:
            return t("app_choisir_carte")
        return t("app_toutes_cartes") if c == "*" else c

    def app_basculer_reseau(self):
        """« Toutes les cartes » ou une seule carte réseau, au choix."""
        total = sum(self.app_compte_cartes().values())
        self.cartes_menu(self.app_cartes_toutes(), self.app_carte_choisie(), self.app_choisir_carte,
                         special=("*", f"{t('app_toutes_cartes')}  —  {self._cartes_txt_nb(total)}"), grises=True)

    def app_choisir_carte(self, c):
        d = self.mon_data
        d["app_carte"] = c
        d["app_set"] = set()
        d["app_scroll"] = 0
        self.jouer("pop")
        if c != "*" and c != self.surv_carte_reglee():
            self.mon_carte_choisir(c)                   # le Monitoring surveille désormais cette même carte
        try:
            self.reconstruire_ui(self.cle_bulle)        # redessine la case (icône et nom recentrés)
        except Exception:
            self.bouton_definir("app_reseau", texte=self.tronque_px(self.app_texte_carte(), F_TEXTE, 19, 200))
            self.app_dessiner_dyn()

    def app_aller(self, debut):
        self.mon_data["app_scroll"] = debut
        self.app_dessiner_dyn()

    # ----- jauge du balayage réseau (entre « actualiser » et « Radar ») -----
    JAUGE_SCAN = (384, 800, 570, 822)

    def app_jauge_texte(self):
        P = _PROG_SCAN
        if not P.get("manuel"):                 # balayages automatiques : silencieux
            return 0.0, ""
        if P["actif"] and P["total"]:
            n, tot = P["n"], P["total"]
            ecoule = time.time() - P["t0"]
            reste = int(ecoule / n * (tot - n)) if n >= 8 else None
            return (n / tot, t("jauge_en_cours", pct=int(100 * n / tot), n=n, total=tot,
                               reste=(f"~{reste} s" if reste is not None else "…")))
        if P["dernier"]:
            tot, dur = P["dernier"]
            return 0.0, t("jauge_repos", total=tot, duree=int(dur))
        return 0.0, ""

    def app_jauge_dessiner(self):
        cv = self.cv
        x1, y1, x2, y2 = self.JAUGE_SCAN
        cv.create_polygon(contour(x1, y1, x2, y2, 9, 777, 0.6, 40), smooth=True, fill=CREME_CLAIR, outline=NOIR,
                          width=2.4, joinstyle="round")
        rempl = cv.create_rectangle(x1 + 4, y1 + 4, x1 + 4, y2 - 4, fill="#238A52", outline="")
        ratio, texte = self.app_jauge_texte()
        txt = cv.create_text((x1 + x2) / 2, (y1 + y2) / 2 + 1, text=texte, font=(F_TEXTE, 13), fill=ENCRE)
        self._jauge_scan = {"fill": rempl, "txt": txt, "sig": None}
        self.app_jauge_maj(True)
        if not self.__dict__.get("_jauge_tick_on"):
            self._jauge_tick_on = True
            self.after(700, self.app_jauge_tick)

    def app_jauge_animee(self, J):
        """Jauge de balayage « actualiser » : la barre verte part de la gauche et avance toujours à vue d'œil, même si
        le balayage est presque instantané. Durée minimale selon le nombre d'adresses (~0,9 s pour 254, 2,5 s pour 1000) ;
        si le balayage est plus lent, la barre suit son vrai avancement."""
        P = _PROG_SCAN
        A = J.setdefault("anim", {"t0": None, "aff": 0.0, "actif": False, "last": 0.0, "total": 0, "fin": None})
        now = time.time()
        if P.get("manuel") and P.get("t0") and P["t0"] != A["t0"] and (P["actif"] or P.get("dernier")):
            tot0 = P.get("total") or (P["dernier"][0] if P.get("dernier") else 0)
            A.update(t0=P["t0"], aff=0.0, actif=True, last=now, total=max(1, tot0), fin=None)
            self.after(30, self.app_jauge_anim_boucle)
        if not A["actif"]:
            return self.app_jauge_texte()
        tot = P.get("total") or A["total"]
        A["total"] = max(1, tot)
        duree = max(0.7, min(2.5, A["total"] * 0.0035))
        cible = (P["n"] / P["total"]) if (P["actif"] and P["total"]) else 1.0
        dt = max(0.0, now - A["last"])
        A["last"] = now
        A["aff"] = min(cible, A["aff"] + dt / duree)
        ratio = A["aff"]
        if ratio >= 1.0 and not P["actif"]:
            if A["fin"] is None:
                A["fin"] = now
            elif now - A["fin"] > 0.35:
                A["actif"] = False              # la barre est restée pleine un instant : retour au texte « N adresses »
        n = int(ratio * A["total"])
        return ratio, t("jauge_en_cours", pct=int(100 * ratio), n=n, total=A["total"],
                        reste=f"~{max(0, int((1 - ratio) * duree))} s")

    def app_jauge_anim_boucle(self):
        J = self.__dict__.get("_jauge_scan")
        if not J or not J.get("anim", {}).get("actif"):
            return
        if self.onglet == "appareils" and self.ui_prete:
            self.app_jauge_maj()
        self.after(30, self.app_jauge_anim_boucle)

    def app_jauge_maj(self, force=False):
        J = self.__dict__.get("_jauge_scan")
        if not J:
            return
        ratio, texte = self.app_jauge_animee(J)
        sig = (texte, round(ratio, 3))
        if sig == J["sig"] and not force:
            return
        J["sig"] = sig
        x1, y1, x2, y2 = self.JAUGE_SCAN
        try:
            self.cv.coords(J["fill"], x1 + 4, y1 + 4, x1 + 4 + (x2 - x1 - 8) * ratio, y2 - 4)
            self.cv.itemconfigure(J["fill"], state="normal" if ratio > 0 else "hidden")
            self.cv.itemconfigure(J["txt"], text=texte, fill=ENCRE, font=(F_TEXTE, 13))
            self.ajuster(J["txt"], F_TEXTE, 13, x2 - x1 - 12, mini=8)
        except Exception:  # noqa: BLE001
            journal_exc()

    def app_jauge_suivre(self, secondes):
        """Après un clic sur « actualiser » : la jauge se rafraîchit souvent (le scan est court, on ne veut pas en rater le début)."""
        self._jauge_fin = time.time() + secondes
        if self.__dict__.get("_jauge_suivi"):
            self.app_jauge_maj(True)
            return
        self._jauge_suivi = True

        def tic():
            if self.onglet == "appareils" and self.ui_prete:
                self.app_jauge_maj()
            if time.time() < self.__dict__.get("_jauge_fin", 0):
                self.after(100, tic)
            else:
                self._jauge_suivi = False
        self.app_jauge_maj(True)
        self.after(100, tic)

    def app_jauge_tick(self):
        if self.onglet == "appareils" and self.ui_prete:
            self.app_jauge_maj()
        self.after(350 if _PROG_SCAN["actif"] else 1000, self.app_jauge_tick)

    def app_dessiner_dyn(self):
        if self.__dict__.get("_menu_cartes"):
            return
        cv = self.cv
        d = self.mon_data
        cv.delete("app_dyn")
        liste = self.app_lignes()
        noms = noms_memorises()
        N = 12
        tri_col, tri_croissant = d.get("app_tri", ("etat", True))
        xs = [x for _, x in self.COLONNES] + [1018]
        for k, ((cle_c, x), nom_h) in enumerate(zip(self.COLONNES, ("hdr_nom", "hdr_ip", "hdr_mac", "hdr_fab",
                                                                    "hdr_note"))):
            tag_h = f"app_h_{cle_c}"
            x2 = xs[k + 1] - 6
            cv.create_polygon(x - 8, 257, x2, 257, x2, 281, x - 8, 281, fill=LILAS_CLAIR, outline="",
                              tags=("app_dyn", tag_h))
            actif = cle_c == tri_col
            th = cv.create_text(x, 269, text=t(nom_h), anchor="w", font=(F_TEXTE, 16), fill=VIOLET,
                                tags=("app_dyn", tag_h))
            if actif:                                    # petite flèche dessinée (▲ croissant, ▼ décroissant)
                bb = cv.bbox(th)
                fx = (bb[2] if bb else x + 40) + 12
                pts = (fx - 6, 274, fx + 6, 274, fx, 263) if tri_croissant else (fx - 6, 264, fx + 6, 264, fx, 275)
                cv.create_polygon(*pts, fill=ROSE, outline=ROSE, width=1, joinstyle="round", tags=("app_dyn", tag_h))
            cv.tag_bind(tag_h, "<ButtonRelease-1>", lambda e, c=cle_c: self.after(1, lambda: self.app_trier(c)))
            cv.tag_bind(tag_h, "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind(tag_h, "<Leave>", lambda e: self._curseur(""))
        # zone sans texte, au-dessus des pastilles : un clic trie par état (vert / rouge)
        cv.create_polygon(48, 257, 74, 257, 74, 281, 48, 281, fill=LILAS_CLAIR, outline="", tags=("app_dyn", "app_h_etat"))
        if tri_col == "etat":
            pts = (55, 273, 67, 273, 61, 262) if tri_croissant else (55, 263, 67, 263, 61, 274)
            cv.create_polygon(*pts, fill=ROSE, outline=ROSE, width=1, joinstyle="round", tags=("app_dyn", "app_h_etat"))
        cv.tag_bind("app_h_etat", "<ButtonRelease-1>", lambda e: self.after(1, lambda: self.app_trier("etat")))
        cv.tag_bind("app_h_etat", "<Enter>", lambda e: self._curseur("pointinghand"))
        cv.tag_bind("app_h_etat", "<Leave>", lambda e: self._curseur(""))
        d["app_scroll"] = max(0, min(d.get("app_scroll", 0), max(0, len(liste) - N)))
        maintenant = time.time()

        def en_ligne_ok(a):
            v = d["app"].get(a["cle"])
            return bool(v and not v.get("perdu") and maintenant - v.get("vu", 0) < 90)
        en_ligne = sum(1 for a in liste if en_ligne_ok(a))
        visibles = {a["cle"] for a in liste}
        d["app_set"] = {k for k in d.get("app_set", set()) if k in visibles}
        if d.get("app_sel") not in visibles:
            d["app_sel"] = liste[0]["cle"] if liste else None
        if not d["app_set"] and d["app_sel"]:
            d["app_set"] = {d["app_sel"]}
            d["app_ancre"] = d["app_sel"]
        perdu_fond = "#FFD9D2" if not NUIT else "#6A2F4F"
        # nombre de résultats de la recherche
        if str(d.get("app_recherche", "")).strip():
            cv.create_text(980, 222, text=t("app_resultats", n=len(liste)), anchor="e", font=(F_SAISIE, 17), fill=VIOLET,
                           tags=("app_dyn",))
        if not liste:
            if str(d.get("app_recherche", "")).strip():
                msg = t("app_aucun_mot", q=str(d.get("app_recherche", "")).strip())
            elif not self.app_carte_choisie():
                msg = t("app_sans_carte")
            else:
                msg = t("app_vide")
            cv.create_text(540, 520, text=msg, font=(F_TEXTE, 22), fill=GRIS_TEXTE, width=700,
                           justify="center", tags=("app_dyn",))
        for i, a in enumerate(liste[d["app_scroll"]:d["app_scroll"] + N]):
            y = 297 + i * 39
            vivant = d["app"].get(a["cle"])
            etat_p = "ok"
            if vivant and not vivant.get("perdu") and maintenant - vivant.get("vu", 0) < 90:
                etat_p = "arp" if vivant.get("passif") else "ok"
                etat, couleur, led = t("app_en_ligne"), VERT_OK, (PASSIF if etat_p == "arp" else VERT_OK)
            elif vivant and vivant.get("perdu"):
                etat_p = "perdu"
                etat, couleur, led = t("mon_perdu"), ERREUR, ERREUR
            else:
                vu = time.strftime("%d/%m %H:%M", time.localtime(a["vu"])) if a.get("vu") else "—"
                etat_p = "hors"                   # plus de scan récent (surveillance arrêtée) : on ne sait plus
                etat, couleur, led = vu, GRIS_TEXTE, GRIS_TEXTE
            sel = a["cle"] in d["app_set"]
            tag = f"app_r{i}"
            cv.create_polygon(contour(46 + 3, y + 3, 1012 + 3, y + 33 + 3, 8, i + 50, 0.7, 60), smooth=True, fill=NOIR,
                              outline=NOIR, width=2, tags=("app_dyn", tag))
            cv.create_polygon(contour(46, y, 1012, y + 33, 8, i + 20, 0.9, 60), smooth=True,
                              fill=perdu_fond if etat == t("mon_perdu") else (LILAS_PALE if sel else CREME_CLAIR),
                              outline=ROSE if sel else NOIR, width=4 if sel else 2.4, tags=("app_dyn", tag))
            self.pastille_etat(58, y + 9, 74, y + 25, etat_p, ("app_dyn", tag))
            # petite croix discrète : oublier cet appareil (grisée, rougit au survol)
            cx_t = f"app_x{i}"
            cv.create_polygon(974, y + 6, 1002, y + 6, 1002, y + 28, 974, y + 28, fill=perdu_fond if etat == t("mon_perdu") else (LILAS_PALE if sel else CREME_CLAIR),
                              outline="", tags=("app_dyn", cx_t))
            croix = cv.create_line(983, y + 12, 993, y + 22, fill="#B9B0C8", width=2.4, capstyle="round", tags=("app_dyn", cx_t))
            croix2 = cv.create_line(993, y + 12, 983, y + 22, fill="#B9B0C8", width=2.4, capstyle="round", tags=("app_dyn", cx_t))
            cv.tag_bind(cx_t, "<Enter>", lambda e, a_=croix, b_=croix2: (cv.itemconfigure(a_, fill=ERREUR), cv.itemconfigure(b_, fill=ERREUR), self._curseur("pointinghand")))
            cv.tag_bind(cx_t, "<Leave>", lambda e, a_=croix, b_=croix2: (cv.itemconfigure(a_, fill="#B9B0C8"), cv.itemconfigure(b_, fill="#B9B0C8"), self._curseur("")))
            cv.tag_bind(cx_t, "<ButtonRelease-1>", lambda e, k=a["cle"]: self.after(1, lambda: self.app_oublier_un(k)))
            valeurs = (noms.get(a["cle"], "") or a.get("nom", "") or "—", a["ip"], a.get("mac", "") or "—", fab_aff(a.get("fab", "")) or "—",
                       a.get("note", ""))
            for (cle, x), v in zip(self.COLONNES, valeurs):
                x_ = x + (6 if cle == "nom" else 0)
                police = (F_TEXTE, 17) if cle in ("nom", "note") else (F_SAISIE, 15)
                maxw = {"nom": 215, "IP": 118, "MAC": 150, "fab": 185, "note": 172}[cle]
                tx, coupe = self.texte_fixe(x_, y + 17, v, police[0], police[1], maxw, anchor="w",
                                            fill=ENCRE, tags=("app_dyn", tag))
                if coupe:                                     # nom coupé par « … » : la bulle montre le texte en entier
                    self.nom_complet_bulle(tx, v)
            cv.tag_bind(tag, "<Button-1>", lambda e, k=a["cle"]: self.app_clic(e, k))
            cv.tag_bind(tag, "<Double-Button-1>", lambda e, k=a["cle"], y_=y: self.app_double_clic(e, k, y_))
            self.lier_clic_droit(tag, a["cle"])
            if a["cle"] in self.suivi:
                self.suivi_pastille(74, y + 9, ("app_dyn", tag))
            if a["cle"] in self.epingles():                 # en dernier : par-dessus la petite croix
                self.vignette_epingle(1010, y + 1, ("app_dyn", tag))
            cv.tag_bind(tag, "<Enter>", lambda e: self._curseur("pointinghand"))
            cv.tag_bind(tag, "<Leave>", lambda e: self._curseur(""))
        if len(liste) > N:
            cv.create_text(540, 775, text=f"{d['app_scroll'] + 1}–{min(len(liste), d['app_scroll'] + N)} / {len(liste)}",
                           font=(F_SAISIE, 13), fill=GRIS_TEXTE, tags=("app_dyn",))
        self.barre_defil("app", 1031, 292, 770, len(liste), N, d["app_scroll"], self.app_aller)
        self.menu_remonter()
        yb = self.centre_barre(30, 150, 1050, 845, -0.2, 1030)
        cv.create_text(1030, yb - 1.2, text=t("app_compte", n=len(liste), m=en_ligne), anchor="e",
                       font=(F_TITRE, 18), fill=CLAIR, tags=("app_dyn",))
        self.app_epingle_maj()


    def app_clic(self, e, cle):
        """Sélection comme dans le Finder : clic = un seul ; Maj-clic = de l'ancre jusqu'ici ; Cmd-clic = ajoute/retire."""
        d = self.mon_data
        etat = getattr(e, "state", 0) if e is not None else 0
        maj, cmd = bool(etat & 0x1), bool(etat & 0x8 or etat & 0x4)
        ordre = [a["cle"] for a in self.app_lignes()]
        ens = set(d.get("app_set", set()))
        if maj and d.get("app_ancre") in ordre:
            i1, i2 = sorted((ordre.index(d["app_ancre"]), ordre.index(cle)))
            plage = set(ordre[i1:i2 + 1])
            ens = (ens | plage) if cmd else plage
        elif cmd:
            ens.symmetric_difference_update({cle})
            d["app_ancre"] = cle
        else:
            if ens == {cle} and d.get("app_sel") == cle:
                return
            ens = {cle}
            d["app_ancre"] = cle
        d["app_set"], d["app_sel"] = ens, cle
        self.jouer("clic")
        self.app_dessiner_dyn()
        self.ip_dialog_suivre()

    def ip_dialog_suivre(self):
        """La fenêtre « Changer l'IP » (si elle est ouverte) suit l'appareil que l'on vient de sélectionner dans la liste."""
        f_ = getattr(self, "_fen_ip", None)
        if f_ is None:
            return
        try:
            if not f_.winfo_exists():
                self._fen_ip = None
                return
            ens = self.mon_data.get("app_set") or set()
            if len(ens) == 1:
                f_._suivre(next(iter(ens)))
        except tk.TclError:
            self._fen_ip = None

    def app_clavier(self, delta, maj=False):
        """Flèches haut/bas (avec Maj pour étendre) comme dans le Finder."""
        if self.onglet != "appareils" or getattr(self, "_edit", None):
            return None
        try:
            w = self.focus_get()
            if w is not None and w.winfo_class() == "Entry":      # on tape dans la recherche : les flèches restent au champ
                return None
        except Exception:
            journal_exc()
        d = self.mon_data
        ordre = [a["cle"] for a in self.app_lignes()]
        if not ordre:
            return "break"
        i = ordre.index(d["app_sel"]) if d.get("app_sel") in ordre else 0
        j = max(0, min(len(ordre) - 1, i + delta))
        if maj and d.get("app_ancre") in ordre:
            i1, i2 = sorted((ordre.index(d["app_ancre"]), j))
            d["app_set"] = set(ordre[i1:i2 + 1])
        else:
            d["app_set"] = {ordre[j]}
            d["app_ancre"] = ordre[j]
        d["app_sel"] = ordre[j]
        N = 13
        if j < d.get("app_scroll", 0):
            d["app_scroll"] = j
        elif j >= d.get("app_scroll", 0) + N:
            d["app_scroll"] = j - N + 1
        self.app_dessiner_dyn()
        self.ip_dialog_suivre()
        return "break"

    def app_tout(self):
        if self.onglet != "appareils" or getattr(self, "_edit", None):
            return None
        d = self.mon_data
        d["app_set"] = {a["cle"] for a in self.app_lignes()}
        self.app_dessiner_dyn()
        return "break"

    # ===== clic droit sur un appareil : menu en bulle de BD (identique dans Appareils et Monitor) =====
    def nom_appareil_cle(self, cle):
        d = self.mon_data
        a = d["app"].get(cle) or {}
        i = self.inv.get(cle) or {}
        return noms_memorises().get(cle) or a.get("nom") or i.get("nom") or ""

    def ip_appareil_cle(self, cle):
        return (self.mon_data["app"].get(cle) or {}).get("ip") or (self.inv.get(cle) or {}).get("ip") or ""

    def mac_appareil_cle(self, cle):
        return (self.mon_data["app"].get(cle) or {}).get("mac") or (self.inv.get(cle) or {}).get("mac") or ""

    def lier_clic_droit(self, tag, cle):
        for seq in ("<Button-2>", "<Button-3>", "<Control-Button-1>"):
            self.cv.tag_bind(tag, seq, lambda e, k=cle: self.menu_ouvrir(e, k))

    def entrees_menu(self, cle):
        """Les mêmes entrées partout. None = trait de séparation."""
        suivi = cle in self.suivi
        return [(t("menu_copier_ip"), lambda: self.copier_champ(cle, "ip"), bool(self.ip_appareil_cle(cle))),
                (t("menu_copier_mac"), lambda: self.copier_champ(cle, "mac"), bool(self.mac_appareil_cle(cle))),
                None,
                (t("menu_web"), lambda: self.ouvrir_web(cle), bool(self.ip_appareil_cle(cle))),
                (t("menu_port"), lambda: self.tester_port_dialogue(cle), bool(self.ip_appareil_cle(cle))),
                (t("menu_artnet"), lambda: self.artnet_changer_ip(cle), bool(self.ip_appareil_cle(cle))),
                None,
                (t("menu_identifier"), lambda: self.identifier(cle), bool(self.ip_appareil_cle(cle)))]

    def menu_fermer(self, *_):
        self._menu = None
        self.survol_oublier("mnu_")
        try:
            self.cv.delete("menu_bd")
        except Exception:
            journal_exc()
        if getattr(self, "_histo_masque", None):           # les vrais champs de saisie reprennent leur place
            for fen_ in self._histo_masque:
                try:
                    self.cv.itemconfigure(fen_, state="normal")
                except Exception:
                    journal_exc()
            self._histo_masque = []

    def menu_remonter(self):
        if self._menu:
            self.cv.tag_raise("menu_bd")
        self.cv.tag_raise("menu_cartes")
        self.cv.tag_raise("bulle_nom")
        self.cv.tag_raise("bulle_aide")

    def texte_fixe(self, x, y, texte, police, taille, maxw, **kw):
        """Texte à taille de police FIXE : s'il est trop long pour `maxw`, il est coupé et fini par « … ».
        Renvoie (identifiant du texte, coupé ?)."""
        cv = self.cv
        it = cv.create_text(x, y, text=texte, font=(police, taille), **kw)
        bb = cv.bbox(it)
        if not bb or bb[2] - bb[0] <= maxw:
            return it, False
        bas, haut = 1, len(texte)
        while bas < haut:
            mil = (bas + haut + 1) // 2
            cv.itemconfigure(it, text=texte[:mil].rstrip() + "…")
            b2 = cv.bbox(it)
            if b2 and b2[2] - b2[0] <= maxw:
                bas = mil
            else:
                haut = mil - 1
        cv.itemconfigure(it, text=texte[:bas].rstrip() + "…")
        return it, True

    def tronque_px(self, texte, police, taille, maxw):
        """Texte raccourci par « … » pour tenir dans `maxw` (sans toucher à la taille de la police)."""
        cv = self.cv
        it = cv.create_text(-500, -500, text=texte, font=(police, taille))
        try:
            bb = cv.bbox(it)
            if not bb or bb[2] - bb[0] <= maxw:
                return texte
            bas, haut = 1, len(texte)
            while bas < haut:
                mil = (bas + haut + 1) // 2
                cv.itemconfigure(it, text=texte[:mil].rstrip() + "…")
                b2 = cv.bbox(it)
                if b2 and b2[2] - b2[0] <= maxw:
                    bas = mil
                else:
                    haut = mil - 1
            return texte[:bas].rstrip() + "…"
        finally:
            cv.delete(it)

    def nom_complet_bulle(self, item, texte, centre=False):
        """Garde le pointeur sur un nom coupé : une petite bulle de BD montre le nom en entier.
        `centre` : petit élément rond (pastille) — la queue de la bulle part du milieu de l'élément."""
        cv = self.cv
        cv.tag_bind(item, "<Enter>", lambda e: self.bulle_nom(item, texte, centre), add="+")
        cv.tag_bind(item, "<Leave>", lambda e: self.bulle_nom_fermer(), add="+")

    def bulle_nom_fermer(self):
        att = self.__dict__.get("_bn_att")
        if att is not None:
            try:
                self.after_cancel(att)
            except Exception:
                journal_exc()
            self._bn_att = None
        gd = self.__dict__.get("_bn_garde")
        if gd is not None:
            try:
                self.after_cancel(gd)
            except Exception:
                journal_exc()
            self._bn_garde = None
        self.cv.delete("bulle_nom")

    def _bn_pointeur_sur(self, item):
        """Le pointeur est-il encore sur cet élément (qui existe toujours) ? Quand la liste défile ou se redessine, l'élément
        est remplacé et Tk n'envoie jamais « la souris quitte » : sans ce contrôle la bulle restait affichée."""
        cv = self.cv
        try:
            if not cv.type(item):
                return False
            bb = cv.bbox(item)
            px = cv.winfo_pointerx() - cv.winfo_rootx()
            py = cv.winfo_pointery() - cv.winfo_rooty()
            lx, ly = cv.vers_logique(px, py)
            return bool(bb) and bb[0] - 3 <= lx <= bb[2] + 3 and bb[1] - 3 <= ly <= bb[3] + 3
        except Exception:  # noqa: BLE001
            return False

    def _bn_surveiller(self, item):
        self._bn_garde = None
        if not cv_existe(self.cv, "bulle_nom"):
            return
        if not self._bn_pointeur_sur(item):
            self.bulle_nom_fermer()
            return
        self._bn_garde = self.after(120, lambda: self._bn_surveiller(item))

    def bulle_nom(self, item, texte, centre=False):
        self.bulle_nom_fermer()
        cv = self.cv
        bb = cv.bbox(item)
        if not bb:
            return

        def montrer():
            self._bn_att = None
            if not self._bn_pointeur_sur(item):               # la liste a bougé pendant l'attente : plus rien à montrer
                return
            tag = ("bulle_nom",)
            mesure = cv.create_text(-2000, -2000, text=texte, font=(F_TEXTE, 18))
            mb = cv.bbox(mesure)
            cv.delete(mesure)
            L = max(80, int((mb[2] - mb[0]) + 36)) if mb else 200
            H = 40
            if centre:                                    # la queue part du milieu de la pastille, la bulle est calée dessus
                cx_ = (bb[0] + bb[2]) / 2
                bx1 = max(36, min(cx_ - 40, 1100 - L))
            else:
                bx1 = max(36, min(bb[0] - 8, 1100 - L))
            bx2 = bx1 + L
            by2 = bb[1] - 10
            by1 = by2 - H
            # la queue a la forme de celle des bulles d'aide (« ? », Radar, Switch, Changer l'IP) : large base, pointe vers le nom
            ax = min(max(cx_, bx1 + 18), bx2 - 18) if centre else max(bb[0] + 30, bx1 + 38)
            if by1 < 4:                                   # pas de place au-dessus : la bulle passe en dessous
                by1 = bb[3] + 10
                by2 = by1 + H
                queue_ = [ax - 12, by1 + 3, ax, bb[3] + 1, ax + 9, by1 + 3]
                trait = by1 + 1.5
            else:
                queue_ = [ax - 12, by2 - 3, ax, bb[1] - 1, ax + 9, by2 - 3]
                trait = by2 - 1.5
            cv.create_polygon(contour(bx1 + 5, by1 + 6, bx2 + 5, by2 + 6, 14, 511, 1.0, 60), smooth=True, fill=NOIR,
                              outline=NOIR, width=3, tags=tag)
            cv.create_polygon(contour(bx1, by1, bx2, by2, 14, 512, 1.4, 60), smooth=True, fill=BULLE_FOND, outline=NOIR,
                              width=3, joinstyle="round", tags=tag)
            tracer_queue_bd(cv, queue_, tag)
            cv.create_text((bx1 + bx2) / 2, (by1 + by2) / 2 + 1, text=texte, font=(F_TEXTE, 18), fill=BULLE_TEXTE,
                           tags=tag)
            self._bn_garde = self.after(120, lambda: self._bn_surveiller(item))
        self._bn_att = self.after(450, montrer)

    def menu_ouvrir(self, e, cle):
        """Bulle de BD avec les actions, dont la queue pointe sur l'endroit du clic droit."""
        self.menu_fermer()
        self.survol_oublier("mnu_")
        if self.onglet == "appareils":
            d = self.mon_data
            if cle not in d.get("app_set", set()):
                d["app_set"], d["app_sel"], d["app_ancre"] = {cle}, cle, cle
                self.app_dessiner_dyn()
        elif self.onglet == "monitoring":
            self.mon_data["sel"] = cle
            self.mon_maj(True)
        cv = self.cv
        px, py = cv.vers_logique(e.x, e.y)
        entrees = self.entrees_menu(cle)
        L, H_ENT, H_SEP = 262, 28, 10
        nom = self.nom_appareil_cle(cle)
        ip = self.ip_appareil_cle(cle)
        titre = f"{nom}  {ip}" if nom else ip
        H = 36 + sum(H_SEP if x is None else H_ENT for x in entrees) + 8
        # la bulle se place à droite et en dessous du clic, ou de l'autre côté si elle sort de la fenêtre
        bx1 = px + 26 if px + 26 + L < 1110 else px - 26 - L
        haut = py + 18 + H < 850
        by1 = py + 18 if haut else py - 18 - H
        bx2, by2 = bx1 + L, by1 + H
        tag = ("menu_bd",)
        cv.create_polygon(contour(bx1 + 5, by1 + 6, bx2 + 5, by2 + 6, 18, 601, 1.2, 80), smooth=True, fill=NOIR,
                          outline=NOIR, width=3, tags=tag)
        if bx1 > px:
            base = [bx1 + 2, by1 + (22 if haut else H - 22), bx1 + 2, by1 + (44 if haut else H - 44)]
        else:
            base = [bx2 - 2, by1 + (22 if haut else H - 22), bx2 - 2, by1 + (44 if haut else H - 44)]
        queue_ = [base[0], base[1], px, py, base[2], base[3]]
        cv.create_polygon([q + (6 if i % 2 == 0 else 7) for i, q in enumerate(queue_)], fill=NOIR, outline=NOIR,
                          width=3, joinstyle="round", tags=tag)
        cv.create_polygon(contour(bx1, by1, bx2, by2, 18, 602, 1.8, 80), smooth=True, fill=BULLE_FOND, outline=NOIR,
                          width=3, joinstyle="round", tags=tag)
        cv.create_polygon(queue_, fill=BULLE_FOND, outline=NOIR, width=3, joinstyle="round", tags=tag)
        cv.create_line([base[0] + (1.5 if bx1 > px else -1.5), base[1] + 2, base[2] + (1.5 if bx1 > px else -1.5), base[3] - 2],
                       fill=BULLE_FOND, width=5, tags=tag)
        tt = cv.create_text(bx1 + 20, by1 + 20, text=titre, anchor="w", font=(F_TITRE, 14), fill=VIOLET, tags=tag)
        self.ajuster(tt, F_TITRE, 14, L - 40)
        y = by1 + 36
        for k, x in enumerate(entrees):
            if x is None:
                cv.create_line(bx1 + 18, y + H_SEP / 2, bx2 - 18, y + H_SEP / 2, fill="#CFC3E6", width=1.6, tags=tag)
                y += H_SEP
                continue
            libelle, action, actif = x
            etiq = f"mnu_{k}"
            fond = cv.create_polygon(contour(bx1 + 10, y + 1, bx2 - 10, y + H_ENT - 1, 7, 610 + k, 0.5, 60), smooth=True,
                                     fill=BULLE_FOND, outline="", tags=tag + (etiq,))
            marque = cle in self.suivi and libelle == t("menu_suivre_stop")
            txt = cv.create_text(bx1 + 24, y + H_ENT / 2, text=libelle, anchor="w", font=(F_TEXTE, 15),
                                 fill=BULLE_TEXTE if actif else GRIS_TEXTE, tags=tag + (etiq,))
            self.ajuster(txt, F_TEXTE, 15, L - 56)
            if marque:
                cv.create_oval(bx2 - 28, y + H_ENT / 2 - 5, bx2 - 18, y + H_ENT / 2 + 5, fill=ROSE, outline=NOIR,
                               width=2, tags=tag + (etiq,))
            if actif:
                def appliquer(v, f=fond):
                    cv.itemconfigure(f, fill=LILAS_PALE if v else BULLE_FOND)
                    self._curseur("pointinghand" if v else "")
                cv.tag_bind(etiq, "<Enter>", lambda e, k_=etiq, f=appliquer: self._survol_lisse(k_, True, f))
                cv.tag_bind(etiq, "<Leave>", lambda e, k_=etiq, f=appliquer: self._survol_lisse(k_, False, f))
                cv.tag_bind(etiq, "<Button-1>", lambda e, a_=action: self._menu_choisir(a_))
            y += H_ENT
        self._menu = {"cle": cle}
        # un champ de texte Tk passe toujours devant le dessin : on le cache tant que la bulle le recouvre
        cachees = []
        for fen_, (rx1, ry1, rx2, ry2) in list(getattr(self, "_fen_masq", [])):
            if bx1 < rx2 and bx2 > rx1 and by1 < ry2 and by2 > ry1:
                try:
                    cv.itemconfigure(fen_, state="hidden")
                    cachees.append(fen_)
                except Exception:
                    journal_exc()
        self._histo_masque = cachees

    def _menu_hors(self, e):
        if not self._menu:
            return
        marques = self.cv.gettags("current") if self.cv.find_withtag("current") else ()
        if "menu_bd" not in marques:
            self.after(1, self.menu_fermer)

    def _menu_choisir(self, action):
        self.menu_fermer()
        self._curseur("")
        self.jouer("pop")
        self.after(1, action)

    # ----- les actions du menu -----
    def copier_champ(self, cle, champ):
        v = self.ip_appareil_cle(cle) if champ == "ip" else self.mac_appareil_cle(cle)
        if not v:
            return
        try:
            self.clipboard_clear()
            self.clipboard_append(v)
            self.update()
        except Exception:
            journal_exc()
        self.set_bulle("bulle_copie", quoi=t("copie_ip" if champ == "ip" else "copie_mac"), v=v)

    def ouvrir_web(self, cle):
        ip = self.ip_appareil_cle(cle)
        if ip:
            try:
                subprocess.Popen(["open", f"http://{ip}"])
            except OSError:
                pass

    def _ip_libre_proche(self, ip):
        """(adresse libre la plus proche après `ip`, masque) d'après l'inventaire et le dernier balayage."""
        try:
            res = ipaddress.IPv4Network(str((getattr(self, "dernier_scan", None) or {}).get("reseau") or f"{ip}/24"), strict=False)
            if ipaddress.IPv4Address(ip) not in res:
                res = ipaddress.IPv4Network(f"{ip}/24", strict=False)
        except ValueError:
            return "", "255.255.255.0"
        pris = {a.get("ip") for a in self.inv.values()} | {a.get("ip") for a in self.mon_data["app"].values()}
        pris |= {self.mon_data.get("ip"), ip}
        hotes = list(res.hosts())
        try:
            depart = hotes.index(ipaddress.IPv4Address(ip))
        except ValueError:
            depart = 0
        for k in range(1, len(hotes) + 1):
            c = str(hotes[(depart + k) % len(hotes)])
            if c not in pris:
                return c, str(res.netmask)
        return "", str(res.netmask)



    def changer_ip_selection(self):
        """Bouton « Changer l'IP » de l'onglet Appareils : agit sur l'appareil sélectionné dans la liste."""
        d = self.mon_data
        ens = d.get("app_set") or set()
        if len(ens) != 1:
            return
        self.artnet_changer_ip(next(iter(ens)))

    def ips_suivies(self):
        """Nouvelles adresses d'appareils qu'on vient de changer : testées aux prochains scans (15 minutes), même hors du réseau."""
        d = self.__dict__.setdefault("_ips_suivies", {})
        maintenant = time.time()
        for a in [a for a, (_, fin) in d.items() if fin < maintenant]:
            d.pop(a, None)
        return [(a, nom) for a, (nom, _) in d.items()]

    def apres_changement_ip(self, cle, nouvelle_ip="", nom="", delai=1500):
        """Juste après un changement d'adresse : l'ancienne adresse n'est plus « en ligne », on suit la nouvelle,
        et on relance un scan pour retrouver l'appareil."""
        self.mon_data["app"].pop(cle, None)
        if nouvelle_ip:
            self.__dict__.setdefault("_ips_suivies", {})[nouvelle_ip] = (nom, time.time() + 900)
        try:
            if self.onglet == "appareils":
                self.app_dessiner_dyn()
        except Exception:  # noqa: BLE001
            journal_exc()
        self.after(delai, self.scan_maintenant)

    def artnet_changer_ip(self, cle):
        """Fenêtre « Changer l'IP » d'un appareil dont le protocole est ouvert (Art-Net, CODA, Shure ULX-D)."""
        ouverte = getattr(self, "_fen_ip", None)
        if ouverte is not None:                       # la fenêtre est déjà ouverte : elle passe simplement sur cet appareil
            try:
                if ouverte.winfo_exists():
                    ouverte._suivre(cle)
                    ouverte.deiconify()
                    ouverte.lift()
                    return
            except tk.TclError:
                pass
            self._fen_ip = None
        ip = self.ip_appareil_cle(cle)
        if not ip:
            return
        nom = self.nom_appareil_cle(cle) or ip
        device = self.mon_data.get("device") or ""
        try:
            fen, corps = _fenetre_base(self, t("an_titre"), 640, 660)
        except Exception as e:  # noqa: BLE001
            print("fenêtre changer l'IP :", repr(e), file=sys.stderr)
            return
        self._fen_ip = fen
        pos_ = lire_reglages().get("pos_fen_ip")            # la fenêtre se rouvre là où tu l'avais laissée
        try:
            if pos_ and 0 <= int(pos_[0]) <= self.winfo_screenwidth() - 120 and 0 <= int(pos_[1]) <= self.winfo_screenheight() - 120:
                fen.geometry(f"+{int(pos_[0])}+{int(pos_[1])}")
            else:                       # première ouverture : à droite, pour laisser voir le début de la liste (noms, IP)
                px_ = max(0, min(self.winfo_rootx() + self.winfo_width() - 650, self.winfo_screenwidth() - 660))
                fen.geometry(f"+{px_}+{self.winfo_rooty() + 40}")
        except Exception:  # noqa: BLE001
            journal_exc()

        def fermer_fen():
            try:
                sauver_reglage(pos_fen_ip=[fen.winfo_x(), fen.winfo_y()])
            except Exception:  # noqa: BLE001
                journal_exc()
            self._fen_ip = None
            try:
                fen.destroy()
            except tk.TclError:
                pass
        fen.protocol("WM_DELETE_WINDOW", fermer_fen)
        propose, masque0 = self._ip_libre_proche(ip)
        fond_c = "#FFFFFF" if not NUIT else CREME_CLAIR
        mac_brut = re.sub(r"[^0-9A-Fa-f]", "", str(self.inv.get(cle, {}).get("mac", "")))
        mac_txt = ":".join(mac_brut[i:i + 2] for i in range(0, 12, 2)).upper() if len(mac_brut) == 12 else ""
        v_app = self.mon_data["app"].get(cle)
        en_ligne = bool(v_app) and not v_app.get("perdu")
        carte_ = tk.Frame(corps, bg=CREME_CLAIR, highlightthickness=3, highlightbackground=NOIR)
        carte_.pack(fill="x", pady=(0, 12))
        lab_nom = tk.Label(carte_, text=nom, bg=CREME_CLAIR, fg=VIOLET, font=(F_TITRE, 19), anchor="w")
        lab_nom.pack(anchor="w", padx=12, pady=(8, 0))
        lab_mac = tk.Label(carte_, text=t("an_mac", mac=mac_txt) if mac_txt else "", bg=CREME_CLAIR, fg=GRIS_TEXTE,
                           font=(F_SAISIE, 14), anchor="w")
        lab_etat = tk.Label(carte_, text="●  " + t("an_en_ligne" if en_ligne else "an_hors_ligne"), bg=CREME_CLAIR,
                            fg=VERT_OK if en_ligne else GRIS_TEXTE, font=(F_TEXTE, 14), anchor="w")
        if mac_txt:
            lab_mac.pack(anchor="w", padx=12)
        lab_etat.pack(anchor="w", padx=12, pady=(0, 8))
        v_ip, v_m = tk.StringVar(value=propose), tk.StringVar(value=masque0)
        mode = {"v": "manuel"}
        tk.Label(corps, text=t("l_mode"), bg=CREME, fg=ENCRE, font=(F_TEXTE, 16), anchor="w").pack(anchor="w")
        rang_mode = tk.Frame(corps, bg=CREME)
        rang_mode.pack(anchor="w", pady=(2, 8))
        boutons_mode = {}
        entrees = []

        def maj_mode():
            for cle_, (coul_n, coul_s, coul_t) in (("manuel", (ROUGE, ROUGE_VIF, CLAIR) if mode["v"] == "manuel" else (CREME_CLAIR, SURVOL_CREME, ENCRE)),
                                                   ("dhcp", (ROUGE, ROUGE_VIF, CLAIR) if mode["v"] == "dhcp" else (CREME_CLAIR, SURVOL_CREME, ENCRE))):
                b_ = boutons_mode[cle_]
                b_.coul["n"], b_.coul["s"] = coul_n, coul_s
                b_.itemconfigure(b_.corps, fill=coul_n)
                b_.itemconfigure(b_.txt, fill=coul_t)
            for e_ in entrees:
                e_.configure(state="normal" if mode["v"] == "manuel" else "disabled",
                             bg=fond_c if mode["v"] == "manuel" else CREME_GRIS)

        def choisir_mode(m_):
            mode["v"] = m_
            maj_mode()
        for cle_, lib_, larg_ in (("manuel", t("ip_fixe"), 130), ("dhcp", t("dhcp_auto"), 130)):
            boutons_mode[cle_] = bouton_plat(rang_mode, lib_, CREME_CLAIR, SURVOL_CREME, ENCRE,
                                             lambda c_=cle_: choisir_mode(c_), largeur=larg_, hauteur=36)
            boutons_mode[cle_].pack(side="left", padx=(0, 8))
        v_ip_av, v_m_av = tk.StringVar(value=ip), tk.StringVar(value=masque0)      # valeurs actuelles de l'appareil
        masque_chips = []
        for libelle, var_av, var in ((t("l_ip"), v_ip_av, v_ip), (t("l_masque"), v_m_av, v_m)):
            tk.Label(corps, text=libelle, bg=CREME, fg=ENCRE, font=(F_TEXTE, 16), anchor="w").pack(anchor="w")
            rang_ = tk.Frame(corps, bg=CREME)
            rang_.pack(fill="x", pady=(2, 10))
            rang_.columnconfigure(0, weight=1, uniform="ch")
            rang_.columnconfigure(2, weight=1, uniform="ch")
            tk.Entry(rang_, textvariable=var_av, font=(F_SAISIE, 18), state="disabled", bg=LILAS_CLAIR,
                     disabledbackground=LILAS_CLAIR, disabledforeground=GRIS_TEXTE, relief="flat", highlightthickness=3,
                     highlightbackground=NOIR).grid(row=0, column=0, sticky="ew", ipady=4)
            tk.Label(rang_, text="→", bg=CREME, fg=ENCRE, font=(F_TITRE, 22)).grid(row=0, column=1, padx=10)
            e_ = tk.Entry(rang_, textvariable=var, font=(F_SAISIE, 18), bg=fond_c, fg=ENCRE, insertbackground=ENCRE,
                          disabledforeground=GRIS_TEXTE, relief="flat", highlightthickness=3, highlightbackground=NOIR,
                          highlightcolor=ROSE)
            e_.grid(row=0, column=2, sticky="ew", ipady=4)
            entrees.append(e_)
            if var is v_m:                                   # raccourcis de masque sous le champ « après »
                ch_ = tk.Frame(rang_, bg=CREME)
                ch_.grid(row=1, column=2, sticky="w", pady=(6, 0))
                for lib_m, val_m in (("/24", "255.255.255.0"), ("/16", "255.255.0.0"), ("/8", "255.0.0.0")):
                    b_m = bouton_plat(ch_, lib_m, CREME_CLAIR, SURVOL_CREME, ENCRE,
                                      lambda v_=val_m: (v_m.set(v_) if mode["v"] == "manuel" else None), largeur=58, hauteur=28)
                    b_m.pack(side="left", padx=(0, 6))
        maj_mode()
        v_st = tk.StringVar(value="")
        lab_st = EtiquetteSerree(corps, textvariable=v_st, bg=CREME, fg=ENCRE, font=(F_TEXTE, 15), anchor="nw", justify="left",
                          wraplength=540)
        lab_st.pack(anchor="w", fill="x", pady=(0, 6))
        rang = tk.Frame(corps, bg=CREME)
        rang.pack(side="bottom", pady=(6, 0))
        etat = {"occupe": False}

        def statut(texte, erreur=False):
            try:
                v_st.set(texte)
                lab_st.configure(fg=ERREUR if erreur else ENCRE)
            except tk.TclError:
                pass

        def en_fond(travail, suite):
            res = {}
            etat["occupe"] = True

            def t_():
                try:
                    res["r"] = travail()
                except Exception as e_:  # noqa: BLE001
                    res["r"] = None
                    print("changer l'IP :", repr(e_), file=sys.stderr)
                res["fini"] = True
            threading.Thread(target=t_, daemon=True).start()

            def attendre():
                if "fini" not in res:
                    try:
                        fen.after(120, attendre)
                    except tk.TclError:
                        pass
                    return
                etat["occupe"] = False
                try:
                    if fen.winfo_exists():
                        suite(res["r"])
                        if etat.get("attente") and not etat["occupe"]:      # l'appareil sélectionné a changé entre-temps
                            suivre(etat.pop("attente"))
                except tk.TclError:
                    pass
            fen.after(120, attendre)

        def decrire(proto, info):
            if proto == "artnet":
                return t("an_det_artnet", ip=info["ip"], m=info["masque"], dhcp=t("an_oui") if info["dhcp"] else t("an_non"))
            if proto == "coda":
                return t("an_det_coda", mod=info["modele"], mac=info["mac"])
            if proto == "lacoustics":
                return t("an_det_coda", mod=info.get("modele", "") + (" · " + info["nom"] if info.get("nom") else ""), mac=info["mac"])
            return t("an_det_shure", mode=info["mode"], ip=info["ip"], m=info["masque"])

        def verifier():
            if etat["occupe"]:
                return
            statut("")

            def suite(det):
                if not det:
                    statut(t("an_pas_reponse"), True)
                else:
                    statut("\n".join(t("an_reconnu", p=PROTO_IP_NOMS[p], d=decrire(p, det[p])) for p in det))
                    for p_ in det:
                        if det[p_].get("masque"):
                            v_m_av.set(str(det[p_]["masque"]))
                            break
                    p0 = next((p for p in ("artnet", "shure") if p in det), None)
                    if p0:                                             # le menu reprend le mode réel de l'appareil
                        auto = (str(det[p0].get("mode", "")).upper() == "AUTO") if p0 == "shure" else bool(det[p0].get("dhcp"))
                        choisir_mode("dhcp" if auto else "manuel")
            en_fond(lambda: detecter_protocoles_ip(ip), suite)

        def passer_dhcp():
            if etat["occupe"]:
                return
            statut("")

            def apres_prep(det):
                if not det:
                    statut(t("an_pas_reponse"), True)
                    return
                proto = next(p for p in ("artnet", "coda", "shure", "lacoustics") if p in det)
                info = det[proto]
                if proto in ("coda", "lacoustics"):
                    statut(t("an_dhcp_coda"), True)
                    return
                if (proto == "shure" and str(info.get("mode", "")).upper() == "AUTO") or (proto == "artnet" and info.get("dhcp")):
                    statut(t("an_dhcp_deja"))
                    return
                if not messagebox.askokcancel("IP Pilot", t("an_dhcp_confirm", nom=nom, p=PROTO_IP_NOMS[proto], a=ip), parent=fen):
                    statut("")
                    return
                statut("")

                def envoyer():
                    if proto == "artnet":
                        artnet_ipprog(ip, 0xC0, delai=2.0)         # 0x80 = programmation autorisée, 0x40 = DHCP
                        return True
                    return shure_net_auto(ip)

                def apres_envoi(ok):
                    if not ok:
                        statut(t("an_dhcp_ko"), True)
                        return
                    statut(t("an_dhcp_ok"))
                    noter_evenement("info", tk_("evt_an_dhcp", nom=nom, a=ip))
                    self.jouer("pop")
                    self.apres_changement_ip(cle, "", nom, delai=4000)
                en_fond(envoyer, apres_envoi)
            en_fond(lambda: detecter_protocoles_ip(ip), apres_prep)

        def valider():
            try:
                ni = ipaddress.IPv4Address(v_ip.get().strip())
                nm = ipaddress.IPv4Address(v_m.get().strip())
                ipaddress.IPv4Network(f"0.0.0.0/{nm}")            # lève ValueError si le masque n'est pas un vrai masque
                if ni.is_multicast or ni.is_unspecified or str(ni).endswith(".255"):
                    raise ValueError
            except ValueError:
                return None
            return str(ni), str(nm)

        def appliquer():
            if etat["occupe"]:
                return
            if mode["v"] == "dhcp":
                passer_dhcp()
                return
            v = valider()
            if v is None:
                statut(t("an_invalide"), True)
                return
            ni, nm = v
            if ni == ip:
                statut(t("an_meme"), True)
                return
            statut("")

            def preparer():
                return _ping_un(ni, device, 800), detecter_protocoles_ip(ip)

            def apres_prep(r):
                ping, det = r if r else (None, {})
                if ping is not None:
                    statut(t("an_deja_prise", ip=ni), True)
                    return
                if not det:
                    statut(t("an_pas_reponse"), True)
                    return
                proto = next(p for p in ("artnet", "coda", "shure", "lacoustics") if p in det)
                info = det[proto]
                avec_masque = proto not in ("coda", "lacoustics")
                if not messagebox.askokcancel("IP Pilot", t("an_confirm", nom=nom, p=PROTO_IP_NOMS[proto], a=ip, n=ni,
                                                            m=(f"  (masque {nm})" if avec_masque else "")), parent=fen):
                    statut("")
                    return
                statut("")

                def envoyer():
                    if proto == "artnet":
                        return artnet_ipprog(ip, ARTNET_IPPROG_CMD, ni, nm, delai=3.0)
                    if proto == "coda":
                        return coda_changeip(ip, ni, info["mac"])
                    if proto == "lacoustics":
                        return lac_changeip(ip, ni)
                    gw = info.get("gw", "0.0.0.0")
                    try:
                        if ipaddress.IPv4Address(gw) not in ipaddress.IPv4Network(f"{ni}/{nm}", strict=False):
                            gw = "0.0.0.0"
                    except ValueError:
                        gw = "0.0.0.0"
                    return shure_net_set(ip, ni, nm, gw)

                def apres_envoi(rr):
                    if rr is None:
                        statut(t("an_echec"))
                        self.apres_changement_ip(cle, ni, nom)        # il a peut-être changé quand même
                        return
                    statut(t("an_succes", ip=rr["ip"]))
                    noter_evenement("info", tk_("evt_an_ok", nom=nom, a=ip, n=rr["ip"]))
                    self.jouer("pop")
                    self.apres_changement_ip(cle, rr["ip"], nom)
                en_fond(envoyer, apres_envoi)
            en_fond(preparer, apres_prep)

        def suivre(nouvelle):
            """La fenêtre passe sur un autre appareil (sélectionné dans la liste) sans se fermer."""
            nonlocal cle, ip, nom
            if nouvelle == cle:
                return
            if etat["occupe"]:                                  # une opération est en cours : on attend sa fin
                etat["attente"] = nouvelle
                return
            ip2 = self.ip_appareil_cle(nouvelle)
            if not ip2:
                return
            cle, ip = nouvelle, ip2
            nom = self.nom_appareil_cle(nouvelle) or ip2
            prop, m0 = self._ip_libre_proche(ip2)
            brut = re.sub(r"[^0-9A-Fa-f]", "", str(self.inv.get(nouvelle, {}).get("mac", "")))
            mac2 = ":".join(brut[i:i + 2] for i in range(0, 12, 2)).upper() if len(brut) == 12 else ""
            v2 = self.mon_data["app"].get(nouvelle)
            ok2 = bool(v2) and not v2.get("perdu")
            lab_nom.configure(text=nom)
            lab_mac.pack_forget()
            lab_mac.configure(text="")
            if mac2:
                lab_mac.configure(text=t("an_mac", mac=mac2))
                lab_mac.pack(anchor="w", padx=12, before=lab_etat)
            lab_etat.configure(text="●  " + t("an_en_ligne" if ok2 else "an_hors_ligne"),
                               fg=VERT_OK if ok2 else GRIS_TEXTE)
            v_ip.set(prop)
            v_m.set(m0)
            v_ip_av.set(ip2)
            v_m_av.set(m0)
            choisir_mode("manuel")
            statut("")
        fen._suivre = suivre
        for libelle, coul, surv, ctexte, action in ((t("an_fermer"), CREME_CLAIR, SURVOL_CREME, ENCRE, fermer_fen),
                                                    (t("an_verifier"), LILAS_CLAIR, LILAS_PALE, ENCRE, verifier),
                                                    (t("an_appliquer"), ROUGE_VIF, ROUGE_CLAIR, CLAIR, appliquer)):
            b_fin = bouton_plat(rang, libelle, coul, surv, ctexte, action, largeur=130, hauteur=40)
            b_fin.pack(side="left", padx=6)
            if action is verifier:                       # bulle d'aide quand la souris reste sur « Vérifier »
                bulle_v = {"att": None, "w": None}

                def montrer_v(b_=b_fin):
                    bulle_v["att"] = None
                    try:
                        texte_ = t("an_expl")
                        Lb = 580
                        c_ = ToileFenetre(tk.Canvas(fen, width=Lb + 12, height=10, bg=CREME, highlightthickness=0, bd=0))
                        c_.regler(1, 0, 0)
                        mes = c_.create_text(-2000, -2000, text=texte_, font=(F_TEXTE, 13), width=Lb - 36, anchor="nw")
                        mb = c_.bbox(mes)
                        c_.delete(mes)
                        Hb = int((mb[3] - mb[1]) + 22) if mb else 52
                        c_.configure(height=Hb + 26)
                        bx = b_.winfo_rootx() - fen.winfo_rootx() + b_.winfo_width() / 2     # centre du bouton « Vérifier »
                        x0 = max(8, min(bx - Lb / 2, fen.winfo_width() - Lb - 24))
                        cx_q = bx - x0 + 2                                                     # position de la queue dans la bulle
                        cx_q = max(30, min(cx_q, Lb - 30))
                        c_.create_polygon(contour(7, 7, Lb + 5, Hb + 5, 14, 611, 1.0, 60), smooth=True, fill=NOIR, outline=NOIR, width=3)
                        q_ = [cx_q - 14, Hb - 3, cx_q + 2, Hb + 18, cx_q + 14, Hb - 3]
                        c_.create_polygon([v + (5 if k % 2 == 0 else 6) for k, v in enumerate(q_)], fill=NOIR, outline=NOIR, width=3,
                                          joinstyle="round")
                        c_.create_polygon(contour(2, 2, Lb, Hb, 14, 612, 1.4, 60), smooth=True, fill=BULLE_FOND, outline=NOIR,
                                          width=3, joinstyle="round")
                        c_.create_polygon(q_, fill=BULLE_FOND, outline=NOIR, width=3, joinstyle="round")
                        c_.create_line(q_[0] + 3, Hb - 1.5, q_[4] - 3, Hb - 1.5, fill=BULLE_FOND, width=5)
                        c_.create_text(18, Hb / 2 + 1, text=texte_, anchor="w", font=(F_TEXTE, 13), fill=BULLE_TEXTE, width=Lb - 36)
                        y_ = b_.winfo_rooty() - fen.winfo_rooty() - (Hb + 26) - 2
                        c_.place(x=x0, y=max(8, y_))
                        bulle_v["w"] = c_
                    except tk.TclError:
                        pass

                def cacher_v():
                    if bulle_v["att"]:
                        try:
                            fen.after_cancel(bulle_v["att"])
                        except Exception:  # noqa: BLE001
                            journal_exc()
                        bulle_v["att"] = None
                    if bulle_v["w"]:
                        try:
                            bulle_v["w"].destroy()
                        except tk.TclError:
                            pass
                        bulle_v["w"] = None
                b_fin.bind("<Enter>", lambda e: bulle_v.update(att=fen.after(600, montrer_v)), add="+")
                b_fin.bind("<Leave>", lambda e: cacher_v(), add="+")
                b_fin.bind("<ButtonPress-1>", lambda e: cacher_v(), add="+")

    def tester_port_dialogue(self, cle):
        from tkinter import simpledialog
        ip = self.ip_appareil_cle(cle)
        if not ip:
            return
        rep_ = simpledialog.askstring("IP Pilot", t("port_q", ip=ip), initialvalue=str(self.mon_data.get("dernier_port", 80)),
                                      parent=self)
        if rep_ is None:
            return
        try:
            port = int(rep_.strip())
            if not 1 <= port <= 65535:
                raise ValueError
        except ValueError:
            messagebox.showwarning("IP Pilot", t("port_invalide"), parent=self)
            return
        self.mon_data["dernier_port"] = port
        nom = self.nom_appareil_cle(cle) or ip
        res = {}

        def travail():
            res["r"] = tester_port(ip, port)
        threading.Thread(target=travail, daemon=True).start()

        def attendre():
            if "r" not in res:
                self.after(150, attendre)
                return
            cle_t = {"ouvert": "port_ouvert", "ferme": "port_ferme", "muet": "port_muet"}[res["r"]]
            msg = tk_(cle_t, port=port, nom=nom, ip=ip)
            noter_evenement("info" if res["r"] == "ouvert" else "avert", msg)
            messagebox.showinfo("IP Pilot", str(msg), parent=self)
        self.after(150, attendre)

    # ----- surveillance continue d'un appareil (ping chaque seconde, coupures notées) -----
    def suivi_confirmer(self, nom, ip):
        """Explique la surveillance continue avant de l'activer ; on peut choisir de ne plus afficher ce message."""
        if lire_reglages().get("suivi_sans_message"):
            return True
        texte = t("suivi_explication", nom=nom, ip=ip)
        try:
            fen, corps = _fenetre_base(self, t("suivi_titre"), 520, 440)
            res, var = [False], tk.BooleanVar(value=False)
            EtiquetteSerree(corps, text=texte, bg=CREME, fg=ENCRE, font=(F_SAISIE, 15), justify="left", wraplength=470,
                     anchor="w").pack(anchor="w")
            tk.Checkbutton(corps, text=t("suivi_ne_plus"), variable=var, bg=CREME, activebackground=CREME, fg=VIOLET,
                           font=(F_TEXTE, 15), highlightthickness=0, bd=0).pack(anchor="w", pady=(12, 6))
            rang = tk.Frame(corps, bg=CREME)
            rang.pack(side="bottom", pady=(6, 0))

            def fin(ok):
                res[0] = ok
                if ok and var.get():
                    sauver_reglage(suivi_sans_message=True)
                try:
                    fen.destroy()
                except Exception:
                    journal_exc()
            for libelle, fond, ok in ((t("suivi_annuler"), CREME_GRIS, False), (t("suivi_activer"), ROUGE, True)):
                b = tk.Label(rang, text=libelle, bg=fond, fg=CLAIR if ok else ENCRE, font=(F_TEXTE, 17), padx=22, pady=5,
                             highlightthickness=3, highlightbackground=NOIR, cursor="pointinghand")
                b.bind("<ButtonRelease-1>", lambda e, o=ok: fin(o))
                b.pack(side="left", padx=8)
            fen.protocol("WM_DELETE_WINDOW", lambda: fin(False))
            try:
                fen.grab_set()
            except Exception:
                journal_exc()
            self.wait_window(fen)
            return res[0]
        except Exception as e:  # noqa: BLE001
            print("fenêtre surveillance :", repr(e), file=sys.stderr)
            return messagebox.askokcancel("IP Pilot", texte, parent=self)

    def suivi_basculer(self, cle):
        ip = self.ip_appareil_cle(cle)
        nom = self.nom_appareil_cle(cle) or ip
        s_ = self.suivi.get(cle)
        if s_:
            s_["stop"].set()
            noter_evenement("info", tk_("evt_suivi_fin", nom=nom, ip=ip, n=len(s_["pertes"])))
            del self.suivi[cle]
        else:
            if not self.suivi_confirmer(nom, ip):
                return
            stop = threading.Event()
            device = self.mon_data.get("device") or ""
            self.suivi[cle] = {"stop": stop, "pts": deque(maxlen=7200), "pertes": [], "perte_t0": None,
                               "ip": ip, "nom": nom, "depuis": time.time()}
            noter_evenement("info", tk_("evt_suivi_debut", nom=nom, ip=ip))

            def boucle():
                while not stop.is_set():
                    t0 = time.time()
                    ms = _ping_un(ip, device)
                    if stop.is_set():
                        break
                    self.file_suivi.put((cle, time.time(), ms))
                    stop.wait(max(0.02, 0.5 - (time.time() - t0)))
            threading.Thread(target=boucle, daemon=True).start()
        self.mon_data["gr_apps"] = None            # (dé)cocher un appareil : les courbes le suivent automatiquement
        self.jouer("pop")
        if self.onglet == "appareils":
            self.app_dessiner_dyn()
        elif self.onglet == "monitoring":
            self.mon_maj(True)

    def suivi_poll(self):
        try:
            change = False
            while True:
                cle, quand, ms = self.file_suivi.get_nowait()
                s_ = self.suivi.get(cle)
                if not s_:
                    continue
                change = True
                s_["pts"].append(ms)
                if ms is None and s_["perte_t0"] is None:
                    s_["perte_t0"] = quand
                elif ms is not None and s_["perte_t0"] is not None:
                    duree = max(0.5, quand - s_["perte_t0"])
                    s_["pertes"].append((s_["perte_t0"], duree))
                    s_["perte_t0"] = None
                    noter_evenement("avert", tk_("evt_micro" if duree < 3 else "evt_coupure", duree=duree_precise(duree),
                                                 nom=s_["nom"], ip=s_["ip"]))
        except queue.Empty:
            pass
        except Exception as e:  # noqa: BLE001
            print("suivi :", repr(e), file=sys.stderr)
        self.after(500, self.suivi_poll)

    # ----- « Identifier » : ping rapide + gros voyant, pour repérer quel câble débrancher -----
    def identifier(self, cle):
        ip = self.ip_appareil_cle(cle)
        if not ip:
            return
        nom = self.nom_appareil_cle(cle) or ip
        self.ident_fermer()
        stop = threading.Event()
        q = queue.Queue()
        device = self.mon_data.get("device") or ""

        def boucle():
            while not stop.is_set():
                t0 = time.time()
                ms = _ping_un(ip, device)
                if stop.is_set():
                    break
                q.put(ms)
                stop.wait(max(0.02, 0.4 - (time.time() - t0)))
        threading.Thread(target=boucle, daemon=True).start()
        fen = tk.Toplevel(self)
        fen.title(t("ident_titre"))
        fen.configure(bg=CREME)
        fen.resizable(False, False)
        tk.Label(fen, text=f"{nom}\n{ip}", font=(F_TITRE, 22), fg=ENCRE, bg=CREME, pady=10).pack(padx=24)
        voyant = tk.Label(fen, text=t("ident_attente"), font=(F_TITRE, 30), fg=CLAIR, bg=GRIS_TEXTE, width=18, pady=18)
        voyant.pack(padx=24, pady=4)
        EtiquetteSerree(fen, text=t("ident_expl"), font=(F_TEXTE, 15), fg=VIOLET, bg=CREME, wraplength=440,
                 justify="center").pack(padx=24, pady=8)
        son = tk.BooleanVar(value=False)
        tk.Checkbutton(fen, text=t("ident_son"), variable=son, font=(F_TEXTE, 13), fg=ENCRE, bg=CREME,
                       activebackground=CREME, wraplength=440).pack(padx=24)
        tk.Button(fen, text=t("ident_fermer"), command=self.ident_fermer).pack(pady=12)
        fen.protocol("WM_DELETE_WINDOW", self.ident_fermer)
        self._ident = {"stop": stop, "q": q, "fen": fen, "voyant": voyant, "son": son, "etat": None}
        self.jouer("pop")
        self.ident_poll()

    def ident_poll(self):
        i = self._ident
        if not i:
            return
        try:
            dernier, recu = None, False
            while True:
                dernier = i["q"].get_nowait()
                recu = True
        except queue.Empty:
            pass
        if recu:
            etat = dernier is not None
            if etat != i["etat"]:
                if i["etat"] is True and not etat and i["son"].get():
                    self.jouer("triste")
                i["etat"] = etat
            if etat:
                i["voyant"].configure(text=t("ident_ok", ms=f"{dernier:.1f} ms"), bg=VERT_OK)
            else:
                i["voyant"].configure(text=t("ident_ko"), bg=ERREUR)
        self.after(150, self.ident_poll)

    def ident_fermer(self):
        i = getattr(self, "_ident", None)
        self._ident = None
        if not i:
            return
        i["stop"].set()
        try:
            i["fen"].destroy()
        except Exception:
            journal_exc()

    def suivi_pastille(self, x, y, tags):
        """Petite pastille rose sur les appareils surveillés de près."""
        self.cv.create_oval(x - 6.5, y - 6.5, x + 6.5, y + 6.5, fill=ROSE, outline=NOIR, width=2, tags=tags)
        self.cv.create_oval(x - 2, y - 2, x + 2, y + 2, fill=NOIR, outline="", tags=tags)

    # ----- vitesse de la liaison (badge dans la barre « réglages du profil ») -----
    def vitesse_poll(self):
        try:
            v = self._vit
            if not v["en_cours"] and self.onglet == "config" and self.ui_prete:
                service = self.v_interface.get().strip()
                v["en_cours"] = True

                def travail():
                    try:
                        dev = periphérique_de(service) if service else ""
                        mbs = vitesse_liaison(dev)
                    except Exception:  # noqa: BLE001
                        mbs = None
                    v["suite"] = (service, mbs)
                    v["en_cours"] = False
                threading.Thread(target=travail, daemon=True).start()
            suite = v.pop("suite", None)
            if suite and suite != (v["service"], v["valeur"]):
                v["service"], v["valeur"] = suite
                self.vitesse_dessiner()
        except Exception as e:  # noqa: BLE001
            print("vitesse :", repr(e), file=sys.stderr)
        self.after(3000, self.vitesse_poll)

    def vitesse_dessiner(self):
        cv = self.cv
        cv.delete("vitesse")
        if self.onglet != "config":
            return
        mbs = getattr(self, "_vit", {}).get("valeur")
        texte = texte_vitesse(mbs)
        if not texte:
            return
        fond = (self.OK_FOND if mbs >= 1000 else "#FFD9A0" if mbs >= 100 else "#FFB3A8" if mbs > 0 else CREME_GRIS)
        xc = 960
        yc = self.centre_barre(355, 150, 1050, 600, 0.35, xc)
        tag = ("vitesse",)
        cv.create_polygon(contour(xc - 82, yc - 10, xc + 82, yc + 10, 8, 701, 0.5, 60), smooth=True, fill=fond,
                          outline=NOIR, width=2, joinstyle="round", tags=tag)
        tx = cv.create_text(xc, yc - 1.5, text=texte, font=(F_SAISIE, 13), fill=CLAIR if mbs >= 1000 else ENCRE, tags=tag)
        self.ajuster(tx, F_SAISIE, 13, 150, mini=9)

    def app_double_clic(self, e, cle, y):
        """Double-clic sur le nom ou sur la note d'un appareil : on écrit directement dans la case."""
        x = (e.x - getattr(self.cv, "ox", 0.0)) / (getattr(self.cv, "k", 1.0) or 1.0)
        self.mon_data["app_sel"] = cle
        self.mon_data["app_set"] = {cle}
        self.mon_data["app_ancre"] = cle
        if x < 305:
            self.app_editer(cle, "nom", 84, 300, y)
        elif x >= 785:
            self.app_editer(cle, "note", 788, 1032, y)

    def app_editer_fin(self, valider):
        ed = getattr(self, "_edit", None)
        if not ed:
            return
        self._edit = None
        entree, fen, cle, champ = ed
        valeur = entree.get() if valider else None
        try:
            self.cv.delete(fen)
            entree.destroy()
        except Exception:
            journal_exc()
        if valeur is None or cle not in self.inv:
            if self.onglet == "appareils":
                self.app_dessiner_dyn()
            return
        if champ == "nom":
            memoriser_nom(cle, valeur)
            a = self.mon_data["app"].get(cle)
            if a is not None:
                a["nom"] = valeur.strip()
            self.inv[cle]["nom"] = valeur.strip()
            sauver_inventaire(self.inv)
        else:
            self.inv[cle]["note"] = valeur.strip()
            sauver_inventaire(self.inv)
        if self.onglet == "appareils":
            self.app_dessiner_dyn()

    def app_editer(self, cle, champ, x1, x2, y):
        self.app_editer_fin(True)
        self.cv.delete("app_dyn_edit")
        noms = noms_memorises()
        a = self.inv.get(cle, {})
        actuel = (noms.get(cle, "") or a.get("nom", "")) if champ == "nom" else a.get("note", "")
        entree = tk.Entry(self.parent_widgets(), bg=CREME_CLAIR, fg=ENCRE, relief="flat", bd=0, highlightthickness=2,
                          highlightbackground=ROSE, highlightcolor=ROUGE, insertbackground=ROUGE,
                          font=(F_TEXTE, max(1, int(round(17 * getattr(self.cv, "k", 1.0))))),
                          selectbackground=LILAS_CLAIR, selectforeground=ENCRE)
        entree.insert(0, actuel)
        fen = self.cv.create_window(x1, y + 2, window=entree, anchor="nw", width=x2 - x1, height=29)
        self._edit = (entree, fen, cle, champ)
        entree.bind("<Return>", lambda e: self.app_editer_fin(True))
        entree.bind("<KP_Enter>", lambda e: self.app_editer_fin(True))
        entree.bind("<Escape>", lambda e: self.app_editer_fin(False))
        entree.bind("<FocusOut>", lambda e: self.after(1, lambda: self.app_editer_fin(True)))
        entree.focus_set()
        entree.select_range(0, "end")

    def app_renommer(self):
        from tkinter import simpledialog
        k = self.mon_data.get("app_sel")
        if k not in self.inv:
            return
        nom = simpledialog.askstring("IP Pilot", t("mon_nom_q"), initialvalue=noms_memorises().get(k, ""), parent=self)
        if nom is None:
            return
        memoriser_nom(k, nom)
        a = self.mon_data["app"].get(k)
        if a is not None:
            a["nom"] = nom.strip()
        self.app_dessiner_dyn()

    def app_note(self):
        from tkinter import simpledialog
        k = self.mon_data.get("app_sel")
        if k not in self.inv:
            return
        note = simpledialog.askstring("IP Pilot", t("app_note_q"), initialvalue=self.inv[k].get("note", ""), parent=self)
        if note is None:
            return
        self.inv[k]["note"] = note.strip()
        sauver_inventaire(self.inv)
        self.app_dessiner_dyn()

    def app_oublier_un(self, cle):
        d = self.mon_data
        d["app_sel"] = cle
        d["app_set"] = {cle}
        d["app_ancre"] = cle
        self.app_oublier()

    def app_oublier(self):
        d = self.mon_data
        cles = [k for k in d.get("app_set", set()) if k in self.inv] or ([d["app_sel"]] if d.get("app_sel") in self.inv else [])
        if not cles:
            return
        q = t("app_oublier_q") if len(cles) == 1 else t("app_oublier_n", n=len(cles))
        if not messagebox.askyesno("IP Pilot", q, parent=self):
            return
        for k in cles:
            self.inv.pop(k, None)
            d["app"].pop(k, None)
        d["app_set"] = set()
        sauver_inventaire(self.inv)
        self.app_dessiner_dyn()

    def app_exporter(self, fmt="csv"):
        from tkinter import filedialog
        if not self.inv:
            messagebox.showinfo("IP Pilot", t("app_vide"))
            return
        chemin = filedialog.asksaveasfilename(defaultextension="." + fmt, filetypes=[(fmt.upper(), "*." + fmt)],
                                              initialfile=time.strftime("appareils_%Y-%m-%d." + fmt),
                                              title=t("app_export"))
        if not chemin:
            return
        try:
            n = (exporter_inventaire_pdf if fmt == "pdf" else exporter_inventaire_csv)(chemin, self.inv)
        except OSError as e:
            messagebox.showwarning("IP Pilot", str(e))
            return
        self.set_bulle("export_ok", n=n)

    # ===== surveillance du réseau, historique, export =====
    INTERVALLE_SURV = 15          # secondes entre deux vérifications

    def surv_actif(self):
        th = getattr(self, "_surv_thread", None)
        return bool(th and th.is_alive() and not self._surv_stop.is_set())

    def carte_auto(self):
        """Carte à surveiller quand l'utilisateur n'en a pas choisi : celle du profil courant si elle a une IP,
        sinon la première carte qui en a une."""
        try:
            courante = self.ifaces[self.i_cour].get("interface", "")
        except Exception:
            courante = ""
        try:
            autres = lister_services()
        except Exception:
            autres = []
        for s_ in [courante] + list(autres):
            if s_:
                dev = periphérique_de(s_)
                if dev and adresse_de_carte(dev)[0]:
                    return s_
        return courante

    def surv_demarrer(self, carte, silencieux=False):
        if self.surv_actif():
            return
        self._surv_stop = threading.Event()
        self._surv_etat = {}
        self._surv_en_erreur = False
        self._surv_force = threading.Event()
        stop, etat, force = self._surv_stop, self._surv_etat, self._surv_force

        def boucle():
            """Deux rythmes : un « ping » rapide (toutes les 2 s) sur les appareils déjà connus pour repérer
            une panne en quelques secondes, et un scan complet toutes les 15 s pour repérer les nouveaux."""
            from concurrent.futures import ThreadPoolExecutor
            n = 0
            dernier_complet = 0.0
            duree_scan = 0.0
            connus = {}            # clé -> appareil, tous ceux vus depuis le début (pour détecter leur retour)
            vus_complet = set()
            dernier = None
            cache = self._cache_hotes
            ecoute = EcouteAnnonces(self._reveil_annonce, lambda: self.__dict__.get("_ips_connues", ()))
            while not stop.is_set():
                if getattr(self, "occupe", False):
                    stop.wait(1.0)
                    continue
                try:
                    if dernier is None or force.is_set() or time.time() - dernier_complet >= max(perf()[0], 2 * duree_scan):
                        force.clear()
                        t_scan = time.time()
                        r = scanner_reseau(carte or self.carte_auto(), attendus=self.ips_suivies(), annuler=stop.is_set, cache_hotes=cache,
                                           rapide=bool(self.__dict__.pop("_rapide_scan", False)),
                                           partiel=lambda p: self.file_surv.put((p, None)))
                        dernier_complet = time.time()
                        duree_scan = dernier_complet - t_scan      # un grand réseau (1000 adresses) : on espace les scans
                        if r["ok"]:
                            if dernier is not None and dernier["reseau"] != r["reseau"]:
                                connus.clear()
                            if r.get("device") and time.time() - self.__dict__.get("_conf_t", 0) > 100:
                                self._conf_t = time.time()
                                r["conflits_sys"] = conflits_systeme(r["device"], r["ip"])
                            for d in r["trouves"]:
                                connus[cle_appareil(d)] = d
                            vus_complet = {cle_appareil(d) for d in r["trouves"]}
                            dernier = r
                            self._ips_connues = {d["ip"] for d in r["trouves"]}
                            ecoute.regler(r["ip"], r["reseau"])
                        n += 1
                    elif dernier is not None:
                        dev = dernier.get("device", "")
                        # on tente aussi les appareils « muets » du dernier scan : s'ils répondent à un ping, ils passent
                        # en appareils mesurables (et alimentent les graphiques sans « surveiller en continu »)
                        pingables = [d for d in connus.values() if d["ms"] is not None]
                        muets = [d for k, d in connus.items() if d["ms"] is None and k in vus_complet]
                        essais = pingables + muets
                        with ThreadPoolExecutor(max_workers=max(1, min(perf()[2], len(essais)))) as pool:
                            temps = list(pool.map(lambda d: _ping_un(d["ip"], dev), essais))
                        presents = [dict(d, ms=ms) for d, ms in zip(pingables, temps) if ms is not None]
                        passifs = []
                        for d, ms in zip(muets, temps[len(pingables):]):
                            if ms is not None:
                                d["ms"] = ms
                                presents.append(dict(d, ms=ms))
                            else:
                                passifs.append(d)
                        presents += passifs
                        r = dict(dernier, trouves=sorted(presents, key=lambda d: tuple(int(x) for x in d["ip"].split("."))),
                                 rapide=True)
                        r.pop("conflits_sys", None)
                        r.pop("absents_confirmes", None)
                    else:
                        r = {"ok": False, "erreur": "pas_d_ip"}
                except Exception as e:  # noqa: BLE001
                    r = {"ok": False, "erreur": str(e)}
                if r.get("ok") and not stop.is_set():
                    try:
                        # un appareil qui manque : on le re-sonde tout de suite (ping, puis ARP) avant de le déclarer perdu
                        vus_k = {cle_appareil(d) for d in r["trouves"]}
                        suivis = etat.get("appareils", {})
                        absents = [(k, d, bool(suivis[k].get("repond"))) for k, d in connus.items()
                                   if k in suivis and not suivis[k].get("perdu") and k not in vus_k]
                        if absents:
                            verdict = verifier_absents(absents, r.get("device", ""), r.get("ip", ""), stop.is_set)
                            retrouves, confirmes = [], []
                            for k, d, _ in absents:
                                v = verdict.get(k)
                                if v is None:
                                    confirmes.append(k)
                                else:
                                    retrouves.append(dict(d, ms=v if v != "arp" else None))
                            r = dict(r, absents_confirmes=confirmes,
                                     trouves=sorted(r["trouves"] + retrouves,
                                                    key=lambda d: tuple(int(x) for x in d["ip"].split("."))))
                    except Exception:  # noqa: BLE001
                        journal_exc()
                self.file_surv.put((r, etat))
                fin_att = time.time() + perf()[1]          # attente interrompue si on clique sur « actualiser »
                while not stop.is_set() and not force.is_set() and time.time() < fin_att:
                    stop.wait(0.15)
            ecoute.arreter()
        self._surv_thread = threading.Thread(target=boucle, daemon=True)
        self._surv_thread.start()
        sauver_reglage(surveillance=True, surv_carte=carte or "")
        if not silencieux:
            self.set_bulle("surv_on")
        self.menu_surv_maj()

    def _reveil_annonce(self):
        """Un appareil inconnu vient de s'annoncer sur le réseau : on relance un scan rapide tout de suite."""
        f = self.__dict__.get("_surv_force")
        if f is not None and self.surv_actif():
            self._rapide_scan = True
            f.set()

    def surv_arreter(self):
        if getattr(self, "_surv_stop", None):
            self._surv_stop.set()
        self._surv_thread = None
        sauver_reglage(surveillance=False)
        self.menu_surv_maj()

    def basculer_surv(self, carte=None):
        """Allume ou éteint la surveillance. Renvoie True si elle est maintenant allumée."""
        if self.surv_actif():
            self.surv_arreter()
            noter_evenement("info", tk_("evt_surv_fin"))
            self.set_bulle("surv_off")
            return False
        self.surv_demarrer(carte or self.surv_carte_reglee() or None)
        return True

    def menu_surv(self):
        self.basculer_surv()

    def menu_surv_maj(self):
        try:
            self._var_surv.set(self.surv_actif())
        except Exception:
            journal_exc()

    def surv_poll(self):
        try:
            while True:
                r, etat = self.file_surv.get_nowait()
                if r.get("partiel"):
                    self.scan_partiel_traiter(r)
                elif etat is None:
                    self.scan_unique_traiter(r)
                elif etat is getattr(self, "_surv_etat", None) and self.surv_actif():
                    self.surv_traiter(r, etat)
        except queue.Empty:
            pass
        except Exception as e:  # noqa: BLE001
            print("surveillance :", repr(e), file=sys.stderr)
        try:
            self.mon_maj()
        except Exception as e:  # noqa: BLE001
            print("monitoring :", repr(e), file=sys.stderr)
        self.after(1000, self.surv_poll)

    def surv_traiter(self, r, etat):
        """Un scan de surveillance est arrivé : on note ce qui a changé et la mascotte le dit dans sa bulle."""
        if not r.get("ok"):
            if not self._surv_en_erreur:
                self._surv_en_erreur = True
                txt = t("scan_pas_ip") if r.get("erreur") == "pas_d_ip" else str(r.get("erreur"))
                noter_evenement("erreur", tk_("evt_scan_erreur", e=txt))
            return
        self._surv_en_erreur = False
        self.dernier_scan = r
        if etat.get("reseau") not in (None, r["reseau"]):      # on a changé de réseau : on repart de zéro
            etat.clear()
        etat["reseau"] = r["reseau"]
        noms = noms_memorises()
        etiquettes = etat.setdefault("etiquettes", {})
        for d in r["trouves"]:
            nom = nom_appareil(d, noms)
            etiquettes[cle_appareil(d)] = f"{nom} ({d['ip']})" if nom else d["ip"]
        premier = not etat.get("init")
        evts = suivre_changements(etat, r["trouves"], confirmes=set(r.get("absents_confirmes", ())))
        if premier:
            noter_evenement("info", tk_("evt_surv_debut", n=len(r["trouves"])))
        perdus, autres, conflits = [], [], []
        for genre, e in evts:
            nom = etiquettes.get(e.get("cle"), e.get("ip", ""))
            if genre == "deconnexion":
                perdus.append(nom)
                noter_evenement("deconnexion", tk_("evt_perdu", nom=nom))
            elif genre == "connexion":
                if e["nouveau"]:
                    noter_evenement("connexion", tk_("evt_nouveau", nom=nom, mac=e["mac"]))
                    autres.append(t("surv_nouveau", nom=nom))
                else:
                    noter_evenement("connexion", tk_("evt_retour", nom=nom))
                    autres.append(t("surv_retour", nom=nom))
            elif genre == "conflit":
                noter_evenement("conflit", tk_("evt_conflit", ip=e["ip"], ancien=e["ancien"], nouveau=e["nouveau"]))
                conflits.append(e["ip"])
        if conflits_ou_mac_change(evts):
            self.mon_data["conflit_t"] = time.time()
        self.mon_integrer(r, etat)
        self.mon_purger(r)
        vus = etat.setdefault("conflits_sys", set())
        for mac in r.get("conflits_sys", []):
            if mac not in vus:
                vus.add(mac)
                noter_evenement("conflit", tk_("evt_conflit_sys", mac=mac, ip=r["ip"]))
                conflits.append(r["ip"])
                self.mon_data["conflit_t"] = time.time()
        if perdus:
            if len(perdus) == 1:
                self.set_bulle("surv_perdu", nom=perdus[0])
            else:
                reste = len(perdus) - 3          # la bulle est petite : trois noms au plus, puis « … +N »
                self.set_bulle("surv_perdus", n=len(perdus),
                               nom=", ".join(perdus[:3]) + (f" … +{reste}" if reste > 0 else ""))
            self.jouer("triste")
        elif conflits:
            self.set_bulle("surv_conflit", ip=conflits[0])
        elif autres and not premier:
            self.cv.itemconfigure(self.t_bulle, text=autres[0])
            self.cle_bulle, self.kw_bulle = "accueil", {}     # phrase déjà composée : à la reconstruction, retour à l'accueil
            self.ajuster(self.t_bulle, F_TEXTE, 27, self.bulle_zone[0], self.bulle_zone[1])

    def ouvrir_historique(self):
        """Grande fenêtre de lecture de l'historique du réseau (même contenu que le petit panneau du Monitor)."""
        try:
            fen = getattr(self, "_fen_histo_grand", None)
            if fen is not None and fen.winfo_exists():
                fen.deiconify()
                fen.lift()
                return
        except Exception:  # noqa: BLE001
            journal_exc()
        try:
            self._fen_histo_grand = fenetre_historique_grand(self)
        except Exception as e:  # noqa: BLE001
            self._fen_histo_grand = None
            print("historique :", repr(e), file=sys.stderr)

    def fermer_app(self, *_):
        """Fermeture de la fenêtre principale (croix rouge ou Cmd+Q) : on arrête proprement ce qui tourne, puis le
        processus s'arrête pour de bon (filet de sécurité de 2 s si une tâche de fond bloquait)."""
        if self.__dict__.get("_ferme"):
            return
        self._ferme = True
        try:
            for n_ in PROTOS + ("midi", "dante"):
                self.proto_arreter(n_)
        except Exception:  # noqa: BLE001
            journal_exc()
        try:
            if getattr(self, "_surv_stop", None):
                self._surv_stop.set()              # (sans toucher au réglage : la surveillance repartira au prochain lancement)
        except Exception:  # noqa: BLE001
            journal_exc()
        t_ = threading.Timer(2.0, sortie_nette)
        t_.daemon = True
        t_.start()
        try:
            self.destroy()
        except Exception:  # noqa: BLE001
            sortie_nette()

    def _echap(self, e):
        """Échap ferme la fenêtre secondaire (pop-up) qui a le focus ; sans effet sur la fenêtre principale."""
        try:
            if self.cv.find_withtag("bulle_aide"):
                self.bulle_aide_fermer()
                return
            tl = e.widget.winfo_toplevel()
            if tl is self or not isinstance(tl, tk.Toplevel):
                return
            cmd = tl.protocol("WM_DELETE_WINDOW")
            if cmd:
                tl.tk.call(cmd)
            else:
                tl.destroy()
        except Exception:  # noqa: BLE001
            journal_exc()

    def profil_deselectionner(self):
        """L'IP a changé en dehors d'un profil (« Me mettre ici ») : plus aucun profil n'est en cours."""
        self.index = None
        self.dernier = ""
        ecrire_dernier("")
        self.rafraichir_liste()

